INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3e80ad5b-1069-4926-9503-42854e8c25ae', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'btn-toggle', 'BtnToggle', 'Form & Input', NULL, 'mdi-toggle-switch-outline', 'components.catalog.btn_toggle.description', 'Single or multi-select toggle group of Btn elements. Wraps OrigamBtnGroup and adds selection state via useGroup (supports v-model).', NULL, NULL, 'origam-btn-toggle', NULL, 'packages/ds/src/components/Btn/OrigamBtnToggle.vue', 'origam', NULL, NULL, '/stories/?story=components-btn--design', '/docs/components/Btn/OrigamBtn.html', 'btn', '{"a11y": {"notes": [{"noteKey": "components.btn_toggle.a11y.role_group", "noteFallback": "Inherits role=\"group\" from OrigamBtnGroup. Add aria-label to describe the toggle purpose (e.g. \"Text alignment controls\")."}, {"noteKey": "components.btn_toggle.a11y.aria_pressed", "noteFallback": "Each selected child OrigamBtn should communicate its state via aria-pressed=\"true\". Ensure child buttons pass their active state correctly."}, {"noteKey": "components.btn_toggle.a11y.mandatory", "noteFallback": "When mandatory=true, at least one button is always selected. Consider communicating this constraint to assistive technology users via group description."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.btn_toggle.a11y.key_tab", "actionFallback": "Moves focus through each toggle button."}, {"key": "Enter / Space", "actionKey": "components.btn_toggle.a11y.key_activate", "actionFallback": "Toggles the selection state of the focused button."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-btn-group---border-radius", "descriptionKey": "components.btn_toggle.tokens.border_radius", "descriptionFallback": "Default border radius for the toggle container."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"20\" width=\"620\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"50\" y=\"30\" width=\"600\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.8))\"/>\n  <text x=\"145\" y=\"64\" font-size=\"11\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">selected</text>\n  <rect x=\"230\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"315\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">unselected</text>\n  <rect x=\"400\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"485\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">unselected</text>\n  <circle cx=\"48\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"58\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"58\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"68\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"68\" y=\"44.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"58\" y1=\"26\" x2=\"120\" y2=\"8\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"124\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-btn-toggle</text>\n", "code": "<!-- root: thin wrapper, adds .origam-btn-toggle class -->\n<origam-btn-group class=\"origam-btn-toggle\" v-bind=\"btnGroupProps\">\n  <template #default>\n    <!-- default slot exposes group navigation API -->\n    <slot v-bind=\"{ items, isSelected, next, prev, select, selected }\" />\n  </template>\n  <template #item=\"{ item, index }\">\n    <slot name=\"item\" v-bind=\"{ item, index }\" />\n  </template>\n</origam-btn-group>", "legend": [{"cls": ".origam-btn-toggle", "num": 1, "descriptionKey": "components.btn_toggle.anatomy.root", "descriptionFallback": "Root modifier class added on top of <code>.origam-btn-group</code>. OrigamBtnToggle is a thin wrapper that adds selection state (useGroup) and exposes the group navigation API (next/prev/select)."}, {"cls": ".origam-btn-group", "num": 2, "descriptionKey": "components.btn_toggle.anatomy.group", "descriptionFallback": "The proxied <code>&lt;origam-btn-group&gt;</code> with all group-level props forwarded via filterProps. Provides the visual container (border, elevation, rounded, overflow: hidden)."}, {"cls": "(origam-btn children)", "num": 3, "descriptionKey": "components.btn_toggle.anatomy.children", "descriptionFallback": "Child <code>&lt;origam-btn&gt;</code> elements with a <code>value</code> prop. isSelected state from useGroup drives the active styling on the matching button."}], "classes": [{"cls": "origam-btn-toggle", "descriptionKey": "components.btn_toggle.anatomy.root", "descriptionFallback": "Root class added alongside origam-btn-group. No additional styles — purely a BEM identifier for the toggle variant."}], "svgDesc": "Schematic of the BtnToggle component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamBtnToggle", "rootClass": "origam-btn-toggle", "figcaption": "Anatomy of <code>&lt;origam-btn-toggle&gt;</code> — outer toggle shell ① (adds <code>.origam-btn-toggle</code> modifier), inner <code>&lt;origam-btn-group&gt;</code> ② rendering child buttons ③. Selected button receives active state from useGroup.", "svgViewBox": "0 0 700 120"}, "cssVars": [{"name": "--origam-btn-group---border-radius", "defaultValue": "4px", "descriptionKey": "components.btn_toggle.css_vars.border_radius", "descriptionFallback": "Inherited from BtnGroup. Border-radius of the toggle container."}, {"name": "--origam-btn-group---density", "defaultValue": "0px", "descriptionKey": "components.btn_toggle.css_vars.density", "descriptionFallback": "Inherited from BtnGroup. Density offset for min-height."}], "exposed": [{"name": "next", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.next", "descriptionFallback": "Selects the next button in the group (wraps around)."}, {"name": "prev", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.prev", "descriptionFallback": "Selects the previous button in the group (wraps around)."}, {"name": "select", "type": "(id: string | number, value: boolean) => void", "descriptionKey": "components.btn_toggle.exposed.select", "descriptionFallback": "Programmatically select or deselect a button by its value id."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.btn_toggle.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.btn_toggle.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed btnToggleStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.btn_toggle.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.btn_toggle.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "multiple", "labelKey": "components.btn_toggle.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "mandatory", "labelKey": "components.btn_toggle.playground.mandatory", "defaultValue": false, "labelFallback": "Mandatory"}, {"kind": "switch", "prop": "divided", "labelKey": "components.btn_toggle.playground.divided", "defaultValue": false, "labelFallback": "Divided"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.btn_toggle.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "border", "labelKey": "components.btn_toggle.playground.border", "defaultValue": true, "labelFallback": "Border"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "pill", "value": "pill"}], "labelKey": "components.btn_toggle.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('410352aa-c9d7-4dd6-a5c6-995d82e78558', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'calendar', 'Calendar', 'Data Display', NULL, 'mdi-calendar', 'components.catalog.calendar.description', 'Full-featured calendar with month, week, day and agenda views, drag-select, event colouring by category and v-model bindings.', NULL, NULL, 'origam-calendar', NULL, 'packages/ds/src/components/Calendar/OrigamCalendar.vue', 'origam', NULL, NULL, '/stories/?story=components-calendar--design', '/docs/components/Calendar/OrigamCalendar.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.calendar.a11y.application_role", "noteFallback": "role=\"application\" is used on the root to indicate rich interactive content to assistive technologies. The @keydown handler manages arrow navigation."}, {"noteKey": "components.calendar.a11y.grid_semantics", "noteFallback": "Month view uses role=\"grid\" / role=\"row\" / role=\"gridcell\" for full grid semantics. Week numbers use role=\"rowheader\"."}, {"noteKey": "components.calendar.a11y.event_aria_label", "noteFallback": "Each event button has an aria-label describing the event title and time range."}, {"noteKey": "components.calendar.a11y.disabled_dates", "noteFallback": "Disabled day cells receive aria-disabled=\"true\". Drag-select is prevented on disabled cells."}, {"noteKey": "components.calendar.a11y.today_cell", "noteFallback": "Today''s cell is identified visually with a primary background tint. Consumers should add aria-label=\"Today\" via the #day slot for full AT support."}], "roles": ["application", "toolb