ba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"300\" y=\"58\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Body text or #default slot content</text>\n  <text x=\"300\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"sans-serif\" opacity=\"0.7\">font-size: 0.875rem · flex: 1 1 auto</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"44\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"26\" x2=\"90\" y2=\"8\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-card-text</text>\n", "code": "<!-- root: <div> by default, customisable via tag prop -->\n<div class=\"origam-card-text\">\n  <slot name=\"default\">\n    <span>{{ text }}</span>\n  </slot>\n</div>", "legend": [{"cls": ".origam-card-text", "num": 1, "descriptionKey": "components.card_text.anatomy.root", "descriptionFallback": "Root element (default: <code>&lt;div&gt;</code>). flex: 1 1 auto so it fills available card height. font-size: 0.875rem, font-weight: 400. Padding is density-adjusted."}, {"cls": "(content / #default slot)", "num": 2, "descriptionKey": "components.card_text.anatomy.content", "descriptionFallback": "Inner content: renders <code>&lt;span&gt;{{ text }}&lt;/span&gt;</code> when the text prop is provided, or the #default slot for richer content."}], "classes": [{"cls": "origam-card-text", "descriptionKey": "components.card_text.anatomy.root", "descriptionFallback": "Root element. flex: 1 1 auto, body typography, density-aware padding on all sides."}, {"cls": "origam-card-text--density-default", "descriptionKey": "components.card_text.anatomy.density_default", "descriptionFallback": "Density default (0px offset)."}, {"cls": "origam-card-text--density-compact", "descriptionKey": "components.card_text.anatomy.density_compact", "descriptionFallback": "Density compact (−8px offset on all padding sides)."}, {"cls": "origam-card-text--density-comfortable", "descriptionKey": "components.card_text.anatomy.density_comfortable", "descriptionFallback": "Density comfortable (+8px offset on all padding sides)."}], "svgDesc": "Schematic of the CardText component with 2 numbered parts.", "svgTitle": "Anatomy of OrigamCardText", "rootClass": "origam-card-text", "figcaption": "Anatomy of <code>&lt;origam-card-text&gt;</code> — root container ① (flex: 1 1 auto) with density-aware padding ② wrapping the body text or <code>#default</code> slot.", "svgViewBox": "0 0 600 120"}, "cssVars": [{"name": "--origam-card-text---flex", "defaultValue": "1 1 auto", "descriptionKey": "components.card_text.css_vars.flex", "descriptionFallback": "Flex grow/shrink/basis for the text area. 1 1 auto ensures it fills available vertical space."}, {"name": "--origam-card-text---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.card_text.css_vars.font_size", "descriptionFallback": "Body text font size (0.875rem = 14px)."}, {"name": "--origam-card-text---font-weight", "defaultValue": "400", "descriptionKey": "components.card_text.css_vars.font_weight", "descriptionFallback": "Body text font weight (normal)."}, {"name": "--origam-card-text---letter-spacing", "defaultValue": "0.0178571429em", "descriptionKey": "components.card_text.css_vars.letter_spacing", 