INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('39dd6a04-9b92-4395-b924-b50a41beb3e3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'carousel', 'Carousel', 'Data Display', NULL, 'mdi-view-carousel', 'components.catalog.carousel.description', 'Sliding window component for cycling through a set of items, with pagination dots, optional progress bar, auto-play interval and keyboard navigation.', NULL, NULL, 'origam-carousel', NULL, 'packages/ds/src/components/Carousel/OrigamCarousel.vue', 'origam', NULL, NULL, '/stories/?story=components-carousel--design', '/docs/components/Carousel/OrigamCarousel.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.carousel.a11y.delimiter_label", "noteFallback": "Each pagination dot receives aria-label=\"Slide N of M\" via useLocale t() — screen readers announce position."}, {"noteKey": "components.carousel.a11y.reduced_motion", "noteFallback": "Auto-play is suppressed when prefers-reduced-motion: reduce is detected (prefersReducedMotion() check on mount)."}, {"noteKey": "components.carousel.a11y.pause_on_focus", "noteFallback": "The slide timer is cleared on unmount and restarted on modelValue change, but there is no explicit pause-on-focus — consider disabling cycle for keyboard-heavy contexts."}], "roles": ["region"], "keyboard": [{"key": "ArrowLeft / ArrowRight", "actionKey": "components.carousel.a11y.key_arrows", "actionFallback": "Navigates to the previous or next slide when focused on the carousel."}, {"key": "Tab", "actionKey": "components.carousel.a11y.key_tab", "actionFallback": "Moves focus through pagination dots and navigation arrows."}, {"key": "Enter / Space", "actionKey": "components.carousel.a11y.key_activate", "actionFallback": "Activates the focused pagination dot or arrow button."}]}, "tokens": {"excerpt": [{"type": "color", "value": "rgba(0, 0, 0, 0.4)", "tokenPath": "--origam-carousel__controls---background-color", "descriptionKey": "components.carousel.tokens.controls_bg", "descriptionFallback": "Dot strip background. Transparent when hideDelimiterBackground=true."}, {"type": "dimension", "value": "50px", "tokenPath": "--origam-carousel__controls---height", "descriptionKey": "components.carousel.tokens.controls_height", "descriptionFallback": "Height of the pagination dot strip."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-carousel__controls-item---opacity", "descriptionKey": "components.carousel.tokens.dot_opacity", "descriptionFallback": "Icon opacity inside inactive dots."}, {"type": "number", "value": "var(--origam-opacity---100)", "tokenPath": "--origam-carousel__controls-item---opacity-active", "descriptionKey": "components.carousel.tokens.dot_opacity_active", "descriptionFallback": "Icon opacity inside the active dot."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-carousel---transition-duration", "descriptionKey": "components.carousel.tokens.transition_duration", "descriptionFallback": "Slide transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"108\" font-size=\"13\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Slide content (#default slot)</text>\n  <rect x=\"20\" y=\"160\" width=\"660\" height=\"20\" rx=\"0\" fill=\"rgba(0,0,0,0.38)\"/>\n  <circle cx=\"320\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"340\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"360\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <rect x=\"20\" y=\"20\" width=\"32\" height=\"160\" rx=\"4\" fill=\"rgba(0,0,0,0.18)\"/>\n  <text x=\"36\" y=\"105\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">‹</text>\n  <rect x=\"648\" y=\"20\" width=\"32\" height=\"160\" rx=\"4\" fill=\"rgba(0,0,0,0.18)\"/>\n  <text x=\"664\" y=\"105\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">›</text>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.7\"/>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"28\" cy=\"164\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"28\" y=\"168\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"340\" cy=\"164\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"340\" y=\"168\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"36\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"36\" y=\"36\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"28\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"220\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑤ progress bar is absolutely positioned at top; ② controls strip sits at bottom</text>\n", "code": "<!-- root wraps OrigamWindow -->\n<origam-window class=\"origam-carousel\">\n  <!-- slide items projected here -->\n  <slot name=\"default\" />\n\n  <!-- additional content: dots + progress -->\n  <template #additional>\n    <!-- pagination dots (hidden when hideDelimiters) -->\n    <div class=\"origam-carousel__controls\">\n      <origam-btn\n        v-for=\"(item, index) in items\"\n        :key=\"index\"\n        class=\"origam-carousel__controls-item\"\n      />\n    </div>\n\n    <!-- progress bar (visible when progress=true) -->\n    <div class=\"origam-carousel__progress\">\n      <origam-progress-linear :model-value=\"progressPercent\" />\n    </div>\n  </template>\n</origam-window>", "legend": [{"cls": ".origam-carousel", "num": 1, "descriptionKey": "components.carousel.anatomy.root", "descriptionFallback": "Root element. Delegates slide rendering to an inner OrigamWindow."}, {"cls": ".origam-carousel__controls", "num": 2, "descriptionKey": "components.carousel.anatomy.controls", "descriptionFallback": "Absolute strip at the bottom. Contains the delimiter (dot) buttons. Hidden when hideDelimiters=true."}, {"cls": ".origam-carousel__controls-item", "num": 3, "descriptionKey": "components.carousel.anatomy.controls_item", "descriptionFallback": "One pagination dot — an OrigamBtn rendered per slide. Gets --active modifier when its slide is selected."}, {"cls": ".origam-carousel__controls-item--active", "num": 4, "descriptionKey": "components.carousel.anatomy.controls_item_active", "descriptionFallback": "BEM modifier applied to the active dot. Icon opacity rises from 0.5 to 1."}, {"cls": ".origam-carousel__progress", "num": 5, "descriptionKey": "components.carousel.anatomy.progress", "descriptionFallback": "Absolute strip at the top. Wraps OrigamProgressLinear. Visible only when progress=true."}], "classes": [{"cls": "origam-carousel", "descriptionKey": "components.carousel.anatomy.root", "descriptionFallback": "Root carousel element."}, {"cls": "origam-carousel__controls", "descriptionKey": "components.carousel.anatomy.controls", "descriptionFallback": "Pagination dots strip, absolutely positioned at the bottom."}, {"cls": "origam-carousel__controls-item", "descriptionKey": "components.carousel.anatomy.controls_item", "descriptionFallback": "Single pagination dot button."}, {"cls": "origam-carousel__controls-item--active", "descriptionKey": "components.carousel.anatomy.controls_item_active", "descriptionFallback": "Active state on the current slide dot."}, {"cls": "origam-carousel__progress", "descriptionKey": "components.carousel.anatomy.progress", "descriptionFallback": "Progress bar container, absolutely positioned at the top."}], "svgDesc": "Schematic of the Carousel component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamCarousel", "rootClass": "origam-carousel", "figcaption": "Anatomy of <code>&lt;origam-carousel&gt;</code> — 5 internal parts.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-carousel---overflow", "defaultValue": "hidden", "descriptionKey": "components.carousel.css_vars.overflow", "descriptionFallback": "Overflow mode of the carousel root."}, {"name": "--origam-carousel---position", "defaultValue": "relative", "descriptionKey": "components.carousel.css_vars.position", "descriptionFallback": "CSS position of the root element."}, {"name": "--origam-carousel---width", "defaultValue": "100%", "descriptionKey": "components.carousel.css_vars.width", "descriptionFallback": "Root width."}, {"name": "--origam-carousel__controls---background-color", "defaultValue": "rgba(0, 0, 0, 0.4)", "descriptionKey": "components.carousel.css_vars.controls_bg", "descriptionFallback": "Background of the pagination dots strip."}, {"name": "--origam-carousel__controls---height", "defaultValue": "50px", "descriptionKey": "components.carousel.css_vars.controls_height", "descriptionFallback": "Height of the controls strip."}, {"name": "--origam-carousel__controls---z-index", "defaultValue": "{zIndex.raised}", "descriptionKey": "components.carousel.css_vars.controls_z_index", "descriptionFallback": "Z-index of the controls strip, ensuring it renders above slide content."}, {"name": "--origam-carousel__controls-item---opacity", "defaultValue": "0.5", "descriptionKey": "components.carousel.css_vars.controls_item_opacity", "descriptionFallback": "Default icon opacity inside a pagination dot."}, {"name": "--origam-carousel__controls-item---opacity-active", "defaultValue": "1", "descriptionKey": "components.carousel.css_vars.controls_item_opacity_active", "descriptionFallback": "Icon opacity inside the active pagination dot."}, {"name": "--origam-carousel__progress---position-top", "defaultValue": "0", "descriptionKey": "components.carousel.css_vars.progress_position_top", "descriptionFallback": "Top offset of the progress bar. Set to auto and provide bottom to move it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.carousel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.carousel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed carousel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.carousel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.carousel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.carousel.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.carousel.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "cycle", "labelKey": "components.carousel.playground.cycle", "defaultValue": false, "labelFallback": "Auto-play"}, {"kind": "number", "prop": "interval", "labelKey": "components.carousel.playground.interval", "defaultValue": 6000, "labelFallback": "Interval (ms)"}, {"kind": "switch", "prop": "progress", "labelKey": "components.carousel.playground.progress", "defaultValue": false, "labelFallback": "Progress bar"}, {"kind": "switch", "prop": "showArrows", "labelKey": "components.carousel.playground.show_arrows", "defaultValue": true, "labelFallback": "Show arrows"}, {"kind": "switch", "prop": "hideDelimiters", "labelKey": "components.carousel.playground.hide_delimiters", "defaultValue": false, "labelFallback": "Hide delimiters"}, {"kind": "switch", "prop": "hideDelimiterBackground", "labelKey": "components.carousel.playground.hide_delimiter_background", "defaultValue": false, "labelFallback": "Hide delimiter background"}]}, "previewVariants": [{"label": "default", "props": {"height": 180, "continuous": true, "showArrows": true}, "slotContent": ""}, {"label": "no arrows", "props": {"height": 180, "showArrows": false}, "slotContent": ""}, {"label": "vertical dots", "props": {"height": 180, "verticalDelimiters": "left"}, "slotContent": ""}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('53976a7b-d8cd-4fa6-8e38-799308a5221e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'carousel-item', 'CarouselItem', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.carousel_item.description', 'A single slide inside OrigamCarousel — wraps OrigamWindowItem and OrigamImg, forwarding all image and window-item props.', NULL, NULL, 'origam-carousel-item', NULL, 'packages/ds/src/components/Carousel/OrigamCarouselItem.vue', 'origam', NULL, NULL, '/stories/?story=components-carousel--design', '/docs/components/Carousel/OrigamCarousel.html', 'carousel', '{"a11y": {"notes": [{"noteKey": "components.carousel_item.a11y.alt_required", "noteFallback": "When src is set, always provide a meaningful alt attribute. An empty alt=\"\" is acceptable for purely decorative images."}, {"noteKey": "components.carousel_item.a11y.hidden_slides", "noteFallback": "Inactive slides are hidden from the accessibility tree by OrigamWindowItem (aria-hidden=\"true\") — only the active slide is reachable by keyboard and screen readers."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.carousel_item.a11y.key_tab", "actionFallback": "Focus moves to interactive content inside the slide (links, buttons, form elements)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"50\" y=\"40\" width=\"600\" height=\"100\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-img (src, cover, srcset, alt…)</text>\n  <rect x=\"50\" y=\"110\" width=\"300\" height=\"30\" rx=\"2\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.12))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"200\" y=\"128\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot (overlay)</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"58\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"58\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"58\" cy=\"118\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"58\" y=\"122\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root = origam-window-item; height: inherit flows from the parent Carousel</text>\n", "code": "<!-- root delegates to origam-window-item -->\n<origam-window-item class=\"origam-carousel-item\">\n  <template #default>\n    <!-- default slot: full custom content -->\n    <slot name=\"default\">\n      <!-- embedded image when no default slot is provided -->\n      <origam-img v-bind=\"imgProps\">\n        <!-- overlay content -->\n        <template #default>\n          <slot name=\"content\" />\n        </template>\n        <!-- error fallback -->\n        <template #error>\n          <slot name=\"error\" />\n        </template>\n        <!-- loading placeholder -->\n        <template #placeholder>\n          <slot name=\"placeholder\" />\n        </template>\n      </origam-img>\n    </slot>\n  </template>\n</origam-window-item>", "legend": [{"cls": ".origam-carousel-item", "num": 1, "descriptionKey": "components.carousel_item.anatomy.root", "descriptionFallback": "Root element. Delegates to OrigamWindowItem and inherits height from the parent Carousel."}, {"cls": "origam-img (embedded)", "num": 2, "descriptionKey": "components.carousel_item.anatomy.img", "descriptionFallback": "OrigamImg instance filling the slide area. Props (src, cover, alt, srcset, eager…) are forwarded automatically. Skipped when the default slot is used."}, {"cls": "#content slot", "num": 3, "descriptionKey": "components.carousel_item.anatomy.content_slot", "descriptionFallback": "Projected into OrigamImg''s default slot. Use for overlay captions, badges, or action buttons positioned over the image."}], "classes": [{"cls": "origam-carousel-item", "descriptionKey": "components.carousel_item.anatomy.root", "descriptionFallback": "Root element. display: block; height: inherit — fills the Carousel height."}], "svgDesc": "Schematic of the CarouselItem component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamCarouselItem", "rootClass": "origam-carousel-item", "figcaption": "Anatomy of <code>&lt;origam-carousel-item&gt;</code> — 3 internal parts. The root delegates to OrigamWindowItem; the image fills the inherited height.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-carousel-item---display", "defaultValue": "block", "descriptionKey": "components.carousel_item.css_vars.display", "descriptionFallback": "Display mode of the root element."}, {"name": "--origam-carousel-item---height", "defaultValue": "inherit", "descriptionKey": "components.carousel_item.css_vars.height", "descriptionFallback": "Height inherited from the parent Carousel container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.carousel_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component (OrigamImg or OrigamWindowItem)."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.carousel_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle for the carousel item."}, {"name": "id", "type": "string", "descriptionKey": "components.carousel_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.carousel_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.carousel_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.carousel_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.carousel_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "cover", "labelKey": "components.carousel_item.playground.cover", "defaultValue": false, "labelFallback": "Cover"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('66ddc48e-f1ce-46c0-9e10-2b5626a60980', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'chart', 'Chart', 'Data Visualization', NULL, 'mdi-chart-line', 'components.catalog.chart.description', 'Universal chart component with 29 visualization primitives (line, area, bar, column, pie, donut, scatter, radar, gauge, pyramid, funnel, honeycomb, treemap, sankey, word-cloud, heatmap, sunburst, box-plot, pictorial, candlestick, streamgraph, variwide, polar-bar, bullet, pareto, map, sparkline, spline, stepped-line). The type prop routes to the appropriate family member.', NULL, NULL, 'origam-chart', NULL, 'packages/ds/src/components/Chart/OrigamChart.vue', 'origam', NULL, NULL, '/stories/?story=components-chart--design', '/docs/components/Chart/OrigamChart.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.chart.a11y.reduced_motion", "noteFallback": "The animated prop respects prefers-reduced-motion: reduce — set animated=false or let the component detect the system preference."}, {"noteKey": "components.chart.a11y.color_blind", "noteFallback": "Use colorScheme to provide intent-based colours with sufficient contrast for all colour-vision deficiency profiles. Avoid relying solely on hue to distinguish series — use dashed/solid patterns or labels when possible."}, {"noteKey": "components.chart.a11y.empty_slot", "noteFallback": "The #empty slot provides a meaningful message when no data is available, ensuring screen reader users are not left with a silent chart container."}], "roles": ["img", "figure"], "keyboard": [{"key": "Tab", "actionKey": "components.chart.a11y.key_tab", "actionFallback": "Moves focus to interactive data points (when keyboard navigation is enabled)."}, {"key": "Enter / Space", "actionKey": "components.chart.a11y.key_activate", "actionFallback": "Fires point-click emit on a focused data point."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-chart---background-color", "descriptionKey": "components.chart.tokens.bg", "descriptionFallback": "Chart container background."}, {"type": "dimension", "value": "var(--origam-font__size---lg)", "tokenPath": "--origam-chart__title---font-size", "descriptionKey": "components.chart.tokens.title_font_size", "descriptionFallback": "Title font size."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-chart__grid---color", "descriptionKey": "components.chart.tokens.grid_color", "descriptionFallback": "Grid line colour."}, {"type": "color", "value": "var(--origam-color__surface---inverse)", "tokenPath": "--origam-chart__tooltip---background-color", "descriptionKey": "components.chart.tokens.tooltip_bg", "descriptionFallback": "Tooltip background."}, {"type": "dimension", "value": "2px", "tokenPath": "--origam-chart__path---stroke-width", "descriptionKey": "components.chart.tokens.path_stroke_width", "descriptionFallback": "Line/area stroke width."}, {"type": "duration", "value": "600ms", "tokenPath": "--origam-chart---animation-duration", "descriptionKey": "components.chart.tokens.animation_duration", "descriptionFallback": "Enter/update animation duration."}, {"type": "dimension", "value": "var(--origam-radius---xs)", "tokenPath": "--origam-chart__bar---border-radius", "descriptionKey": "components.chart.tokens.bar_border_radius", "descriptionFallback": "Bar/column corner radius."}, {"type": "number", "value": "0.18", "tokenPath": "--origam-chart__radar---fill-opacity", "descriptionKey": "components.chart.tokens.radar_fill_opacity", "descriptionFallback": "Radar polygon fill opacity."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"36\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"600\">Chart Title</text>\n  <line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"155\" stroke=\"var(--origam-color__border---default, #e5e1f5)\" stroke-width=\"1\"/>\n  <line x1=\"60\" y1=\"155\" x2=\"660\" y2=\"155\" stroke=\"var(--origam-color__border---default, #e5e1f5)\" stroke-width=\"1\"/>\n  <polyline points=\"100,130 220,90 340,110 460,60 580,80 640,50\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\" fill=\"none\"/>\n  <rect x=\"220\" y=\"170\" width=\"260\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"178\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Legend</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"40\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"60\" cy=\"150\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"60\" y=\"154\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"350\" cy=\"173\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"177\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"400\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"400\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"210\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Routes to type-specific family member at runtime (cartesian / polar / radar / gauge / …)</text>\n", "code": "<!-- OrigamChart routes to a family member per type -->\n<origam-chart type=\"line\" :series=\"series\" :categories=\"categories\">\n  <!-- optional slot overrides -->\n  <template #tooltip=\"{ point, series, category }\">\n    <custom-tooltip :point=\"point\" :series=\"series\" />\n  </template>\n  <template #legend-item=\"{ series, visible }\">\n    <custom-legend-entry :series=\"series\" :visible=\"visible\" />\n  </template>\n  <template #empty>\n    <p>No data available.</p>\n  </template>\n</origam-chart>", "legend": [{"cls": ".origam-chart", "num": 1, "descriptionKey": "components.chart.anatomy.root", "descriptionFallback": "Root element. Delegates to the correct family component (cartesian/polar/radar/gauge/pyramid…)."}, {"cls": ".origam-chart__title", "num": 2, "descriptionKey": "components.chart.anatomy.title", "descriptionFallback": "Title and subtitle block rendered above the plotting area."}, {"cls": ".origam-chart__axis", "num": 3, "descriptionKey": "components.chart.anatomy.axis", "descriptionFallback": "X and Y axes with tick labels. Rendered by OrigamChartAxis. Hidden when showAxis=false."}, {"cls": ".origam-chart__legend", "num": 4, "descriptionKey": "components.chart.anatomy.legend", "descriptionFallback": "Legend block. Rendered by OrigamChartLegend. Position controlled by legendPosition prop."}, {"cls": ".origam-chart__plot", "num": 5, "descriptionKey": "components.chart.anatomy.plot", "descriptionFallback": "SVG plotting area where series paths, bars or slices are drawn."}], "classes": [{"cls": "origam-chart", "descriptionKey": "components.chart.anatomy.root", "descriptionFallback": "Root element wrapping the SVG plotting area."}, {"cls": "origam-chart__title", "descriptionKey": "components.chart.anatomy.title", "descriptionFallback": "Title / subtitle region."}, {"cls": "origam-chart__axis", "descriptionKey": "components.chart.anatomy.axis", "descriptionFallback": "Axis tick labels and grid lines."}, {"cls": "origam-chart__legend", "descriptionKey": "components.chart.anatomy.legend", "descriptionFallback": "Legend swatch entries."}, {"cls": "origam-chart__plot", "descriptionKey": "components.chart.anatomy.plot", "descriptionFallback": "SVG series paths, bars and point markers."}], "svgDesc": "Schematic of the Chart component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamChart", "rootClass": "origam-chart", "figcaption": "Anatomy of <code>&lt;origam-chart&gt;</code> — 5 visible regions; the component delegates rendering to the appropriate family member based on the <code>type</code> prop.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart.css_vars.bg", "descriptionFallback": "Chart container background colour."}, {"name": "--origam-chart---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart.css_vars.color", "descriptionFallback": "Default text colour for title, labels and legend."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart.css_vars.padding", "descriptionFallback": "Inner padding of the chart container."}, {"name": "--origam-chart__title---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart.css_vars.title_color", "descriptionFallback": "Title text colour."}, {"name": "--origam-chart__title---font-size", "defaultValue": "{font.size.lg}", "descriptionKey": "components.chart.css_vars.title_font_size", "descriptionFallback": "Title font size."}, {"name": "--origam-chart__axis---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.chart.css_vars.axis_color", "descriptionFallback": "Axis line colour."}, {"name": "--origam-chart__grid---color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.chart.css_vars.grid_color", "descriptionFallback": "Grid line colour."}, {"name": "--origam-chart__tooltip---background-color", "defaultValue": "{color.surface.inverse}", "descriptionKey": "components.chart.css_vars.tooltip_bg", "descriptionFallback": "Tooltip background colour."}, {"name": "--origam-chart__path---stroke-width", "defaultValue": "2px", "descriptionKey": "components.chart.css_vars.path_stroke_width", "descriptionFallback": "Stroke width of line/area series paths."}, {"name": "--origam-chart__animation---duration", "defaultValue": "600ms", "descriptionKey": "components.chart.css_vars.animation_duration", "descriptionFallback": "Animation duration for enter/update transitions."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "line", "value": "line"}, {"label": "area", "value": "area"}, {"label": "bar", "value": "bar"}, {"label": "column", "value": "column"}, {"label": "pie", "value": "pie"}, {"label": "donut", "value": "donut"}, {"label": "scatter", "value": "scatter"}, {"label": "radar", "value": "radar"}, {"label": "gauge", "value": "gauge"}], "labelKey": "components.chart.playground.type", "defaultValue": "line", "labelFallback": "Chart type"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart.playground.show_legend", "defaultValue": true, "labelFallback": "Show legend"}, {"kind": "switch", "prop": "showGrid", "labelKey": "components.chart.playground.show_grid", "defaultValue": true, "labelFallback": "Show grid"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "switch", "prop": "stacked", "labelKey": "components.chart.playground.stacked", "defaultValue": false, "labelFallback": "Stacked"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('75568f80-4095-4141-9bd1-014f42ba64df', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'chart-axis', 'ChartAxis', 'Data Visualization', NULL, 'mdi-axis', 'components.catalog.chart_axis.description', 'Axis and tick rendering sub-component. Extracts cartesian axis chrome (X+Y axes, grid lines, tick labels) from the chart family so polar/radar/gauge families do not inherit cartesian elements.', NULL, NULL, 'origam-chart-axis', NULL, 'packages/ds/src/components/Chart/OrigamChartAxis.vue', 'origam', NULL, NULL, NULL, NULL, 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_axis.a11y.decorative", "noteFallback": "ChartAxis is a purely decorative SVG sub-component with no interactive elements. Accessibility is handled by the parent chart container (role=\"img\" with aria-label describing the data)."}], "roles": ["group"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__border---default)", "tokenPath": "--origam-chart__axis---color", "descriptionKey": "components.chart_axis.tokens.axis_color", "descriptionFallback": "Axis line colour."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-chart__axis-label---color", "descriptionKey": "components.chart_axis.tokens.label_color", "descriptionFallback": "Tick label text colour."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-chart__grid---color", "descriptionKey": "components.chart_axis.tokens.grid_color", "descriptionFallback": "Grid line colour."}, {"type": "dimension", "value": "1px", "tokenPath": "--origam-chart__grid---stroke-width", "descriptionKey": "components.chart_axis.tokens.grid_stroke_width", "descriptionFallback": "Grid line stroke width."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"60\" y=\"20\" width=\"620\" height=\"160\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <line x1=\"60\" y1=\"20\" x2=\"60\" y2=\"180\" stroke=\"var(--origam-color__border---default, #a855f7)\" stroke-width=\"1.5\"/>\n  <line x1=\"60\" y1=\"180\" x2=\"680\" y2=\"180\" stroke=\"var(--origam-color__border---default, #a855f7)\" stroke-width=\"1.5\"/>\n  <line x1=\"60\" y1=\"60\" x2=\"680\" y2=\"60\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <line x1=\"60\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <line x1=\"60\" y1=\"140\" x2=\"680\" y2=\"140\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"40\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"''JetBrains Mono'',monospace\">300</text>\n  <text x=\"40\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"''JetBrains Mono'',monospace\">200</text>\n  <text x=\"40\" y=\"144\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"''JetBrains Mono'',monospace\">100</text>\n  <text x=\"200\" y=\"196\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Jan</text>\n  <text x=\"370\" y=\"196\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Feb</text>\n  <text x=\"540\" y=\"196\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Mar</text>\n  <circle cx=\"68\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"68\" cy=\"180\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"68\" y=\"184\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"370\" cy=\"100\" r=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"370\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"200\" cy=\"196\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"200\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<!-- OrigamChartAxis renders inside the parent chart SVG -->\n<g class=\"origam-chart-axis\">\n  <!-- horizontal grid lines (one per Y tick) -->\n  <line class=\"origam-chart-axis__grid\" />\n  <!-- Y axis vertical line -->\n  <line class=\"origam-chart-axis__y-axis\" />\n  <!-- X axis horizontal line -->\n  <line class=\"origam-chart-axis__x-axis\" />\n  <!-- tick labels for X and Y -->\n  <text class=\"origam-chart-axis__tick-label\" />\n</g>", "legend": [{"cls": ".origam-chart-axis__y-axis", "num": 1, "descriptionKey": "components.chart_axis.anatomy.y_axis", "descriptionFallback": "Left vertical axis line. Hidden when showAxis=false."}, {"cls": ".origam-chart-axis__x-axis", "num": 2, "descriptionKey": "components.chart_axis.anatomy.x_axis", "descriptionFallback": "Bottom horizontal axis line. Hidden when showAxis=false."}, {"cls": ".origam-chart-axis__grid", "num": 3, "descriptionKey": "components.chart_axis.anatomy.grid", "descriptionFallback": "Horizontal grid lines aligned with Y-axis ticks. Hidden when showGrid=false."}, {"cls": ".origam-chart-axis__tick-label", "num": 4, "descriptionKey": "components.chart_axis.anatomy.tick_label", "descriptionFallback": "X and Y axis tick labels formatted by xAxisFormat / yAxisFormat."}], "classes": [{"cls": "origam-chart-axis", "descriptionKey": "components.chart_axis.anatomy.root", "descriptionFallback": "Root SVG group element wrapping all axis chrome."}, {"cls": "origam-chart-axis__y-axis", "descriptionKey": "components.chart_axis.anatomy.y_axis", "descriptionFallback": "Left Y-axis line."}, {"cls": "origam-chart-axis__x-axis", "descriptionKey": "components.chart_axis.anatomy.x_axis", "descriptionFallback": "Bottom X-axis line."}, {"cls": "origam-chart-axis__grid", "descriptionKey": "components.chart_axis.anatomy.grid", "descriptionFallback": "Horizontal grid lines."}, {"cls": "origam-chart-axis__tick-label", "descriptionKey": "components.chart_axis.anatomy.tick_label", "descriptionFallback": "Axis tick label text elements."}], "svgDesc": "Schematic showing X axis, Y axis, grid lines and tick labels.", "svgTitle": "Anatomy of OrigamChartAxis", "rootClass": "origam-chart-axis", "figcaption": "Anatomy of <code>&lt;origam-chart-axis&gt;</code> — 4 visible regions: Y axis line ①, X axis line ②, horizontal grid lines ③, and tick labels ④.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-chart__axis---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.chart_axis.css_vars.axis_color", "descriptionFallback": "Axis line colour."}, {"name": "--origam-chart__axis__label---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.chart_axis.css_vars.label_color", "descriptionFallback": "Tick label text colour."}, {"name": "--origam-chart__axis__label---font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.chart_axis.css_vars.label_font_size", "descriptionFallback": "Tick label font size."}, {"name": "--origam-chart__grid---color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.chart_axis.css_vars.grid_color", "descriptionFallback": "Grid line colour."}, {"name": "--origam-chart__grid---stroke-width", "defaultValue": "1px", "descriptionKey": "components.chart_axis.css_vars.grid_stroke_width", "descriptionFallback": "Grid line stroke width."}], "playground": {"controls": [{"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_axis.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showGrid", "labelKey": "components.chart_axis.playground.show_grid", "defaultValue": true, "labelFallback": "Show Grid"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
