x2=\"200\" y2=\"160\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <line x1=\"185\" y1=\"60\" x2=\"215\" y2=\"60\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <line x1=\"185\" y1=\"160\" x2=\"215\" y2=\"160\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <circle cx=\"200\" cy=\"170\" r=\"4\" fill=\"var(--origam-color__feedback--danger---bg, #dc2626)\"/>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"200\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"200\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"114\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"200\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"200\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"200\" cy=\"170\" r=\"9\" fill=\"var(--origam-color__feedback--danger---bg, #dc2626)\"/>\n  <text x=\"200\" y=\"174\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<g class=\"origam-chart-box-plot\">\n  <!-- one group per category slot -->\n  <g class=\"origam-chart-box-plot__slot\">\n    <!-- upper and lower whiskers + caps -->\n    <line class=\"origam-chart-box-plot__whisker\" />\n    <!-- IQR box (Q1 to Q3) -->\n    <rect class=\"origam-chart-box-plot__box\" />\n    <!-- median line at Q2 -->\n    <line class=\"origam-chart-box-plot__median\" />\n    <!-- outlier dots (v-if showOutliers) -->\n    <circle class=\"origam-chart-box-plot__outlier\" />\n  </g>\n</g>", "legend": [{"cls": ".origam-chart-box-plot", "num": 1, "descriptionKey": "components.chart_box_plot.anatomy.root", "descriptionFallback": "Root SVG element containing all box plots."}, {"cls": ".origam-chart-box-plot__box", "num": 2, "descriptionKey": "components.chart_box_plot.anatomy.box", "descriptionFallback": "IQR rectangle from Q1 to Q3."}, {"cls": ".origam-chart-box-plot__median", "num": 3, "descriptionKey": "components.chart_box_plot.anatomy.median", "descriptionFallback": "Horizontal line at the median (Q2)."}, {"cls": ".origam-chart-box-plot__whisker", "num": 4, "descriptionKey": "components.chart_box_plot.anatomy.whisker", "descriptionFallback": "Vertical whisker lines extending from Q1/Q3 to min/max fences, plus cap segments."}, {"cls": ".origam-chart-box-plot__outlier", "num": 5, "descriptionKey": "components.chart_box_plot.anatomy.outlier", "descriptionFallback": "Outlier dot circles rendered when showOutliers=true."}], "classes": [{"cls": "origam-chart-box-plot", "descriptionKey": "components.chart_box_plot.anatomy.root", "descriptionFallback": "Root SVG group."}, {"cls": "origam-chart-box-plot__slot", "descriptionKey": "components.chart_box_plot.anatomy.slot", "descriptionFallback": "Per-category slot group."}, {"cls": "origam-chart-box-plot__box", "descriptionKey": "components.chart_box_plot.anatomy.box", "descriptionFallback": "IQR box rectangle."}, {"cls": "origam-chart-box-plot__median", "descriptionKey": "components.chart_box_plot.anatomy.median", "descriptionFallback": "Median line."}, {"cls": "origam-chart-box-plot__whisker", "descriptionKey": "components.chart_box_plot.anatomy.whisker", "descriptionFallback": "Whisker lines and caps."}, {"cls": "origam-chart-box-plot__outlier", "descriptionKey": "components.chart_box_plot.anatomy.outlier", "descriptionFallback": "Outlier dot circles."}], "svgDesc": "Schematic showing a box, whiskers and outlier dot.", "svgTitle": "Anatomy of 