ents.data_table_header_cell.tokens.background_color", "descriptionFallback": "Header cell background — neutral.0 light / neutral.900 dark."}, {"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-data-table__header---color", "descriptionKey": "components.data_table_header_cell.tokens.color", "descriptionFallback": "Header cell text colour."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-data-table__header---sort-icon-opacity", "descriptionKey": "components.data_table_header_cell.tokens.sort_icon_opacity", "descriptionFallback": "Sort icon opacity at rest (hidden)."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-data-table__header---sort-badge-border-radius", "descriptionKey": "components.data_table_header_cell.tokens.sort_badge_border_radius", "descriptionFallback": "Sort badge border-radius (pill shape)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"28\" width=\"528\" height=\"84\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"16\" y=\"28\" width=\"528\" height=\"84\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\"/>\n  <rect x=\"28\" y=\"44\" width=\"300\" height=\"36\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"80\" y=\"67\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Column Title</text>\n  <rect x=\"196\" y=\"52\" width=\"20\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"206\" y=\"65\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">↑</text>\n  <rect x=\"220\" y=\"52\" width=\"20\" height=\"20\" rx=\"10\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\"/>\n  <text x=\"230\" y=\"65\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">1</text>\n  <rect x=\"16\" y=\"100\" width=\"528\" height=\"4\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\"/>\n  <circle cx=\"24\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"24\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"34\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"34\" y=\"66\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"200\" y=\"56\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"224\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"224\" y=\"56\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"33\" y1=\"36\" x2=\"320\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"324\" y=\"17\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-header-cell</text>\n", "code": "<origam-data-table-column-cell tag=\"th\" class=\"origam-data-table-header-cell\">\n  <slot :name=\"`header.${column.key}`\" v-bind=\"slotProps\">\n    <!-- select-all checkbox (data-table-select column only) -->\n    <origam-checkbox-btn v-if=\"hasColumn(''data-table-select'')\" />\n    <!-- regular title + sort icon -->\n    <div v-else class=\"origam-data-table-header-cell__content\">\n      <span>{{ column.title }}</span>\n      <origam-icon class=\"origam-data-table-header-cell__sort-icon\" />\n      <!-- multi-sort badge -->\n      <div class=\"origam-data-table-header-cell__sort-badge\">{{ sortIndex }}</div>\n    </div>\n  </slot>\n</origam-data-table-column-cell>", "legend": [{"cls": ".origam-data-table-header-cell", "num": 1, "descriptionKey": "components.data_table_header_cell.anatomy.root", "descriptionFallback": "Root <code>&lt;th&gt;</code> element rendered via <code>OrigamDataTableColumnCell tag=\"th\"</code>. Has <code>--sortable</code> and <code>--sorted</code> BEM modifiers and <code>--fixed</code> when the column is pinned."}, {"cls": ".origam-data-table-header-cell__content", "num": 2, "descriptionKey": "components.data_table_header_cell.anatomy.content", "descriptionFallback": "Flex row containing the column title span, sort icon and optional multi-sort badge."}, {"cls": ".origam-data-table-header-cell__sort-icon", "num": 3, "descriptionKey": "components.data_table_header_cell.anatomy.sort_icon", "descriptionFallback": "<code>OrigamIcon</code> shown when <code>column.sortable && !disableSort</code>. Opacity 0 at rest, 0.5 on hover, 1 when sorted. Has <code>--active</code> modifier."}, {"cls": ".origam-data-table-header-cell__sort-badge", "num": 4, "descriptionKey": "components.data_table_header_cell.anatomy.sort_badge", "descriptionFallback": "Pill badge showing the sort priority index when <code>multiSort=true</code> and the column is sorted."}], "classes": [{"cls": "origam-data-table-header-cell", "descriptionKey": "components.data_table_header_cell.anatomy.root", "descriptionFallback": "Root th element."}, {"cls": "origam-data-table-header-cell--sortable", "descriptionKey": "components.data_table_header_cell.anatomy.sortable", "descriptionFallback": "Applied when column.sortable=true and disableSort=false. Sets cursor: pointer."}, {"cls": "origam-data-table-header-cell--sorted", "descriptionKey": "components.data_table_header_cell.anatomy.sorted", "descriptionFallback": "Applied when the column is actively used in the sort. Sets sort icon opacity to 1."}, {"cls": "origam-data-table-header-cell--fixed", "descriptionKey": "components.data_table_header_cell.anatomy.fixed", "descriptionFallback": "Applied when column.fixed=true. Column is sticky-positioned at fixedOffset."}, {"cls": "origam-data-table-header-cell__content", "descriptionKey": "components.data_table_header_cell.anatomy.content", "descriptionFallback": "Flex row — title, sort icon, and badge."}, {"cls": "origam-data-table-header-cell__sort-icon", "descriptionKey": "components.data_table_header_cell.anatomy.sort_icon", "descriptionFallback": "Sort direction icon. Opacity controlled by hover/sorted state."}, {"cls": "origam-data-table-header-cell__sort-icon--active", "descriptionKey": "components.data_table_header_cell.anatomy.sort_icon_active", "descriptionFallback": "Modifier applied when the column is actively sorted."}, {"cls": "origam-data-table-header-cell__sort-badge", "descriptionKey": "components.data_table_header_cell.anatomy.sort_badge", "descriptionFallback": "Multi-sort priority badge (20x20px pill)."}], "svgDesc": "Schematic of DataTableHeaderCell with 4 internal parts.", "svgTitle": "Anatomy of OrigamDataTableHeaderCell", "rootClass": "origam-data-table-header-cell", "figcaption": "Anatomy of <code>&lt;origam-data-table-header-cell&gt;</code> — 4 parts: th root ①, content wrapper ②, sort icon ③, multi-sort badge ④.", "svgViewBox": "0 0 560 140"}, "cssVars": [{"name": "--origam-data-table-header-cell---color", "defaultValue": "var(--origam-color__text---primary)", "descriptionKey": "components.data_table_header_cell.css_vars.color", "descriptionFallback": "Header cell text colour."}, {"name": "--origam-data-table-header-cell---background", "defaul