family=\"system-ui\" font-weight=\"600\">May</text>\n  <rect x=\"362\" y=\"112\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"449\" y=\"130\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Jun</text>\n  <text x=\"350\" y=\"168\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… (Jul – Dec)</text>\n  <!-- markers -->\n  <circle cx=\"148\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"168\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"168\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"168\" cy=\"120\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"168\" y=\"124.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-months\">\n  <div class=\"origam-date-picker-months__content\">\n    <!-- slot: #month — repeated for each of the 12 months -->\n    <origam-btn\n      v-for=\"(month, i) in months\"\n      :key=\"i\"\n      :active=\"model === i\"\n      :color=\"model === i ? color : undefined\"\n      :disabled=\"month.isDisabled\"\n      :rounded=\"true\"\n      :text=\"month.text\"\n      @click=\"handleClick(i)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-months", "num": 1, "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Fixed height (288px by default). Overflow hidden."}, {"cls": ".origam-date-picker-months__content", "num": 2, "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column CSS grid with justify-content: space-around. padding-inline: 36px. grid-gap: 0 24px. Inner OrigamBtn elements have text-transform: none."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_months.anatomy.active_btn", "descriptionFallback": "The currently selected month button. Receives active=true and color=props.color. All buttons have rounded=true."}], "classes": [{"cls": "origam-date-picker-months", "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Default height 288px."}, {"cls": "origam-date-picker-months__content", "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column grid of month buttons."}], "svgDesc": "Schematic of the DatePickerMonths component showing a 2-column grid of 12 month buttons.", "svgTitle": "Anatomy of OrigamDatePickerMonths", "rootClass": "origam-date-picker-months", "figcaption": "Anatomy of <code>&lt;origam-date-picker-months&gt;</code> — 3 parts: ① root container (288px default height), ② the 2-column grid content wrapper, ③ the active month button highlighted with the <code>color</code> prop.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-months---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_months.css_vars.height", "descriptionFallback": "Container height. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_months.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_months.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_months.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_months.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_months.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_months.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_months.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2d9f0847-de57-4edd-b53a-d48d24dcb5a7', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'date-picker-years', 'DatePickerYears', 'Form & Input', NULL, 'mdi-calendar-range', 'components.catalog.date_picker_years.description', 'Scrollable year list for picking a year. Renders years in a 3-column grid from min to max (defaulting to ±100 years from today). Auto-scrolls to the selected year on mount.', NULL, NULL, 'origam-date-picker-years', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerYears.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePickerYears.html', 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_years.a11y.scroll_note", "noteFallback": "On mount, the selected year is automatically scrolled into the centre of the visible area via scrollIntoView({block: \"center\"}), so users do not need to scroll manually to find the current year."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_years.a11y.key_select", "actionFallback": "Selects the focused year."}, {"key": "Tab", "actionKey": "components.date_picker_years.a11y.key_tab", "actionFallback": "Moves focus between year tiles."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_years.tokens.selected_bg", "descriptionFallback": "Active year button background (driven by the color prop)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root with scroll indicator -->\n  <rect x=\"100\" y=\"20\" width=\"500\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- scroll indicator bar on right -->\n  <rect x=\"590\" y=\"20\" width=\"6\" height=\"180\" rx=\"3\" fill=\"var(--origam-color__border---subtle, rgba(0,0,0,0.06))\"/>\n  <rect x=\"590\" y=\"68\" width=\"6\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <!-- 3-col grid -->\n  <text x=\"162\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2020</text>\n  <text x=\"310\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2021</text>\n  <text x=\"458\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2022</text>\n  <text x=\"162\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2023</text>\n  <text x=\"310\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2024</text>\n  <text x=\"458\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2025</text>\n  <!-- selected year -->\n  <rect x=\"218\" y=\"92\" width=\"184\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"310\" y=\"110\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"700\">2026</text>\n  <text x=\"162\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2026</text>\n  <text x=\"458\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2027</text>\n  <text x=\"162\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2028</text>\n  <text x=\"310\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2029</text>\n  <text x=\"458\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2030</text>\n  <text x=\"350\" y=\"178\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… scrollable</text>\n  <!-- markers -->\n  <circle cx=\"108\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"120\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"120\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"220\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"220\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-years\">\n  <div class=\"origam-date-picker-years__content\">\n    <!-- slot: #year — repeated for each year in the [min..max] range -->\n    <origam-btn\n      v-for=\"year in years\"\n      :ref=\"model === year.value ? yearRef : undefined\"\n      :active=\"model === year.value\"\n      :color=\"model === year.value ? color : undefined\"\n      :rounded=\"true\"\n      :text=\"year.text\"\n      @click=\"handleClick(year.value)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-years", "num": 1, "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root container. Height 288px (default), overflow-y: scroll. Enables native browser scrolling to the selected year."}, {"cls": ".origam-date-picker-years__content", "num": 2, "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column CSS grid with justify-content: space-around. gap: 8px 24px. padding-inline: 32px. Inner OrigamBtn have padding-inline: 8px."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_years.anatomy.active_btn", "descriptionFallback": "The selected year button. Receives active=true and color=props.color. All buttons have rounded=true. The active button is also assigned a template ref so scrollIntoView can target it on mount."}], "classes": [{"cls": "origam-date-picker-years", "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root scroll container. Default height 288px."}, {"cls": "origam-date-picker-years__content", "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column grid of year buttons."}], "svgDesc": "Schematic of the DatePickerYears component showing a scrollable 3-column grid of year buttons.", "svgTitle": "Anatomy of OrigamDatePickerYears", "rootClass": "origam-date-picker-years", "figcaption": "Anatomy of <code>&lt;origam-date-picker-years&gt;</code> — 3 parts: ① root scroll container (288px height, overflow-y: scroll), ② 3-column grid content wrapper, ③ the active year button. On mount, the selected year scrolls into view via <code>scrollIntoView({block: ''center''})</code>.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-years---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_years.css_vars.height", "descriptionFallback": "Container height. Overflow-y: scroll. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_years.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_years.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_years.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_years.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_years.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a52efcda-823c-459f-9ade-1b11638df94e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'defaults-provider', 'DefaultsProvider', 'Utilities & Providers', NULL, 'mdi-tune-variant', 'components.catalog.defaults_provider.description', 'Structurally transparent context provider that injects a prop-defaults map into all descendant Origam components via useDefaults().', NULL, NULL, 'origam-defaults-provider', NULL, 'packages/ds/src/components/DefaultsProvider/OrigamDefaultsProvider.vue', 'origam', NULL, NULL, '/stories/?story=components-defaults-provider--design', '/docs/components/DefaultsProvider/OrigamDefaultsProvider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.defaults_provider.a11y.transparent_note", "noteFallback": "OrigamDefaultsProvider has no visual rendering, no focusable element and no ARIA attributes. All a11y considerations belong to the descendant components it wraps."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"120\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"8 4\"/>\n  <text x=\"350\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-defaults-provider (no DOM output)</text>\n  <rect x=\"80\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"300\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"390\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"520\" y=\"70\" width=\"120\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"580\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">…more</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"170\" cy=\"78\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"170\" y=\"82.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① Provider (transparent) injects defaults via provide() — no DOM node rendered</text>\n", "code": "<!-- OrigamDefaultsProvider renders ONLY its default slot — no DOM wrapper -->\n<template>\n  <slot name=\"default\" />\n</template>\n\n<script setup>\n// Injects the defaults map into all useDefaults() consumers in the subtree\nprovideDefaults(computed(() => props.defaults ?? {}), {\n  scoped: props.scoped,\n  reset: props.reset,\n  root: props.root,\n  disabled: props.disabled\n})\n</script>", "legend": [{"cls": ".origam-defaults-provider (no DOM)", "num": 1, "descriptionKey": "components.defaults_provider.anatomy.provider", "descriptionFallback": "The provider itself. Calls <code>provideDefaults()</code> once on setup, then renders only <code>&lt;slot name=\"default\"/&gt;</code>. No wrapper element is injected into the DOM."}, {"cls": "#default slot — descendant components", "num": 2, "descriptionKey": "components.defaults_provider.anatomy.slot", "descriptionFallback": "Any Origam component in the subtree that calls <code>useDefaults()</code> automatically picks up the injected map. Child components are NOT aware of being wrapped."}], "classes": [{"cls": "origam-defaults-provider", "descriptionKey": "components.defaults_provider.anatomy.root", "descriptionFallback": "No CSS class is emitted on any DOM element. The component is purely logical."}], "svgDesc": "Schematic showing the provider renders only its default slot with no visual chrome.", "svgTitle": "Anatomy of OrigamDefaultsProvider", "rootClass": "origam-defaults-provider", "figcaption": "Anatomy of <code>&lt;origam-defaults-provider&gt;</code> — structurally transparent. The component renders only the <code>#default</code> slot; it injects defaults via Vue''s <code>provide()</code> / <code>inject()</code> without any DOM output of its own.", "svgViewBox": "0 0 700 200"}, "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.defaults_provider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component. Used by Origam''s auto-forwarding pattern."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.defaults_provider.playground.disabled", "defaultValue": false, "labelFallback": "Disabled (pass through parent defaults)"}, {"kind": "switch", "prop": "scoped", "labelKey": "components.defaults_provider.playground.scoped", "defaultValue": false, "labelFallback": "Scoped (no parent inheritance)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb57a14a-051e-4482-a4ac-31f5a4993ad4', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'dialog', 'Dialog', 'Overlay & Surface', NULL, 'mdi-card-outline', 'components.catalog.dialog.description', 'Modal overlay dialog built on OrigamOverlay and OrigamCard. Supports activator slot, focus trap, scrollable mode, fullscreen, size variants, and status icons.', NULL, NULL, 'origam-dialog', NULL, 'packages/ds/src/components/Dialog/OrigamDialog.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialog.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.dialog.a11y.role_note", "noteFallback": "The inner OrigamCard renders role=\"dialog\" and aria-modal=\"true\". The title element is linked via aria-labelledby using the auto-generated dialogTitleId."}, {"noteKey": "components.dialog.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content element. On close, focus returns to the activator element."}, {"noteKey": "components.dialog.a11y.activator_note", "noteFallback": "The activator element automatically receives aria-haspopup=\"dialog\" and aria-expanded bound to the open state."}, {"noteKey": "components.dialog.a11y.persistent_note", "noteFallback": "When persistent=true, Escape and click-outside do not close the dialog. Use this only for critical flows (e.g., unsaved changes warning)."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog.a11y.key_tab", "actionFallback": "Cycles focus through focusable elements inside the dialog. When retainFocus=true, Tab wraps from last to first element."}, {"key": "Shift+Tab", "actionKey": "components.dialog.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards. Wraps from first to last element when retainFocus=true."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-dialog---background", "descriptionKey": "components.dialog.tokens.background", "descriptionFallback": "Dialog surface background. Uses the raised surface semantic color."}, {"type": "dimension", "value": "var(--origam-radius---lg)", "tokenPath": "--origam-dialog---border-radius", "descriptionKey": "components.dialog.tokens.border_radius", "descriptionFallback": "Border radius applied to the dialog content wrapper. Reset to 0 in fullscreen mode."}, {"type": "shadow", "value": "var(--origam-shadow---xl)", "tokenPath": "--origam-dialog---box-shadow", "descriptionKey": "components.dialog.tokens.box_shadow", "descriptionFallback": "Elevation shadow for the dialog surface."}, {"type": "number", "value": "var(--origam-zIndex---modal)", "tokenPath": "--origam-dialog---z-index", "descriptionKey": "components.dialog.tokens.z_index", "descriptionFallback": "z-index of the dialog overlay (default: 2400)."}, {"type": "dimension", "value": "720px", "tokenPath": "--origam-dialog---width-md", "descriptionKey": "components.dialog.tokens.width_md", "descriptionFallback": "Default dialog width (size=\"default\")."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-dialog---transition-duration", "descriptionKey": "components.dialog.tokens.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-dialog__header---padding", "descriptionKey": "components.dialog.tokens.header_padding", "descriptionFallback": "Padding inside the dialog header zone."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-dialog__content---padding-inline", "descriptionKey": "components.dialog.tokens.content_padding_inline", "descriptionFallback": "Horizontal padding of the dialog body content."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"25\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">origam-overlay (scrim)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"220\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"72\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend | title | subtitle | append (close btn)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"96\" width=\"500\" height=\"108\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"204\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"236\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">footer — action buttons</text>\n  <!-- numbering -->\n  <circle cx=\"18\" cy=\"18\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"104\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"108.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"212\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"216.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-overlay v-model=\"isActive\" class=\"origam-dialog\">\n  <!-- activator trigger element -->\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <template #default=\"{ isActive }\">\n    <slot name=\"default\" v-bind=\"{ isActive }\">\n      <!-- default body: OrigamCard -->\n      <origam-card\n        role=\"dialog\"\n        aria-modal=\"true\"\n        :aria-labelledby=\"dialogTitleId\"\n      >\n        <!-- header zone: prepend | title | subtitle | append(close) -->\n        <template #header-prepend><slot name=\"header-prepend\" /></template>\n        <template #header-title=\"{ titleId }\"><slot name=\"header-title\" v-bind=\"{ titleId }\" /></template>\n        <template #header-append>\n          <slot name=\"header-append\">\n            <origam-btn icon=\"mdi-close\" @click=\"handleClose\" aria-label=\"Close dialog\" />\n          </slot>\n        </template>\n\n        <!-- scrollable content body -->\n        <template #default>\n          <slot name=\"content\" />\n          <div ref=\"endText\" v-intersect=\"handleIntersect\" />\n        </template>\n\n        <!-- footer actions -->\n        <template #footer><slot name=\"footer\" /></template>\n      </origam-card>\n    </slot>\n  </template>\n</origam-overlay>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog.anatomy.overlay", "descriptionFallback": "Full-viewport overlay managed by OrigamOverlay. Blocks interaction with the page and handles click-outside / Escape key."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog.anatomy.header", "descriptionFallback": "Card header zone with prepend (status icon), title (aria-labelledby target), subtitle, and append (close button)."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog.anatomy.content", "descriptionFallback": "Scrollable content body. Contains the #content slot plus an invisible IntersectionObserver sentinel that fires isRead when scrolled into view."}, {"cls": ".origam-card__footer", "num": 4, "descriptionKey": "components.dialog.anatomy.footer", "descriptionFallback": "Footer area for action buttons. Typically Cancel and Confirm. Fixed at the bottom in scrollable mode."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog.anatomy.root", "descriptionFallback": "Root class applied to the origam-overlay element. Drives alignment (center center) and size-width vars."}, {"cls": "origam-dialog--fullscreen", "descriptionKey": "components.dialog.anatomy.fullscreen", "descriptionFallback": "Applied when fullscreen=true. Resets width, max-width, max-height and border-radius to 100vw/100vh/0."}, {"cls": "origam-dialog--scrollable", "descriptionKey": "components.dialog.anatomy.scrollable", "descriptionFallback": "Applied when scrollable=true. Enables overflow-y: auto on the card content zone."}, {"cls": "origam-dialog--size-x-small", "descriptionKey": "components.dialog.anatomy.size_xs", "descriptionFallback": "Sets --origam-dialog---width to 320px."}, {"cls": "origam-dialog--size-small", "descriptionKey": "components.dialog.anatomy.size_sm", "descriptionFallback": "Sets --origam-dialog---width to 400px."}, {"cls": "origam-dialog--size-default", "descriptionKey": "components.dialog.anatomy.size_md", "descriptionFallback": "Sets --origam-dialog---width to 720px."}, {"cls": "origam-dialog--size-large", "descriptionKey": "components.dialog.anatomy.size_lg", "descriptionFallback": "Sets --origam-dialog---width to 960px."}, {"cls": "origam-dialog--size-x-large", "descriptionKey": "components.dialog.anatomy.size_xl", "descriptionFallback": "Sets --origam-dialog---width to 1080px."}], "svgDesc": "Schematic of the Dialog component showing overlay wrapper, card body, header, content, and footer zones.", "svgTitle": "Anatomy of OrigamDialog", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog&gt;</code> — 4 zones: ① overlay scrim, ② card header (prepend / title / append), ③ scrollable content body, ④ footer for actions.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog---width", "defaultValue": "auto", "descriptionKey": "components.dialog.css_vars.width", "descriptionFallback": "Dialog width. Overridden per size class (xs: 320px → xl: 1080px) and set to 100vw in fullscreen mode."}, {"name": "--origam-dialog---max-height", "defaultValue": "calc(100vh - 48px)", "descriptionKey": "components.dialog.css_vars.max_height", "descriptionFallback": "Maximum dialog height. Resolves to 100vh in fullscreen mode."}, {"name": "--origam-dialog---max-width", "defaultValue": "calc(100vw - 48px)", "descriptionKey": "components.dialog.css_vars.max_width", "descriptionFallback": "Maximum dialog width."}, {"name": "--origam-dialog---border-radius", "defaultValue": "{radius.lg} (12px)", "descriptionKey": "components.dialog.css_vars.border_radius", "descriptionFallback": "Border radius applied to the overlay content wrapper. Reset to 0 in fullscreen mode."}, {"name": "--origam-dialog---box-shadow", "defaultValue": "{shadow.xl}", "descriptionKey": "components.dialog.css_vars.box_shadow", "descriptionFallback": "Box shadow applied to the dialog surface for depth."}, {"name": "--origam-dialog---width-xs", "defaultValue": "320px", "descriptionKey": "components.dialog.css_vars.width_xs", "descriptionFallback": "Width token for size=\"x-small\"."}, {"name": "--origam-dialog---width-sm", "defaultValue": "400px", "descriptionKey": "components.dialog.css_vars.width_sm", "descriptionFallback": "Width token for size=\"small\"."}, {"name": "--origam-dialog---width-md", "defaultValue": "720px", "descriptionKey": "components.dialog.css_vars.width_md", "descriptionFallback": "Width token for size=\"default\"."}, {"name": "--origam-dialog---width-lg", "defaultValue": "960px", "descriptionKey": "components.dialog.css_vars.width_lg", "descriptionFallback": "Width token for size=\"large\"."}, {"name": "--origam-dialog---width-xl", "defaultValue": "1080px", "descriptionKey": "components.dialog.css_vars.width_xl", "descriptionFallback": "Width token for size=\"x-large\"."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to inner OrigamOverlay or OrigamCard instances."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.dialog.exposed.css", "descriptionFallback": "Reactive CSS string generated from dialogStyles. Used by OrigamDefaultsProvider for style injection."}, {"name": "id", "type": "string", "descriptionKey": "components.dialog.exposed.id", "descriptionFallback": "Unique style-sheet ID for this dialog instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.dialog.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.dialog.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.dialog.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "contentEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.content_el", "descriptionFallback": "Reference to the overlay content element forwarded from the inner OrigamOverlay ref."}, {"name": "activatorEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.activator_el", "descriptionFallback": "Reference to the activator element forwarded from the inner OrigamOverlay ref."}, {"name": "globalTop", "type": "boolean", "descriptionKey": "components.dialog.exposed.global_top", "descriptionFallback": "True when this dialog is the topmost open overlay in the global stack."}], "playground": {"controls": [{"kind": "select", "prop": "size", "options": [{"label": "x-small (320px)", "value": "x-small"}, {"label": "small (400px)", "value": "small"}, {"label": "default (720px)", "value": "default"}, {"label": "large (960px)", "value": "large"}, {"label": "x-large (1080px)", "value": "x-large"}], "labelKey": "components.dialog.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.dialog.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}, {"kind": "switch", "prop": "scrollable", "labelKey": "components.dialog.playground.scrollable", "defaultValue": false, "labelFallback": "Scrollable"}, {"kind": "switch", "prop": "persistent", "labelKey": "components.dialog.playground.persistent", "defaultValue": false, "labelFallback": "Persistent (no outside-click close)"}, {"kind": "select", "prop": "status", "options": [{"label": "(none)", "value": ""}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog.playground.status", "defaultValue": "", "labelFallback": "Status"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2f8984ad-8ab6-4c7c-92d9-e5c7dac50b25', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'dialog-confirmation', 'DialogConfirmation', 'Overlay & Surface', NULL, 'mdi-check-circle-outline', 'components.catalog.dialog_confirmation.description', 'Opinionated dialog with built-in Validate / Cancel footer buttons and a read-to-enable guard — the Validate button is only enabled once the user has scrolled to the bottom of the content (isRead pattern).', NULL, NULL, 'origam-dialog-confirmation', NULL, 'packages/ds/src/components/Dialog/OrigamDialogConfirmation.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialogConfirmation.html', 'dialog', '{"a11y": {"notes": [{"noteKey": "components.dialog_confirmation.a11y.validate_disabled_note", "noteFallback": "The Validate button is rendered with disabled=true and aria-disabled until the user scrolls to the bottom of the content (isRead=true). This is intentional — it enforces that users read critical content before confirming."}, {"noteKey": "components.dialog_confirmation.a11y.role_note", "noteFallback": "role=\"dialog\" and aria-modal=\"true\" are applied by the inner OrigamDialog on the card element. The title is linked via aria-labelledby."}, {"noteKey": "components.dialog_confirmation.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content. On close, focus returns to the activator element."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog_confirmation.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog_confirmation.a11y.key_tab", "actionFallback": "Cycles focus through Cancel, Validate and any other focusable elements inside the dialog (focus trap inherited from OrigamDialog)."}, {"key": "Shift+Tab", "actionKey": "components.dialog_confirmation.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"24\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">OrigamDialog (inner overlay)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"228\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"68\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend (status icon) | title | append (close)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"92\" width=\"500\" height=\"100\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.12))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"146\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead IntersectionObserver sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"192\" width=\"500\" height=\"72\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.18))\" stroke-width=\"1\"/>\n  <!-- cancel button -->\n  <rect x=\"120\" y=\"212\" width=\"100\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"232\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"system-ui\">Cancel</text>\n  <!-- validate button -->\n  <rect x=\"468\" y=\"212\" width=\"112\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"524\" y=\"232\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"600\">Validate</text>\n  <text x=\"350\" y=\"247\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">Validate enabled only when isRead = true (user scrolled to bottom)</text>\n  <!-- markers -->\n  <circle cx=\"18\" cy=\"18\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"204.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-dialog\n  ref=\"origamDialogRef\"\n  v-model=\"isActive\"\n  v-bind=\"dialogProps\"\n  @is-read=\"handleIsRead\"\n>\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <!-- all header-* slots forwarded -->\n  <template #header><slot name=\"header\" /></template>\n  <template #header-prepend><slot name=\"header-prepend\" /></template>\n  <template #header-title><slot name=\"header-title\" /></template>\n  <!-- … -->\n\n  <template #content><slot name=\"content\" /></template>\n\n  <!-- built-in footer: Cancel + Validate -->\n  <template #footer>\n    <slot name=\"footer\">\n      <origam-container fluid>\n        <origam-row justify=\"space-between\">\n          <origam-col cols=\"auto\">\n            <origam-btn v-if=\"cancellable\" text=\"Cancel\" @click=\"handleCancel\" />\n          </origam-col>\n          <origam-col cols=\"auto\">\n            <origam-btn :disabled=\"!validatable\" text=\"Validate\" @click=\"handleValidate\" />\n          </origam-col>\n        </origam-row>\n      </origam-container>\n    </slot>\n  </template>\n</origam-dialog>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog_confirmation.anatomy.overlay", "descriptionFallback": "Full-viewport overlay inherited from OrigamDialog. Handles click-outside and Escape (unless persistent=true)."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog_confirmation.anatomy.header", "descriptionFallback": "Card header with status icon in prepend slot, title, and close button in append slot. All header-* slots are forwarded transparently."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog_confirmation.anatomy.content", "descriptionFallback": "Scrollable content body. An IntersectionObserver sentinel at the bottom fires the @isRead event when it enters the viewport, enabling the Validate button."}, {"cls": ".origam-card__footer (two-button bar)", "num": 4, "descriptionKey": "components.dialog_confirmation.anatomy.footer", "descriptionFallback": "Default footer with Cancel (left) and Validate (right) in a space-between row. The Validate button is disabled until isRead=true. Override with the #footer slot."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog_confirmation.anatomy.root", "descriptionFallback": "Root class — delegated to the inner OrigamDialog. DialogConfirmation itself has no additional BEM root class."}], "svgDesc": "Schematic of the DialogConfirmation component showing its inner OrigamDialog with header, content, and a two-button footer.", "svgTitle": "Anatomy of OrigamDialogConfirmation", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog-confirmation&gt;</code> — wraps OrigamDialog with 4 zones: ① overlay scrim, ② header (status icon + title), ③ scrollable content + isRead sentinel, ④ two-button footer (Cancel / Validate).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog-confirmation---icon-size", "defaultValue": "28px", "descriptionKey": "components.dialog_confirmation.css_vars.icon_size", "descriptionFallback": "Size of the status icon in the header prepend slot."}, {"name": "--origam-dialog-confirmation---icon-color-default", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_default", "descriptionFallback": "Icon colour when no status is set."}, {"name": "--origam-dialog-confirmation---icon-color-success", "defaultValue": "{color.feedback.success.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_success", "descriptionFallback": "Icon colour when status=\"success\"."}, {"name": "--origam-dialog-confirmation---icon-color-warning", "defaultValue": "{color.feedback.warning.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_warning", "descriptionFallback": "Icon colour when status=\"warning\"."}, {"name": "--origam-dialog-confirmation---icon-color-danger", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_danger", "descriptionFallback": "Icon colour when status=\"danger\"."}, {"name": "--origam-dialog-confirmation---icon-color-info", "defaultValue": "{color.feedback.info.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_info", "descriptionFallback": "Icon colour when status=\"info\"."}, {"name": "--origam-dialog-confirmation---title-font-size", "defaultValue": "{font.size.lg}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_size", "descriptionFallback": "Title font size."}, {"name": "--origam-dialog-confirmation---title-font-weight", "defaultValue": "{font.weight.semibold}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_weight", "descriptionFallback": "Title font weight."}, {"name": "--origam-dialog-confirmation---actions-gap", "defaultValue": "{space.3}", "descriptionKey": "components.dialog_confirmation.css_vars.actions_gap", "descriptionFallback": "Gap between footer action buttons."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog_confirmation.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the inner OrigamDialog."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog_confirmation.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.dialog_confirmation.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "select", "prop": "status", "options": [{"label": "(default)", "value": ""}, {"label": "STATUS.SUCCESS", "value": "STATUS.SUCCESS"}, {"label": "success", "value": "success"}, {"label": "info", "value": "info"}, {"label": "STATUS.INFO", "value": "STATUS.INFO"}, {"label": "STATUS.WARNING", "value": "STATUS.WARNING"}, {"label": "warning", "value": "warning"}, {"label": "error", "value": "error"}, {"label": "STATUS.ERROR", "value": "STATUS.ERROR"}], "labelKey": "components.dialog_confirmation.playground.status", "defaultValue": "", "labelFallback": "Status"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.dialog_confirmation.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "modelValue", "labelKey": "components.dialog_confirmation.playground.model_value", "defaultValue": false, "labelFallback": "Value"}, {"kind": "switch", "prop": "cancellable", "labelKey": "components.dialog_confirmation.playground.cancellable", "defaultValue": true, "labelFallback": "Cancellable"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.dialog_confirmation.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.dialog_confirmation.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7b7686fb-8e3c-464e-8190-b334d10bb852', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'divider', 'Divider', 'Layout & Structure', NULL, 'mdi-minus', 'components.catalog.divider.description', 'Horizontal or vertical separator rendered as a semantic <hr> with color, thickness and inset support.', NULL, NULL, 'origam-divider', NULL, 'packages/ds/src/components/Divider/OrigamDivider.vue', 'origam', NULL, NULL, '/stories/?story=components-divider--design', '/docs/components/Divider/OrigamDivider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.divider.a11y.role_note", "noteFallback": "Renders as a native <hr> element which has an implicit role=\"separator\". The aria-orientation attribute matches the direction prop (horizontal or vertical)."}, {"noteKey": "components.divider.a11y.decorative_note", "noteFallback": "When used purely for visual decoration, pass role=\"presentation\" via attrs to remove the element from the accessibility tree."}], "roles": ["separator"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-divider---color", "descriptionKey": "components.divider.tokens.color", "descriptionFallback": "Default divider color. References the subtle border semantic token."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-divider---thickness", "descriptionKey": "components.divider.tokens.thickness", "descriptionFallback": "Default stroke thickness. Overridden by the thickness prop."}, {"type": "number", "value": "var(--origam-opacity---100)", "tokenPath": "--origam-divider---opacity", "descriptionKey": "components.divider.tokens.opacity", "descriptionFallback": "Token default opacity (1). SCSS overrides to 0.12 for a subtle separator effect."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-divider---margin-block", "descriptionKey": "components.divider.tokens.margin_block", "descriptionFallback": "Default block margin (0). Use the margin prop for spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"350\" y=\"40\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">HORIZONTAL</text>\n  <rect x=\"40\" y=\"55\" width=\"620\" height=\"2\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"48\" cy=\"56\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"350\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">VERTICAL</text>\n  <rect x=\"348\" y=\"120\" width=\"4\" height=\"60\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"350\" cy=\"125\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"129.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"195\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Rendered as &lt;hr&gt; — native HTML separator with role=\"separator\"</text>\n", "code": "<hr\n  role=\"separator\"\n  aria-orientation=\"horizontal\"\n  class=\"origam-divider origam-divider--horizontal\"\n/>", "legend": [{"cls": ".origam-divider", "num": 1, "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root <code>&lt;hr&gt;</code> element. In horizontal mode: <code>display: block; flex: 1 1 100%</code>. <code>aria-orientation=\"horizontal\"</code>."}, {"cls": ".origam-divider--vertical", "num": 2, "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Vertical variant modifier. Switches to <code>display: inline-flex</code>, <code>height: auto</code>, <code>align-self: stretch</code>. <code>aria-orientation=\"vertical\"</code>."}, {"cls": ".origam-divider--inset", "num": 3, "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Inset modifier. Adds <code>margin-inline-start</code> so the line aligns with list item content."}], "classes": [{"cls": "origam-divider", "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root element. Renders as a semantic <hr> with role=\"separator\"."}, {"cls": "origam-divider--horizontal", "descriptionKey": "components.divider.anatomy.horizontal", "descriptionFallback": "Applied when direction=\"horizontal\" (the default). Full-width block line."}, {"cls": "origam-divider--vertical", "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Applied when direction=\"vertical\". Inline-flex stretch line."}, {"cls": "origam-divider--inset", "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Applied when inset=true. Adds a leading margin offset."}], "svgDesc": "Schematic of the Divider component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamDivider", "rootClass": "origam-divider", "figcaption": "Anatomy of <code>&lt;origam-divider&gt;</code>. Horizontal ① is full-width; vertical ② is inline-flex with height: auto. Both render as a native <code>&lt;hr&gt;</code>.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-divider---opacity", "defaultValue": "0.12", "descriptionKey": "components.divider.css_vars.opacity", "descriptionFallback": "Global opacity of the divider line. Token: {opacity.100} resolves to 1; the component overrides to 0.12 by default in SCSS."}, {"name": "--origam-divider---border-top-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_top_width", "descriptionFallback": "Stroke thickness for the horizontal divider. Overridden by the thickness prop."}, {"name": "--origam-divider---border-right-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_right_width", "descriptionFallback": "Stroke thickness for the vertical divider. Overridden by the thickness prop."}, {"name": "--origam-divider---max-width", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_width", "descriptionFallback": "Maximum width for horizontal dividers. Set by the length prop."}, {"name": "--origam-divider---max-height", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_height", "descriptionFallback": "Maximum height for vertical dividers. Set by the length prop."}, {"name": "--origam-divider--inset---margin-inline-start", "defaultValue": "16px", "descriptionKey": "components.divider.css_vars.inset_margin", "descriptionFallback": "Leading indent applied when inset=true."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.divider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.divider.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed dividerStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.divider.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.divider.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.divider.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.divider.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.divider.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.divider.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "inset", "labelKey": "components.divider.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "number", "prop": "thickness", "labelKey": "components.divider.playground.thickness", "defaultValue": 1, "labelFallback": "Thickness (px)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ec681764-c9e1-4252-9949-8b09ed831d6a', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'drawer', 'Drawer', 'Layout & Structure', NULL, 'mdi-page-layout-sidebar-left', 'components.catalog.drawer.description', 'Side-panel navigation drawer that integrates with the Origam layout grid. Supports rail/mini mode, expand-on-hover, temporary/persistent variants, touch drag, and four docking edges (left, right, top, bottom).', NULL, NULL, 'origam-drawer', NULL, 'packages/ds/src/components/Drawer/OrigamDrawer.vue', 'origam', NULL, NULL, '/stories/?story=components-drawer--design', '/docs/components/Drawer/OrigamDrawer.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.drawer.a11y.nav_note", "noteFallback": "The root element renders as <nav> by default (configurable via the tag prop). This gives it an implicit navigation landmark role, discoverable by screen reader landmark navigation."}, {"noteKey": "components.drawer.a11y.label_note", "noteFallback": "The root element carries aria-label set to the name prop (or \"Navigation\" as fallback). Provide a meaningful name prop when multiple navigation landmarks exist on the page."}, {"noteKey": "components.drawer.a11y.scrim_note", "noteFallback": "The scrim overlay in temporary mode is purely decorative and hidden from assistive technologies. It only handles click events to close the drawer."}], "roles": ["navigation"], "keyboard": [{"key": "Tab / Shift+Tab", "actionKey": "components.drawer.a11y.key_tab", "actionFallback": "Moves focus between interactive elements inside the drawer."}, {"key": "Escape", "actionKey": "components.drawer.a11y.key_escape", "actionFallback": "Closes the drawer when in temporary mode (if the overlay scrim is active)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-drawer---background", "descriptionKey": "components.drawer.tokens.background", "descriptionFallback": "Drawer surface background color."}, {"type": "shadow", "value": "var(--origam-shadow---none)", "tokenPath": "--origam-drawer---box-shadow", "descriptionKey": "components.drawer.tokens.box_shadow", "descriptionFallback": "Default shadow (none for permanent). Overridden to shadow.lg in temporary mode."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-drawer---transition-duration", "descriptionKey": "components.drawer.tokens.transition_duration", "descriptionFallback": "Open/close animation duration."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-drawer__temporary---box-shadow", "descriptionKey": "components.drawer.tokens.temporary_box_shadow", "descriptionFallback": "Shadow applied when the drawer is in temporary mode to elevate it above the scrim."}, {"type": "color", "value": "var(--origam-color__overlay---scrim)", "tokenPath": "--origam-drawer__scrim---background", "descriptionKey": "components.drawer.tokens.scrim_background", "descriptionFallback": "Background of the scrim shown behind the temporary drawer."}, {"type": "number", "value": "0.2", "tokenPath": "--origam-drawer__scrim---opacity", "descriptionKey": "components.drawer.tokens.scrim_opacity", "descriptionFallback": "Scrim opacity in temporary mode. Tracks drag progress during touch open/close."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- drawer panel -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- prepend zone -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.07))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"54\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#prepend</text>\n  <!-- content zone -->\n  <rect x=\"30\" y=\"80\" width=\"200\" height=\"140\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"130\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default (scrollable)</text>\n  <!-- append zone -->\n  <rect x=\"30\" y=\"220\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"254\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#append</text>\n  <!-- layout reservation hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.02)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"6 4\"/>\n  <text x=\"460\" y=\"155\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">layout main content (offset by drawer width)</text>\n  <!-- numbering -->\n  <circle cx=\"38\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"88\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"92.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"38\" cy=\"228\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"232.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"38\" cy=\"148\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <!-- scrim overlay hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.06)\" stroke=\"rgba(0,0,0,0.1)\" stroke-width=\"1\" stroke-dasharray=\"3 3\" opacity=\"0.5\"/>\n  <text x=\"460\" y=\"40\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">scrim (temporary mode only)</text>\n", "code": "<teleport :to=\"layoutTarget\" :disabled=\"isLayoutOrphan\">\n  <origam-transition :transition=\"transition\">\n    <!-- root: nav by default -->\n    <nav v-if=\"isActive\" class=\"origam-drawer origam-drawer--left\">\n      <!-- inner wrapper: prepend | content | append -->\n      <div class=\"origam-drawer__wrapper\">\n        <!-- fixed header slot -->\n        <div class=\"origam-drawer__prepend\">\n          <slot name=\"prepend\" />\n        </div>\n\n        <!-- scrollable navigation content -->\n        <div class=\"origam-drawer__content\">\n          <slot name=\"default\" />\n        </div>\n\n        <!-- fixed footer slot -->\n        <div class=\"origam-drawer__append\">\n          <slot name=\"append\" />\n        </div>\n      </div>\n    </nav>\n  </origam-transition>\n\n  <!-- scrim: visible only in temporary mode -->\n  <origam-overlay-scrim :active=\"isTemporary && isActive\" @click=\"close\" />\n</teleport>", "legend": [{"cls": ".origam-drawer", "num": 1, "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root nav element. Teleported into <code>#layout-id .origam-layout__wrapper</code> so it participates in the layout grid. Renders inline when no OrigamLayout ancestor exists."}, {"cls": ".origam-drawer__prepend", "num": 2, "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed zone above the scrollable content. Rendered only when the #prepend slot is filled. <code>flex: none</code> so it does not participate in content scrolling."}, {"cls": ".origam-drawer__append", "num": 3, "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed zone below the scrollable content. Rendered only when the #append slot is filled. <code>flex: none</code>."}, {"cls": ".origam-drawer__content", "num": 4, "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable content area hosting the #default slot. <code>overflow-y: auto</code>; fills remaining height between prepend and append."}], "classes": [{"cls": "origam-drawer", "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root element. Controls all layout, transition, and z-index properties."}, {"cls": "origam-drawer--left", "descriptionKey": "components.drawer.anatomy.left", "descriptionFallback": "Applied when location=\"left\". Sets top: 0; left: 0 and right: auto, with border-right-width: thin."}, {"cls": "origam-drawer--right", "descriptionKey": "components.drawer.anatomy.right", "descriptionFallback": "Applied when location=\"right\". Sets top: 0; left: auto; right: 0, with border-left-width: thin."}, {"cls": "origam-drawer--temporary", "descriptionKey": "components.drawer.anatomy.temporary", "descriptionFallback": "Applied when temporary=true. Applies shadow.lg and shows the scrim."}, {"cls": "origam-drawer--rail", "descriptionKey": "components.drawer.anatomy.rail", "descriptionFallback": "Applied when rail=true. Collapses width to railWidth (default 56px)."}, {"cls": "origam-drawer--expand-on-hover", "descriptionKey": "components.drawer.anatomy.expand_on_hover", "descriptionFallback": "Applied when expandOnHover=true. Enables the hover-triggered width transition."}, {"cls": "origam-drawer--floating", "descriptionKey": "components.drawer.anatomy.floating", "descriptionFallback": "Applied when floating=true. Removes the side border."}, {"cls": "origam-drawer--sticky", "descriptionKey": "components.drawer.anatomy.sticky", "descriptionFallback": "Applied when sticky=true. Switches height to auto and uses position: sticky."}, {"cls": "origam-drawer__wrapper", "descriptionKey": "components.drawer.anatomy.wrapper", "descriptionFallback": "Inner flex container. Hosts prepend, content, and append zones in a column layout."}, {"cls": "origam-drawer__content", "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable main area. overflow-y: auto; flex: 0 1 auto; height: 100%."}, {"cls": "origam-drawer__prepend", "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed header area. flex: none."}, {"cls": "origam-drawer__append", "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed footer area. flex: none."}], "svgDesc": "Schematic of the Drawer component showing the three-zone layout: prepend, content, append.", "svgTitle": "Anatomy of OrigamDrawer", "rootClass": "origam-drawer", "figcaption": "Anatomy of <code>&lt;origam-drawer&gt;</code> — 4 parts: ① root drawer panel (teleported into the layout grid), ② prepend zone (fixed header), ③ append zone (fixed footer), ④ scrollable content (#default slot).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-drawer---background", "defaultValue": "{color.surface.default}", "descriptionKey": "components.drawer.css_vars.background", "descriptionFallback": "Background color of the drawer panel."}, {"name": "--origam-drawer---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.drawer.css_vars.color", "descriptionFallback": "Foreground (text/icon) color."}, {"name": "--origam-drawer---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.drawer.css_vars.box_shadow", "descriptionFallback": "Box shadow. Applied to shadow.lg automatically in temporary mode."}, {"name": "--origam-drawer---width", "defaultValue": "100%", "descriptionKey": "components.drawer.css_vars.width", "descriptionFallback": "Drawer panel width. Driven by the width prop and layout item styles (useLayoutItem)."}, {"name": "--origam-drawer---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.drawer.css_vars.transition_duration", "descriptionFallback": "Duration of the open/close slide animation."}, {"name": "--origam-drawer---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.drawer.css_vars.transition_timing_function", "descriptionFallback": "Easing function for the open/close transition."}, {"name": "--origam-drawer__scrim---background", "defaultValue": "{color.overlay.scrim}", "descriptionKey": "components.drawer.css_vars.scrim_background", "descriptionFallback": "Scrim overlay background color (temporary mode)."}, {"name": "--origam-drawer__scrim---opacity", "defaultValue": "0.2", "descriptionKey": "components.drawer.css_vars.scrim_opacity", "descriptionFallback": "Scrim opacity. Animates with drag progress during touch drag."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.drawer.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.drawer.exposed.css", "descriptionFallback": "Reactive CSS string from drawerStyles. Used by OrigamDefaultsProvider."}, {"name": "id", "type": "string", "descriptionKey": "components.drawer.exposed.id", "descriptionFallback": "Unique style-sheet ID for this drawer instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.drawer.exposed.load", "descriptionFallback": "Injects the computed style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.drawer.exposed.unload", "descriptionFallback": "Removes the injected style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.drawer.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}], "labelKey": "components.drawer.playground.location", "defaultValue": "left", "labelFallback": "Location"}, {"kind": "switch", "prop": "temporary", "labelKey": "components.drawer.playground.temporary", "defaultValue": false, "labelFallback": "Temporary"}, {"kind": "switch", "prop": "rail", "labelKey": "components.drawer.playground.rail", "defaultValue": false, "labelFallback": "Rail mode"}, {"kind": "switch", "prop": "expandOnHover", "labelKey": "components.drawer.playground.expand_on_hover", "defaultValue": false, "labelFallback": "Expand on hover"}, {"kind": "switch", "prop": "floating", "labelKey": "components.drawer.playground.floating", "defaultValue": false, "labelFallback": "Floating (no border)"}], "defaultSlotContent": "Navigation content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('530679b5-8135-42e3-89cb-241f6d2e0963', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'empty-state', 'EmptyState', 'Feedback & Status', NULL, 'mdi-inbox-outline', 'components.catalog.empty_state.description', 'Placeholder shown when a list, table or collection has nothing to display. Five visual presets (no-data, no-results, error, offline, locked) bundle icon + intent; both are overridable via props or slots.', NULL, NULL, 'origam-empty-state', NULL, 'packages/ds/src/components/EmptyState/OrigamEmptyState.vue', 'origam', NULL, NULL, '/stories/?story=components-emptystate--design', '/docs/components/EmptyState/OrigamEmptyState.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.empty_state.a11y.live_region", "noteFallback": "The root has role=\"status\" and aria-live=\"polite\". Screen readers announce the state change when the component appears or when preset changes without a page reload."}, {"noteKey": "components.empty_state.a11y.icon_hidden", "noteFallback": "The icon container carries aria-hidden=\"true\" — it is decorative. The meaningful information is in the title and description text nodes."}, {"noteKey": "components.empty_state.a11y.actions", "noteFallback": "Actions inside the #actions slot must individually carry correct roles (button, link). EmptyState does not wrap or intercept keyboard events."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---10)", "tokenPath": "--origam-empty-state---padding-block-md", "descriptionKey": "components.empty_state.tokens.padding_block_md", "descriptionFallback": "Block padding for size=md (40px)."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-empty-state---gap-md", "descriptionKey": "components.empty_state.tokens.gap_md", "descriptionFallback": "Gap between sections for size=md (16px)."}, {"type": "dimension", "value": "480px", "tokenPath": "--origam-empty-state---max-width", "descriptionKey": "components.empty_state.tokens.max_width", "descriptionFallback": "Max width of the description text zone."}, {"type": "dimension", "value": "64px", "tokenPath": "--origam-empty-state__icon---size-md", "descriptionKey": "components.empty_state.tokens.icon_size_md", "descriptionFallback": "Icon size for size=md."}, {"type": "dimension", "value": "var(--origam-font__size---xl)", "tokenPath": "--origam-empty-state__title---font-size-md", "descriptionKey": "components.empty_state.tokens.title_font_size_md", "descriptionFallback": "Title font size for size=md (1.25rem)."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-empty-state__description---color", "descriptionKey": "components.empty_state.tokens.description_color", "descriptionFallback": "Description text colour."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"208\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"280\" y=\"32\" width=\"140\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__icon</text>\n  <rect x=\"160\" y=\"100\" width=\"380\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"117\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__title</text>\n  <rect x=\"100\" y=\"136\" width=\"500\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"153\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__description</text>\n  <rect x=\"250\" y=\"172\" width=\"200\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"194\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__actions</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"280\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"160\" cy=\"104\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"160\" y=\"108\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"100\" cy=\"140\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"100\" y=\"144\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"250\" cy=\"176\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"250\" y=\"180\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- root: role=\"status\" aria-live=\"polite\" -->\n<div class=\"origam-empty-state origam-empty-state--size-md origam-empty-state--align-center\">\n\n  <!-- icon area — aria-hidden -->\n  <div class=\"origam-empty-state__icon\" aria-hidden=\"true\">\n    <slot name=\"icon\">\n      <origam-icon class=\"origam-empty-state__icon-glyph\" />\n    </slot>\n  </div>\n\n  <!-- title — v-if=\"hasTitle\" -->\n  <div class=\"origam-empty-state__title\">\n    <slot name=\"title\">{{ title }}</slot>\n  </div>\n\n  <!-- description — v-if=\"hasDescription\" -->\n  <div class=\"origam-empty-state__description\">\n    <slot name=\"description\">{{ description }}</slot>\n  </div>\n\n  <!-- actions — v-if=\"hasActions\" -->\n  <div class=\"origam-empty-state__actions\">\n    <slot name=\"actions\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-empty-state", "num": 1, "descriptionKey": "components.empty_state.anatomy.root", "descriptionFallback": "Root element. Has role=\"status\" aria-live=\"polite\". Flex column. Width 100%."}, {"cls": ".origam-empty-state__icon", "num": 2, "descriptionKey": "components.empty_state.anatomy.icon", "descriptionFallback": "Icon container. aria-hidden=\"true\". Contains OrigamIcon or the #icon slot."}, {"cls": ".origam-empty-state__title", "num": 3, "descriptionKey": "components.empty_state.anatomy.title", "descriptionFallback": "Title element. Rendered when the title prop or the #title slot is present."}, {"cls": ".origam-empty-state__description", "num": 4, "descriptionKey": "components.empty_state.anatomy.description", "descriptionFallback": "Description element. Width clamped by --origam-empty-state---max-width (480px default). Rendered when description prop or #description slot is present."}, {"cls": ".origam-empty-state__actions", "num": 5, "descriptionKey": "components.empty_state.anatomy.actions", "descriptionFallback": "Actions row. Inline-flex with wrap. Rendered only when the #actions slot is provided."}], "classes": [{"cls": "origam-empty-state", "descriptionKey": "components.empty_state.anatomy.root", "descriptionFallback": "Root element. role=\"status\" aria-live=\"polite\". Flex column layout."}, {"cls": "origam-empty-state__icon", "descriptionKey": "components.empty_state.anatomy.icon", "descriptionFallback": "Icon wrapper with aria-hidden=\"true\". Centres the icon glyph."}, {"cls": "origam-empty-state__icon-glyph", "descriptionKey": "components.empty_state.anatomy.icon_glyph", "descriptionFallback": "OrigamIcon instance inside the icon wrapper. Inherits size and colour from CSS vars."}, {"cls": "origam-empty-state__title", "descriptionKey": "components.empty_state.anatomy.title", "descriptionFallback": "Title text element."}, {"cls": "origam-empty-state__description", "descriptionKey": "components.empty_state.anatomy.description", "descriptionFallback": "Description text element. max-width clamped by token."}, {"cls": "origam-empty-state__actions", "descriptionKey": "components.empty_state.anatomy.actions", "descriptionFallback": "Inline-flex actions row with gap and top margin."}], "svgDesc": "Schematic of the EmptyState component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamEmptyState", "rootClass": "origam-empty-state", "figcaption": "Anatomy of <code>&lt;origam-empty-state&gt;</code> — 5 internal parts. The root ① carries <code>role=\"status\"</code> and <code>aria-live=\"polite\"</code>; each section is conditionally rendered.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-empty-state---padding-block", "defaultValue": "{space.10} (40px)", "descriptionKey": "components.empty_state.css_vars.padding_block", "descriptionFallback": "Block padding of the root element. Per-size variants override this value."}, {"name": "--origam-empty-state---padding-inline", "defaultValue": "{space.6} (24px)", "descriptionKey": "components.empty_state.css_vars.padding_inline", "descriptionFallback": "Inline padding of the root element."}, {"name": "--origam-empty-state---gap", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.empty_state.css_vars.gap", "descriptionFallback": "Flex gap between icon, title, description and actions. Per-size overrides apply."}, {"name": "--origam-empty-state---max-width", "defaultValue": "480px", "descriptionKey": "components.empty_state.css_vars.max_width", "descriptionFallback": "Maximum width of the description text for readable line length."}, {"name": "--origam-empty-state__icon---size", "defaultValue": "64px", "descriptionKey": "components.empty_state.css_vars.icon_size", "descriptionFallback": "Icon font-size / size. Overridden per size class (sm=48px, md=64px, lg=96px)."}, {"name": "--origam-empty-state__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.empty_state.css_vars.icon_color", "descriptionFallback": "Icon colour. Overridden per intent modifier class (e.g. --intent-danger maps to danger feedback colour)."}, {"name": "--origam-empty-state__title---font-size", "defaultValue": "{font.size.xl} (1.25rem)", "descriptionKey": "components.empty_state.css_vars.title_font_size", "descriptionFallback": "Title font size. Overridden per size class."}, {"name": "--origam-empty-state__description---font-size", "defaultValue": "{font.size.md} (1rem)", "descriptionKey": "components.empty_state.css_vars.description_font_size", "descriptionFallback": "Description font size. Overridden per size class."}], "exposed": [{"name": "resolvedIcon", "type": "ComputedRef<TIcon>", "descriptionKey": "components.empty_state.exposed.resolved_icon", "descriptionFallback": "The resolved icon: user icon prop wins over preset default."}, {"name": "resolvedIntent", "type": "ComputedRef<TIntent>", "descriptionKey": "components.empty_state.exposed.resolved_intent", "descriptionFallback": "The resolved intent: user iconColor prop wins over preset default."}, {"name": "hasDefaultSlot", "type": "ComputedRef<boolean>", "descriptionKey": "components.empty_state.exposed.has_default_slot", "descriptionFallback": "True when the default slot is provided — replaces the built-in layout entirely."}, {"name": "hasTitle", "type": "ComputedRef<boolean>", "descriptionKey": "components.empty_state.exposed.has_title", "descriptionFallback": "True when a title prop or #title slot is present."}, {"name": "hasDescription", "type": "ComputedRef<boolean>", "descriptionKey": "components.empty_state.exposed.has_description", "descriptionFallback": "True when a description prop or #description slot is present."}, {"name": "hasActions", "type": "ComputedRef<boolean>", "descriptionKey": "components.empty_state.exposed.has_actions", "descriptionFallback": "True when the #actions slot is provided."}], "playground": {"controls": [{"kind": "select", "prop": "preset", "options": [{"label": "no-data", "value": "no-data"}, {"label": "no-results", "value": "no-results"}, {"label": "error", "value": "error"}, {"label": "offline", "value": "offline"}, {"label": "locked", "value": "locked"}], "labelKey": "components.empty_state.playground.preset", "defaultValue": "no-data", "labelFallback": "Preset"}, {"kind": "text", "prop": "title", "labelKey": "components.empty_state.playground.title", "defaultValue": "Nothing to show yet", "labelFallback": "Title"}, {"kind": "text", "prop": "description", "labelKey": "components.empty_state.playground.description", "defaultValue": "Create your first item to get started.", "labelFallback": "Description"}, {"kind": "select", "prop": "size", "options": [{"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.empty_state.playground.size", "defaultValue": "md", "labelFallback": "Size"}, {"kind": "select", "prop": "align", "options": [{"label": "center", "value": "center"}, {"label": "left", "value": "left"}], "labelKey": "components.empty_state.playground.align", "defaultValue": "center", "labelFallback": "Align"}]}, "previewVariants": [{"label": "no-data", "props": {"title": "No data", "preset": "no-data", "description": "Nothing to show yet."}}, {"label": "no-results", "props": {"size": "sm", "title": "No results", "preset": "no-results"}}, {"label": "error", "props": {"title": "Something went wrong", "preset": "error", "description": "Please try again."}}, {"label": "offline", "props": {"size": "sm", "title": "You are offline", "preset": "offline"}}, {"label": "locked", "props": {"align": "left", "title": "Access denied", "preset": "locked"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2a7fd1b2-7565-4ddb-9a9a-299b03bbca2f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'expand-x', 'ExpandX', 'Utilities & Providers', NULL, 'mdi-arrow-expand-horizontal', 'components.catalog.transition_expand_x.description', 'JS-driven horizontal width expand/collapse transition. Animates the element width from 0 to its natural offsetWidth (enter) and back to 0 (leave). Duration 0.5s with cubic-bezier(0.4, 0, 0.2, 1).', NULL, NULL, 'origam-expand-x', NULL, 'packages/ds/src/components/Transition/OrigamExpandX.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamExpandX.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.expand_x.a11y.reduced_motion", "noteFallback": "Set disabled=true to suppress all animations for users with prefers-reduced-motion: reduce. OrigamDatePickerMonth passes this prop automatically when the media query matches."}, {"noteKey": "components.expand_x.a11y.no_role", "noteFallback": "ExpandX is transparent to the accessibility tree — it adds no ARIA roles or attributes. Only the slotted content is visible to screen readers."}, {"noteKey": "components.expand_x.a11y.overflow", "noteFallback": "During the transition, overflow: hidden is set on the element to prevent content from showing outside the animated bounds. The original overflow is restored in afterEnter / afterLeave."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- enter phase: 0 → full width -->\n  <rect x=\"40\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"40\" y=\"40\" width=\"60\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"none\"/>\n  <text x=\"180\" y=\"76\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"180\" y=\"92\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">width: 0 → offsetWidth</text>\n  <!-- arrow -->\n  <text x=\"350\" y=\"84\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n  <!-- leave phase: full width → 0 -->\n  <rect x=\"380\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.55\"/>\n  <rect x=\"600\" y=\"40\" width=\"60\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"none\" opacity=\"0.55\"/>\n  <text x=\"520\" y=\"76\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">leave-active</text>\n  <text x=\"520\" y=\"92\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">width: offsetWidth → 0</text>\n  <!-- markers -->\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"388\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"388\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamExpandX — JS-driven <transition> -->\n<transition\n  name=\"origam-transition--expand-x\"\n  mode=\"in-out\"\n  :css=\"!disabled\"\n  @before-enter=\"handleBeforeEnter\"\n  @enter=\"handleEnter\"\n  @after-enter=\"handleAfterEnter\"\n  @enter-cancelled=\"handleEnterCancelled\"\n  @leave=\"handleLeave\"\n  @after-leave=\"handleAfterLeave\"\n  @leave-cancelled=\"handleLeaveCancelled\"\n>\n  <slot name=\"default\" />\n</transition>", "legend": [{"cls": ".origam-transition--expand-x-enter-active", "num": 1, "descriptionKey": "components.expand_x.anatomy.enter_active", "descriptionFallback": "Enter phase. CSS class drives transition-duration (0.5s), timing (cubic-bezier(0.4,0,0.2,1)) and transition-property (width). The JS beforeEnter hook stashes the initial width; enter sets width to 0 then requestAnimationFrame restores offsetWidth."}, {"cls": ".origam-transition--expand-x-leave-active", "num": 2, "descriptionKey": "components.expand_x.anatomy.leave_active", "descriptionFallback": "Leave phase. CSS class drives transition-duration (0.5s), timing and transition-property. The JS leave hook stashes the current width and animates to 0. afterLeave restores the initial style."}], "classes": [{"cls": "origam-transition--expand-x-enter-active", "descriptionKey": "components.expand_x.anatomy.enter_active", "descriptionFallback": "Applied during enter. Sets transition-property: width, duration 0.5s."}, {"cls": "origam-transition--expand-x-leave-active", "descriptionKey": "components.expand_x.anatomy.leave_active", "descriptionFallback": "Applied during leave. Sets transition-property: width, duration 0.5s."}, {"cls": "origam-transition--expand-x-move", "descriptionKey": "components.expand_x.anatomy.move", "descriptionFallback": "Applied to elements repositioning in a group transition. Sets transition-property: transform, duration 0.5s."}], "svgDesc": "Schematic showing width expansion from 0 to natural size on enter, and collapse on leave.", "svgTitle": "Anatomy of OrigamExpandX", "rootClass": "origam-transition--expand-x", "figcaption": "Anatomy of <code>&lt;origam-expand-x&gt;</code> — wraps a single element. JS hooks read <code>offsetWidth</code> to animate width from 0 → natural size on enter ①, and back to 0 on leave ②. <code>overflow: hidden</code> is set during the transition to prevent content overflow.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition--expand-x-enter-active---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.enter_duration", "descriptionFallback": "Duration of the enter (expand) animation."}, {"name": "--origam-transition--expand-x-enter-active---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_x.css_vars.enter_timing", "descriptionFallback": "Easing function for the enter animation."}, {"name": "--origam-transition--expand-x-enter-active---transition-property", "defaultValue": "width", "descriptionKey": "components.expand_x.css_vars.enter_property", "descriptionFallback": "CSS property animated on enter."}, {"name": "--origam-transition--expand-x-enter-leave---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.leave_duration", "descriptionFallback": "Duration of the leave (collapse) animation."}, {"name": "--origam-transition--expand-x-enter-leave---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_x.css_vars.leave_timing", "descriptionFallback": "Easing function for the leave animation."}, {"name": "--origam-transition--expand-x-enter-leave---transition-property", "defaultValue": "width", "descriptionKey": "components.expand_x.css_vars.leave_property", "descriptionFallback": "CSS property animated on leave."}, {"name": "--origam-transition--expand-x-move---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_x.css_vars.move_duration", "descriptionFallback": "Duration of the move animation in group transitions."}, {"name": "--origam-transition--expand-x-move---transition-property", "defaultValue": "transform", "descriptionKey": "components.expand_x.css_vars.move_property", "descriptionFallback": "CSS property animated during group moves."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expand_x.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.expand_x.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.expand_x.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('47fbd0dc-91d3-4617-8052-16af09f39d49', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'expand-y', 'ExpandY', 'Utilities & Providers', NULL, 'mdi-arrow-expand-vertical', 'components.catalog.transition_expand_y.description', 'JS-driven vertical height expand/collapse transition. Animates the element height from 0 to its natural offsetHeight (enter) and back to 0 (leave). Duration 0.5s with cubic-bezier(0.4, 0, 0.2, 1). Commonly used for accordion and collapsible content.', NULL, NULL, 'origam-expand-y', NULL, 'packages/ds/src/components/Transition/OrigamExpandY.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamExpandY.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.expand_y.a11y.reduced_motion", "noteFallback": "Set disabled=true to suppress all animations for users with prefers-reduced-motion: reduce. OrigamExpansionPanel passes this automatically when the media query matches."}, {"noteKey": "components.expand_y.a11y.no_role", "noteFallback": "ExpandY is transparent to the accessibility tree — it adds no ARIA roles or attributes. Only the slotted content is visible to screen readers."}, {"noteKey": "components.expand_y.a11y.overflow", "noteFallback": "During the transition, overflow: hidden is set on the element to prevent content from showing outside the animated bounds. The original overflow is restored in afterEnter / afterLeave."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- enter phase: 0 → full height -->\n  <rect x=\"80\" y=\"20\" width=\"220\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"80\" y=\"140\" width=\"220\" height=\"40\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"none\"/>\n  <text x=\"190\" y=\"100\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"190\" y=\"118\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">height: 0 → offsetHeight</text>\n  <!-- arrow -->\n  <text x=\"350\" y=\"115\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n  <!-- leave phase: full height → 0 -->\n  <rect x=\"400\" y=\"20\" width=\"220\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.55\"/>\n  <rect x=\"400\" y=\"20\" width=\"220\" height=\"40\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"none\" opacity=\"0.55\"/>\n  <text x=\"510\" y=\"100\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">leave-active</text>\n  <text x=\"510\" y=\"118\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.7\">height: offsetHeight → 0</text>\n  <!-- markers -->\n  <circle cx=\"88\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamExpandY — JS-driven <transition> -->\n<transition\n  name=\"origam-transition--expand-y\"\n  mode=\"in-out\"\n  :css=\"!disabled\"\n  @before-enter=\"handleBeforeEnter\"\n  @enter=\"handleEnter\"\n  @after-enter=\"handleAfterEnter\"\n  @enter-cancelled=\"handleEnterCancelled\"\n  @leave=\"handleLeave\"\n  @after-leave=\"handleAfterLeave\"\n  @leave-cancelled=\"handleLeaveCancelled\"\n>\n  <slot name=\"default\" />\n</transition>", "legend": [{"cls": ".origam-transition--expand-y-enter-active", "num": 1, "descriptionKey": "components.expand_y.anatomy.enter_active", "descriptionFallback": "Enter phase. CSS class drives transition-duration (0.5s), timing (cubic-bezier(0.4,0,0.2,1)) and transition-property (height). The JS beforeEnter hook stashes the initial height; enter sets height to 0 then requestAnimationFrame restores offsetHeight."}, {"cls": ".origam-transition--expand-y-leave-active", "num": 2, "descriptionKey": "components.expand_y.anatomy.leave_active", "descriptionFallback": "Leave phase. CSS class drives transition-duration (0.5s) and property (height). The JS leave hook stashes the current height and animates to 0. afterLeave restores the initial style."}], "classes": [{"cls": "origam-transition--expand-y-enter-active", "descriptionKey": "components.expand_y.anatomy.enter_active", "descriptionFallback": "Applied during enter. Sets transition-property: height, duration 0.5s."}, {"cls": "origam-transition--expand-y-leave-active", "descriptionKey": "components.expand_y.anatomy.leave_active", "descriptionFallback": "Applied during leave. Sets transition-property: height, duration 0.5s."}, {"cls": "origam-transition--expand-y-move", "descriptionKey": "components.expand_y.anatomy.move", "descriptionFallback": "Applied to elements repositioning in a group transition. Sets transition-property: transform, duration 0.5s."}], "svgDesc": "Schematic showing height expansion from 0 to natural size on enter, and collapse on leave.", "svgTitle": "Anatomy of OrigamExpandY", "rootClass": "origam-transition--expand-y", "figcaption": "Anatomy of <code>&lt;origam-expand-y&gt;</code> — wraps a single element. JS hooks read <code>offsetHeight</code> to animate height from 0 → natural size on enter ①, and back to 0 on leave ②. <code>overflow: hidden</code> is set during the transition. ExpandY is the backbone of <code>&lt;origam-expansion-panel&gt;</code>.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-transition--expand-y-enter-active---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_y.css_vars.enter_duration", "descriptionFallback": "Duration of the enter (expand) animation."}, {"name": "--origam-transition--expand-y-enter-active---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_y.css_vars.enter_timing", "descriptionFallback": "Easing function for the enter animation."}, {"name": "--origam-transition--expand-y-enter-active---transition-property", "defaultValue": "height", "descriptionKey": "components.expand_y.css_vars.enter_property", "descriptionFallback": "CSS property animated on enter."}, {"name": "--origam-transition--expand-y-enter-leave---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_y.css_vars.leave_duration", "descriptionFallback": "Duration of the leave (collapse) animation."}, {"name": "--origam-transition--expand-y-enter-leave---transition-timing-function", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.expand_y.css_vars.leave_timing", "descriptionFallback": "Easing function for the leave animation."}, {"name": "--origam-transition--expand-y-enter-leave---transition-property", "defaultValue": "height", "descriptionKey": "components.expand_y.css_vars.leave_property", "descriptionFallback": "CSS property animated on leave."}, {"name": "--origam-transition--expand-y-move---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_y.css_vars.move_duration", "descriptionFallback": "Duration of the move animation in group transitions."}, {"name": "--origam-transition--expand-y-move---transition-property", "defaultValue": "transform", "descriptionKey": "components.expand_y.css_vars.move_property", "descriptionFallback": "CSS property animated during group moves."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expand_y.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.expand_y.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.expand_y.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b2ed691c-1d0e-4caa-b957-22c1782465d9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'expansion-panel', 'ExpansionPanel', 'Layout & Structure', NULL, 'mdi-chevron-down-box-outline', 'components.catalog.expansion_panel.description', 'Collapsible panel with animated header and content reveal. Supports accordion, popout and inset layout modes; optional loader, ripple and density controls.', NULL, NULL, 'origam-expansion-panel', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanel.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.expansion_panel.a11y.aria_expanded", "noteFallback": "The header button carries aria-expanded=\"true|false\" reflecting the current panel state. Screen readers announce the expanded/collapsed status."}, {"noteKey": "components.expansion_panel.a11y.aria_controls", "noteFallback": "The header button carries aria-controls pointing to the content region ID. The content region carries aria-labelledby pointing to the header ID."}, {"noteKey": "components.expansion_panel.a11y.disabled", "noteFallback": "Disabled panels use tabindex=\"-1\" on the header and add aria-disabled via the disabled HTML attribute."}, {"noteKey": "components.expansion_panel.a11y.reduced_motion", "noteFallback": "The expand/collapse animation respects prefers-reduced-motion: the transition-duration is overridden to 0ms."}], "roles": ["button", "region"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.expansion_panel.a11y.key_activate", "actionFallback": "Toggles the panel expanded/collapsed when focus is on the header button."}, {"key": "Tab", "actionKey": "components.expansion_panel.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element (next header or content)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-expansion-panel---background", "descriptionKey": "components.expansion_panel.tokens.background", "descriptionFallback": "Panel background — raised surface."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-expansion-panel---border-radius", "descriptionKey": "components.expansion_panel.tokens.border_radius", "descriptionFallback": "Panel corner radius."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-expansion-panel---transition-duration", "descriptionKey": "components.expansion_panel.tokens.transition_duration", "descriptionFallback": "Transition duration for expand/collapse animations."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-expansion-panel---active-margin-top", "descriptionKey": "components.expansion_panel.tokens.active_margin_top", "descriptionFallback": "Margin above active panels (16px)."}, {"type": "dimension", "value": "48px", "tokenPath": "--origam-expansion-panel__header---min-height", "descriptionKey": "components.expansion_panel.tokens.header_min_height", "descriptionFallback": "Header minimum height at rest."}, {"type": "dimension", "value": "64px", "tokenPath": "--origam-expansion-panel__header---min-height-active", "descriptionKey": "components.expansion_panel.tokens.header_min_height_active", "descriptionFallback": "Header minimum height when panel is expanded."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.18))\"/>\n  <rect x=\"48\" y=\"32\" width=\"604\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"61\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-expansion-panel-header (button)</text>\n  <rect x=\"48\" y=\"96\" width=\"604\" height=\"76\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"138\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-expansion-panel-content (role=region)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"36\" cy=\"20\" r=\"7\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"36\" y=\"23\" font-size=\"7\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"56\" cy=\"104\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"108\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-expansion-panel\">\n  <!-- shadow pseudo-element -->\n  <div class=\"origam-expansion-panel__shadow\" />\n\n  <!-- conditional loader -->\n  <div class=\"origam-expansion-panel__loader\"><!-- OrigamProgress --></div>\n\n  <!-- header (button) -->\n  <origam-expansion-panel-header\n    class=\"origam-expansion-panel__header\"\n    aria-expanded=\"false\"\n    aria-controls=\"expansion-panel-content-{id}\"\n  >\n    <slot name=\"prepend\" />\n    <slot name=\"title\" />\n    <!-- expand/collapse icon -->\n  </origam-expansion-panel-header>\n\n  <!-- content (region) -->\n  <origam-expansion-panel-content\n    class=\"origam-expansion-panel__content\"\n    role=\"region\"\n    aria-labelledby=\"expansion-panel-header-{id}\"\n  >\n    <slot name=\"default\" />\n  </origam-expansion-panel-content>\n</div>", "legend": [{"cls": ".origam-expansion-panel", "num": 1, "descriptionKey": "components.expansion_panel.anatomy.root", "descriptionFallback": "Root element. Flex container for shadow, header and content."}, {"cls": ".origam-expansion-panel__shadow", "num": 2, "descriptionKey": "components.expansion_panel.anatomy.shadow", "descriptionFallback": "Absolutely positioned shadow layer. Uses box-shadow token. z-index: -1 prevents clipping content."}, {"cls": ".origam-expansion-panel__header / origam-expansion-panel-header", "num": 3, "descriptionKey": "components.expansion_panel.anatomy.header", "descriptionFallback": "Rendered as a <button> with aria-expanded and aria-controls. Carries the overlay, wrapper, prepend, title, append and expand icon."}, {"cls": ".origam-expansion-panel__content / origam-expansion-panel-content", "num": 4, "descriptionKey": "components.expansion_panel.anatomy.content", "descriptionFallback": "Content region with role=\"region\" and aria-labelledby. Animated via OrigamExpandY transition. Hosts the default slot."}], "classes": [{"cls": "origam-expansion-panel", "descriptionKey": "components.expansion_panel.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-expansion-panel--active", "descriptionKey": "components.expansion_panel.anatomy.active", "descriptionFallback": "Applied when the panel is selected/expanded."}, {"cls": "origam-expansion-panel--disabled", "descriptionKey": "components.expansion_panel.anatomy.disabled", "descriptionFallback": "Applied when disabled. Dims the header via overlay opacity."}, {"cls": "origam-expansion-panel__shadow", "descriptionKey": "components.expansion_panel.anatomy.shadow", "descriptionFallback": "Absolute shadow layer. z-index: -1."}, {"cls": "origam-expansion-panel-header", "descriptionKey": "components.expansion_panel.anatomy.header_class", "descriptionFallback": "Header button root. Carries aria-expanded, aria-controls, ripple."}, {"cls": "origam-expansion-panel-header__wrapper", "descriptionKey": "components.expansion_panel.anatomy.header_wrapper", "descriptionFallback": "Inner flex row: prepend | title | append."}, {"cls": "origam-expansion-panel-content", "descriptionKey": "components.expansion_panel.anatomy.content_class", "descriptionFallback": "Content region. role=\"region\" with aria-labelledby referencing header ID."}, {"cls": "origam-expansion-panel-content__wrapper", "descriptionKey": "components.expansion_panel.anatomy.content_wrapper", "descriptionFallback": "Inner padding wrapper for the panel body content."}], "svgDesc": "Schematic of the ExpansionPanel component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanel", "rootClass": "origam-expansion-panel", "figcaption": "Anatomy of <code>&lt;origam-expansion-panel&gt;</code> — 4 internal parts. The shadow ① is an absolutely-positioned sibling. Header ③ is a <code>&lt;button&gt;</code> with aria-expanded. Content ④ has <code>role=\"region\"</code> and <code>aria-labelledby</code> pointing to the header.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-expansion-panel---border-radius", "defaultValue": "{radius.sm} (4px)", "descriptionKey": "components.expansion_panel.css_vars.border_radius", "descriptionFallback": "Panel corner radius. Reset to 0 on inner panels in accordion/flat mode."}, {"name": "--origam-expansion-panel---transition-duration", "defaultValue": "{motion.duration.slow} (0.3s)", "descriptionKey": "components.expansion_panel.css_vars.transition_duration", "descriptionFallback": "Transition duration for margin, radius and max-width changes on expand/collapse."}, {"name": "--origam-expansion-panel---active-margin-top", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.expansion_panel.css_vars.active_margin_top", "descriptionFallback": "Margin applied above an active panel (and the panel following it) to visually separate it from siblings."}, {"name": "--origam-expansion-panel---divider-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.expansion_panel.css_vars.divider_color", "descriptionFallback": "Colour of the ::after separator line between panels (non-accordion mode)."}, {"name": "--origam-expansion-panel---divider-opacity", "defaultValue": "0.12", "descriptionKey": "components.expansion_panel.css_vars.divider_opacity", "descriptionFallback": "Opacity of the ::after separator. Fades to 0 adjacent to active panels."}, {"name": "--origam-expansion-panel__shadow---box-shadow", "defaultValue": "{shadow.sm}", "descriptionKey": "components.expansion_panel.css_vars.shadow_box_shadow", "descriptionFallback": "Box shadow of the elevation pseudo-element."}, {"name": "--origam-expansion-panel---header-min-height", "defaultValue": "48px", "descriptionKey": "components.expansion_panel.css_vars.header_min_height", "descriptionFallback": "Header minimum height at rest. Increases to 64px when the panel is active."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expansion_panel.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to header/content sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.expansion_panel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.expansion_panel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.expansion_panel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.expansion_panel.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.expansion_panel.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.expansion_panel.playground.title", "defaultValue": "Panel title", "labelFallback": "Title"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.expansion_panel.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}], "labelKey": "components.expansion_panel.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.expansion_panel.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "hideActions", "labelKey": "components.expansion_panel.playground.hide_actions", "defaultValue": false, "labelFallback": "Hide actions"}], "defaultSlotContent": "This is the panel body content."}, "previewVariants": [{"label": "default", "props": {}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('047b85b3-5f38-46bc-a674-d81a15ed70e4', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'expansion-panel-content', 'ExpansionPanelContent', 'Layout & Structure', NULL, 'mdi-card-text-outline', 'components.catalog.expansion_panel_content.description', 'Animated content region revealed when the parent ExpansionPanel is expanded. Has role="region" and aria-labelledby pointing to the header.', NULL, NULL, 'origam-expansion-panel-content', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanelContent.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panel_content.a11y.aria_labelledby", "noteFallback": "The content root carries aria-labelledby pointing to the sibling header ID, associating the region with its label for screen readers."}, {"noteKey": "components.expansion_panel_content.a11y.visibility", "noteFallback": "Uses v-show to hide the content — it remains in the DOM (unless eager=false and not yet revealed) so focus management works correctly after expand."}, {"noteKey": "components.expansion_panel_content.a11y.lazy", "noteFallback": "Content is lazily rendered on first expand (unless eager is true). After first expand, the DOM is preserved on collapse via v-show."}], "roles": ["region"], "keyboard": [{"key": "Tab", "actionKey": "components.expansion_panel_content.a11y.key_tab", "actionFallback": "Moves focus into and out of the content region when it is expanded."}]