ss_vars.focus_overlay_opacity", "descriptionFallback": "Overlay opacity when the header is focused (focus-visible)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expansion_panel_header.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.expansion_panel_header.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.expansion_panel_header.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.expansion_panel_header.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.expansion_panel_header.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.expansion_panel_header.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.expansion_panel_header.playground.title", "defaultValue": "Panel header", "labelFallback": "Title"}, {"kind": "select", "prop": "expandIcon", "options": [{"label": "chevron-down", "value": "mdi-chevron-down"}, {"label": "plus", "value": "mdi-plus"}, {"label": "arrow-down", "value": "mdi-arrow-down"}], "labelKey": "components.expansion_panel_header.playground.expand_icon", "defaultValue": "mdi-chevron-down", "labelFallback": "Expand icon"}, {"kind": "switch", "prop": "hideActions", "labelKey": "components.expansion_panel_header.playground.hide_actions", "defaultValue": false, "labelFallback": "Hide actions"}, {"kind": "switc