INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('865f346b-da45-4baf-ab07-3bd69dbd4a04', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'expansion-panels', 'ExpansionPanels', 'Layout & Structure', NULL, 'mdi-view-list-outline', 'components.catalog.expansion_panels.description', 'Container managing a group of ExpansionPanel items. Supports accordion, flat, popout and inset display modes. Props cascade to all child panels via DefaultsProvider.', NULL, NULL, 'origam-expansion-panels', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanels.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panels.a11y.group_management", "noteFallback": "The container manages group selection state and propagates it to child panels via inject/provide. Each panel header receives aria-expanded and aria-controls independently."}, {"noteKey": "components.expansion_panels.a11y.cascade", "noteFallback": "Visual props (density, color, bgColor, rounded, border) are cascaded via OrigamDefaultsProvider so all child panels share the same visual treatment without per-panel repetition."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.expansion_panels.a11y.key_tab", "actionFallback": "Moves focus between panel headers in sequence."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "calc(100% - 32px)", "tokenPath": "--origam-expansion-panel__popout---max-width", "descriptionKey": "components.expansion_panels.tokens.popout_ma