ionFallback": "Root container element."}, {"cls": "origam-expansion-panels--accordion", "descriptionKey": "components.expansion_panels.anatomy.accordion", "descriptionFallback": "Accordion mode: panels are flush, one open at a time."}, {"cls": "origam-expansion-panels--flat", "descriptionKey": "components.expansion_panels.anatomy.flat", "descriptionFallback": "Flat mode: no shadow, no border separator."}, {"cls": "origam-expansion-panels--popout", "descriptionKey": "components.expansion_panels.anatomy.popout", "descriptionFallback": "Popout mode: active panel extends beyond container width."}, {"cls": "origam-expansion-panels--inset", "descriptionKey": "components.expansion_panels.anatomy.inset", "descriptionFallback": "Inset mode: active panel shrinks inside container width."}], "svgDesc": "Schematic of the ExpansionPanels container with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanels", "rootClass": "origam-expansion-panels", "figcaption": "Anatomy of <code>&lt;origam-expansion-panels&gt;</code>. The root ① is a flex container wrapping all child panels ②. Mode modifiers (accordion, flat, popout, inset) are applied as root class modifiers.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-expansion-panel__popout---max-width", "defaultValue": "calc(100% - 32px)", "descriptionKey": "components.expansion_panels.css_vars.popout_max_width", "descriptionFallback": "Width of inactive panels in popout mode."}, {"name": "--origam-expansion-panel__popout---max-width-active", "defaultValue": "calc(100% + 16px)", "descriptionKey": "components.expansion_panels.css_vars.popout_max_width_active", "descriptionFallback": "Width of the active panel in popout mode."}, {"name": "--origam-expansion-panel__inset---max-width", "defaultValue": "100%", "descriptionKey": "components.expansion_panels.css_vars.inset_max_width", "descriptionFallback": "Width of inactive panels in inset mode."}, {"name": "--origam-expansion-panel__inset---max-width-active", "defaultValue": "calc(100% - 32px)", "descriptionKey": "components.expansion_panels.css_vars.inset_max_width_active", "descriptionFallback": "Width of the active panel in inset mode."}, {"name": "--origam-expansion-panel__accordion---header-overlay-transition", "defaultValue": "{motion.duration.slow} (0.3s)", "descriptionKey": "components.expansion_panels.css_vars.accordion_header_overlay_transition", "descriptionFallback": "Transition duration for the header overlay border-radius animation in accordion mode."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expansion_panels.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.expansion_panels.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.expansion_panels.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.expansion_panels.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.expansion_panels.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.expansion_panels.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "switch", "prop": "accordion", "labelKey": "components.expansion_panels.playground.accordion", "defaultValue": false, "labelFallback": "Accordion"}, {"kind": "switch", "prop": "flat", "labelKey": "components.expansion_panels.playground.flat", "defaultValue": false, "labelFallback": "Flat"}, {"kind": "switch", "prop": "popout", "labelKey": "components.expansion_panels.playground.popout", "defaultValue": false, "labelFallback": "Popout"}, {"kind": "switch", "prop": "inset", "labelKey": "components.expansion_panels.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.expansion_panels.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.expansion_panels.playground.color", "defaultValue": "", "labelFallback": "Color"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('05d8214d-8dcf-4df2-a972-0f7b4257d019', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'fade', 'Fade', 'Utilities & Providers', NULL, 'mdi-transition', 'components.catalog.fade.description', 'Opacity-only enter/leave CSS transition. A thin wrapper around the generic Transition that sets name="origam-transition--fade".', NULL, NULL, 'origam-fade', NULL, 'packages/ds/src/components/Transition/OrigamFade.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.fade.a11y.reduced_motion", "noteFallback": "useCssTransition automatically sets disabled=true when prefers-reduced-motion: reduce is detected. Content appears/disappears instantly with no opacity animation."}, {"noteKey": "components.fade.a11y.transparent", "noteFallback": "The transition wrapper adds no elements to the DOM — it is transparent to the accessibility tree. Only the slotted content is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"75\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"91\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 0 → 1</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.45\"/>\n  <text x=\"530\" y=\"75\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"91\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 1 → 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"80\" font-size=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>", "legend": [{"cls": ".origam-transition--fade-enter-active", "num": 1, "descriptionKey": "components.fade.anatomy.enter", "descriptionFallback": "Applied to the entering element. Sets transition-property: opacity, duration: 0.3s, easing: cubic-bezier(0.4, 0, 0.2, 1)."}, {"cls": ".origam-transition--fade-leave-active", "num": 2, "descriptionKey": "components.fade.anatomy.leave", "descriptionFallback": "Applied to the leaving element. Same duration and easing. Opacity animates from 1 to 0 via .origam-transition--fade-leave-to."}], "classes": [{"cls": "origam-transition--fade", "descriptionKey": "components.fade.anatomy.cls_root", "descriptionFallback": "Transition name used as the CSS class prefix for enter/leave phases."}, {"cls": "origam-transition--fade-enter-active", "descriptionKey": "components.fade.anatomy.cls_enter_active", "descriptionFallback": "Active entering phase: transition-property: opacity; duration: 0.3s."}, {"cls": "origam-transition--fade-leave-active", "descriptionKey": "components.fade.anatomy.cls_leave_active", "descriptionFallback": "Active leaving phase: same timing as enter."}, {"cls": "origam-transition--fade-enter-from", "descriptionKey": "components.fade.anatomy.cls_enter_from", "descriptionFallback": "Initial state of the entering element: opacity: 0."}, {"cls": "origam-transition--fade-leave-to", "descriptionKey": "components.fade.anatomy.cls_leave_to", "descriptionFallback": "Final state of the leaving element: opacity: 0."}, {"cls": "origam-transition--fade-move", "descriptionKey": "components.fade.anatomy.cls_move", "descriptionFallback": "Applied to sibling elements that shift position when group=true. Animates transform over 0.5s."}], "svgDesc": "Schematic showing the fade transition: an entering element at full opacity and a leaving element at opacity 0.", "svgTitle": "Anatomy of OrigamFade", "rootClass": "origam-transition--fade", "figcaption": "Anatomy of <code>&lt;origam-fade&gt;</code> — wraps a single child. During the transition, the entering element ① fades from <code>opacity: 0</code> to <code>1</code> while the leaving element ② fades from <code>1</code> to <code>0</code> over 300 ms.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.fade.css_vars.duration", "descriptionFallback": "Fade enter/leave duration (300 ms). Hardcoded in the SCSS block as 0.3s; override via the token rebuild."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.fade.css_vars.easing", "descriptionFallback": "Easing function for both enter and leave phases: cubic-bezier(0.4, 0, 0.2, 1)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.fade.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying transition element."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.fade.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.fade.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "group", "labelKey": "components.fade.playground.group", "defaultValue": false, "labelFallback": "Group"}, {"kind": "switch", "prop": "hideOnLeave", "labelKey": "components.fade.playground.hide_on_leave", "defaultValue": false, "labelFallback": "Hide On Leave"}, {"kind": "switch", "prop": "leaveAbsolute", "labelKey": "components.fade.playground.leave_absolute", "defaultValue": false, "labelFallback": "Leave Absolute"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a904eb72-f089-41ec-9e79-2633a4558eff', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'field', 'Field', 'Form & Input', NULL, 'mdi-form-textbox', 'components.catalog.field.description', 'Shared form-field shell used by all input components (TextField, NumberField, PasswordField…). Provides the label, prefix/suffix, prepend/append-inner zones, loader, outline/underline rendering and error state. Not intended for direct use — consume through a specific input component.', NULL, NULL, 'origam-field', NULL, 'packages/ds/src/components/Field/OrigamField.vue', 'origam', NULL, NULL, '/stories/?story=components-field--design', '/docs/components/Field/OrigamField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.field.a11y.label_for", "noteFallback": "The floating label is wired to the input via the id passed through the default slot props. Consumers must bind the id from slotProps to their <input> id attribute."}, {"noteKey": "components.field.a11y.aria_describedby", "noteFallback": "The aria-describedby attribute is provided through the default slot props and must be forwarded to the native <input> so screen readers read associated messages."}, {"noteKey": "components.field.a11y.error_state", "noteFallback": "When error is truthy, the --error modifier class is applied. Consumers are responsible for adding aria-invalid=\"true\" to the native input."}, {"noteKey": "components.field.a11y.required", "noteFallback": "The required prop appends * to the label. The native required attribute must be added to the <input> element directly by the consuming component."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.field.a11y.key_tab", "actionFallback": "Moves focus to the embedded input element (passed via #default slot)."}, {"key": "Escape", "actionKey": "components.field.a11y.key_escape", "actionFallback": "Clears the field when clearable=true and focus is inside the field."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-field---border-radius", "descriptionKey": "components.field.tokens.border_radius", "descriptionFallback": "Field corner radius (4px)."}, {"type": "color", "value": "var(--origam-color__border---default)", "tokenPath": "--origam-field---border-color", "descriptionKey": "components.field.tokens.border_color", "descriptionFallback": "Default border colour."}, {"type": "number", "value": "0.38", "tokenPath": "--origam-field---border-opacity", "descriptionKey": "components.field.tokens.border_opacity", "descriptionFallback": "Border opacity at rest (translucent on inactive state)."}, {"type": "dimension", "value": "16px", "tokenPath": "--origam-field---font-size", "descriptionKey": "components.field.tokens.font_size", "descriptionFallback": "Base input font size."}, {"type": "dimension", "value": "6px", "tokenPath": "--origam-field__input---padding-block-md", "descriptionKey": "components.field.tokens.input_padding_block_md", "descriptionFallback": "Block padding for size=default (36px control). Centres input text vertically."}, {"type": "color", "value": "var(--origam-color__feedback--danger---border)", "tokenPath": "--origam-field--error---border-color", "descriptionKey": "components.field.tokens.error_border_color", "descriptionFallback": "Border colour in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"60\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__label (floating)</text>\n  <rect x=\"28\" y=\"56\" width=\"200\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\"/>\n  <rect x=\"28\" y=\"134\" width=\"644\" height=\"2\" rx=\"1\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.3))\"/>\n  <text x=\"350\" y=\"150\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">loader (OrigamProgress)</text>\n  <rect x=\"48\" y=\"72\" width=\"60\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"78\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">prepend</text>\n  <rect x=\"116\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"136\" y=\"104\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">prefix</text>\n  <rect x=\"164\" y=\"72\" width=\"300\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"314\" y=\"104\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__input (#default slot)</text>\n  <rect x=\"472\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"492\" y=\"104\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">suffix</text>\n  <rect x=\"520\" y=\"72\" width=\"40\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"540\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">clear</text>\n  <rect x=\"568\" y=\"72\" width=\"84\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"610\" y=\"104\" font-size=\"7.5\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">append</text>\n  <circle cx=\"36\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n", "code": "<div class=\"origam-field origam-field--variant-outlined\">\n  <!-- interaction overlay -->\n  <div class=\"origam-field__overlay\" />\n\n  <!-- loader (OrigamProgress) — v-if hasLoader -->\n  <div class=\"origam-field__loader\"><origam-progress /></div>\n\n  <!-- prepend inner icon / avatar -->\n  <div class=\"origam-field__prepend-inner\">\n    <slot name=\"prependInner\" />\n  </div>\n\n  <!-- input area: label + prefix + #default + suffix -->\n  <div class=\"origam-field__field\">\n    <label class=\"origam-field__label\">{{ label }}</label>\n    <span class=\"origam-field__prefix\">{{ prefix }}</span>\n    <slot name=\"default\" v-bind=\"slotProps\" />\n    <span class=\"origam-field__suffix\">{{ suffix }}</span>\n  </div>\n\n  <!-- clearable button — v-if showClear -->\n  <div class=\"origam-field__clearable\">\n    <origam-icon :icon=\"clearIcon\" />\n  </div>\n\n  <!-- append inner icon / avatar -->\n  <div class=\"origam-field__append-inner\">\n    <slot name=\"appendInner\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-field", "num": 1, "descriptionKey": "components.field.anatomy.root", "descriptionFallback": "Root grid container. display: grid; grid-template-areas: \"prepend-inner field clear append-inner\"."}, {"cls": ".origam-field__overlay", "num": 2, "descriptionKey": "components.field.anatomy.overlay", "descriptionFallback": "Interaction scrim (hover/focus ripple). pointer-events: none."}, {"cls": ".origam-field__prepend-inner", "num": 3, "descriptionKey": "components.field.anatomy.prepend_inner", "descriptionFallback": "Leading icon/avatar zone inside the field border."}, {"cls": ".origam-field__field", "num": 4, "descriptionKey": "components.field.anatomy.field", "descriptionFallback": "Input area containing label, prefix, #default slot and suffix."}, {"cls": ".origam-field__clearable", "num": 5, "descriptionKey": "components.field.anatomy.clearable", "descriptionFallback": "Clear icon button. Shown when clearable=true and field is dirty/focused."}, {"cls": ".origam-field__append-inner", "num": 6, "descriptionKey": "components.field.anatomy.append_inner", "descriptionFallback": "Trailing icon/avatar zone inside the field border."}, {"cls": ".origam-field__loader", "num": 7, "descriptionKey": "components.field.anatomy.loader", "descriptionFallback": "Progress bar at the bottom of the field. Rendered when loading is active and kind !== skeleton."}], "classes": [{"cls": "origam-field", "descriptionKey": "components.field.anatomy.root", "descriptionFallback": "Root grid container."}, {"cls": "origam-field--variant-outlined", "descriptionKey": "components.field.anatomy.variant_outlined", "descriptionFallback": "Variant modifier. One of: outlined, underlined, filled, solo, solo-filled, solo-inverted, plain."}, {"cls": "origam-field--focused", "descriptionKey": "components.field.anatomy.focused", "descriptionFallback": "Applied when the embedded input has focus."}, {"cls": "origam-field--error", "descriptionKey": "components.field.anatomy.error", "descriptionFallback": "Applied when the error prop is truthy. Changes border and label colour to the danger semantic."}, {"cls": "origam-field__overlay", "descriptionKey": "components.field.anatomy.overlay", "descriptionFallback": "Interaction scrim layer."}, {"cls": "origam-field__field", "descriptionKey": "components.field.anatomy.field", "descriptionFallback": "Core input region containing label, prefix, slot and suffix."}, {"cls": "origam-field__prepend-inner", "descriptionKey": "components.field.anatomy.prepend_inner", "descriptionFallback": "Leading inner icon/avatar zone."}, {"cls": "origam-field__append-inner", "descriptionKey": "components.field.anatomy.append_inner", "descriptionFallback": "Trailing inner icon/avatar zone."}, {"cls": "origam-field__clearable", "descriptionKey": "components.field.anatomy.clearable", "descriptionFallback": "Clear button zone."}, {"cls": "origam-field__loader", "descriptionKey": "components.field.anatomy.loader", "descriptionFallback": "Progress loader zone at the bottom."}], "svgDesc": "Schematic of the Field component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamField", "rootClass": "origam-field", "figcaption": "Anatomy of <code>&lt;origam-field&gt;</code> — 7 internal zones. The field is a CSS Grid with columns: prepend-inner / input / clear / append-inner. Label floats above the top edge when active.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-field---border-radius", "defaultValue": "{radius.sm} (4px)", "descriptionKey": "components.field.css_vars.border_