", "descriptionFallback": "Default indentation per nesting level."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-list-group---prepend-width", "descriptionKey": "components.list_group.tokens.prepend_width", "descriptionFallback": "Prepend area width added to the indent calculation when a prepend zone is present."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"220\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- activator wrapper -->\n  <rect x=\"48\" y=\"60\" width=\"604\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"94\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-list-group-activator (.origam-list-group__activator)</text>\n  <text x=\"350\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#activator slot → default: origam-list-item (.origam-list-group__header)</text>\n  <!-- items zone -->\n  <rect x=\"48\" y=\"130\" width=\"604\" height=\"110\" rx=\"3\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"160\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">div.origam-list-group__items (v-if isOpen, role=group)</text>\n  <text x=\"350\" y=\"178\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">--origam-list---indent-padding applied to children</text>\n  <text x=\"350\" y=\"220\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">#items slot</text>\n  <!-- numbers -->\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"72.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"138\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"142.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-group</text>\n", "legend": [{"cls": ".origam-list-group", "num": 1, "descriptionKey": "components.list_group.anatomy.root", "descriptionFallback": "Root element. Carries modifier classes: <code>--prepend</code>, <code>--append</code>, <code>--fluid</code>, <code>--open</code>. Uses <code>v-contrast</code> directive for automatic contrast correction."}, {"cls": ".origam-list-group__activator", "num": 2, "descriptionKey": "components.list_group.anatomy.activator", "descriptionFallback": "OrigamListGroupActivator wrapper around the header slot. Registers the activator context for nested group detection (<code>useNestedGroupActivator</code>)."}, {"cls": ".origam-list-group__items", "num": 3, "descriptionKey": "components.list_group.anatomy.items", "descriptionFallback": "Collapsible container. Rendered only when <code>isOpen</code> is true (<code>v-if</code>). Wrapped in <code>OrigamExpandY</code> for enter/leave animation. Sets <code>role=\"group\"</code> and <code>aria-labelledby</code> pointing to the activator id."}], "svgDesc": "Schematic of the ListGroup component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamListGroup", "rootClass": "origam-list-group", "figcaption": "Anatomy of <code>&lt;origam-list-group&gt;</code> — 3 primary zones: root ①, activator wrapper ②, and the collapsible items container ③ with an animated OrigamExpandY transition.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-list-group---list-indent-size", "defaultValue": "{space.4}", "descriptionKey": "components.list_group.css_vars.list_indent_size", "descriptionFallback": "Amount by which nested items are indented. Set to 0 by --fluid modifier."}, {"name": "--origam-list-group---prepend-width", "defaultValue": "{space.4}", "descriptionKey": "components.list_group.css_vars.prepend_width", "descriptionFallback": "Width of the prepend area accounted for in the nested indent calculation."}, {"name": "--origam-list-group---parent-padding", "defaultValue": "0px", "descriptionKey": "components.list_group.css_vars.parent_padding", "descriptionFallback": "Cumulative indent from parent groups. Grows with each nesting level."}, {"name": "--origam-list-group__header--active---opacity", "defaultValue": "0", "descriptionKey": "components.list_group.css_vars.header_active_opacity", "descriptionFallback": "Overlay opacity of the activator item when the group is open. Defaults to 0 (no tint on active header)."}, {"name": "--origam-list-group__header--active--hover---opacity", "defaultValue": "0", "descriptionKey": "components.list_group.css_vars.header_active_hover_opacity", "descriptionFallback": "Overlay opacity on hover when the activator is in active/open state. A scoped calc (0.04 * 1) is applied in the component SCSS."}], "exposed": [{"name": "isOpen", "type": "Ref<boolean>", "descriptionKey": "components.list_group.exposed.is_open", "descriptionFallback": "Reactive ref reflecting whether the group is currently expanded."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "ComputedRef<string>", "descriptionKey": "components.list_group.exposed.id", "descriptionFallback": "Computed unique ID used for aria-labelledby on the items container."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_group.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_group.playground.title", "defaultValue": "Settings", "labelFallback": "Title"}, {"kind": "switch", "prop": "fluid", "labelKey": "components.list_group.playground.fluid", "defaultValue": false, "labelFallback": "Fluid (no indent)"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-cog", "value": "mdi-cog"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-folder", "value": "mdi-folder"}], "labelKey": "components.list_group.playground.prepend_icon", "defaultValue": "mdi-cog", "labelFallback": "Prepend icon"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('05962fd0-6527-4c79-abc1-0a730b203f8f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'list-group-activator', 'ListGroupActivator', 'Data Display', NULL, 'mdi-format-list-group', 'components.catalog.list_group_activator.description', 'Internal wrapper component that registers the nested group activator context via useNestedGroupActivator. Consumed internally by OrigamListGroup to wire the toggle header to the expand/collapse mechanism.', NULL, NULL, 'origam-list-group-activator', NULL, 'packages/ds/src/components/List/OrigamListGroupActivator.vue', 'origam', NULL, NULL, '/stories/?story=components-list--design', '/docs/components/List/OrigamList.html', 'list-group', '{"a11y": {"notes": [{"noteKey": "components.list_group_activator.a11y.context", "noteFallback": "OrigamListGroupActivator is a context-only wrapper — it has no ARIA role or keyboard contract of its own. The slotted content (OrigamListItem) owns the interactive surface with the correct aria-expanded and role=\"button\" attributes."}, {"noteKey": "components.list_group_activator.a11y.transparent", "noteFallback": "The component renders a plain <div> (or tag prop value) with no ARIA attributes added at this level. It is transparent to the accessibility tree."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"38\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"60\" y=\"44\" width=\"560\" height=\"52\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"340\" y=\"73\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot — ListItem / custom activator header</text>\n  <circle cx=\"68\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"68\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<component :is=\"tag\" class=\"origam-list-group-activator\">\n  <slot name=\"default\" />\n</component>", "legend": [{"cls": ".origam-list-group-activator", "num": 1, "descriptionKey": "components.list_group_activator.anatomy.root", "descriptionFallback": "Root element. Rendered via <component :is=\"tag\"> — defaults to <div>. Registers the nested group activator context via useNestedGroupActivator() on mount."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.list_group_activator.anatomy.slot", "descriptionFallback": "Default slot content — the interactive header element (usually an OrigamListItem) that the user clicks to expand/collapse the ListGroup."}], "classes": [{"cls": "origam-list-group-activator", "descriptionKey": "components.list_group_activator.anatomy.root", "descriptionFallback": "Root wrapper element. Registers useNestedGroupActivator context so child ListItems can toggle the parent ListGroup open/close state."}], "svgDesc": "Schematic showing the activator wrapper element wrapping the header slot content.", "svgTitle": "Anatomy of OrigamListGroupActivator", "rootClass": "origam-list-group-activator", "figcaption": "Anatomy of <code>&lt;origam-list-group-activator&gt;</code> — a transparent wrapper ① rendered as the tag prop value (default: <code>&lt;div&gt;</code>). The default slot ② holds the activator header content (typically a ListItem).", "svgViewBox": "0 0 700 140"}, "cssVars": [], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_group_activator.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_group_activator.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.list_group_activator.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_group_activator.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_group_activator.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_group_activator.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('27d9a1b0-023e-432c-8f26-7f2d67f8029b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'list-item', 'ListItem', 'Data Display', NULL, 'mdi-format-list-bulleted', 'components.catalog.list_item.description', 'Single row inside a List. Supports prepend/append icons or avatars, title, subtitle, active state, and polymorphic link rendering.', NULL, NULL, 'origam-list-item', NULL, 'packages/ds/src/components/List/OrigamListItem.vue', 'origam', NULL, NULL, '/stories/?story=components-list-item--design', '/docs/components/List/OrigamListItem.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_item.a11y.disabled_note", "noteFallback": "When disabled=true and rendered as an anchor, aria-disabled=\"true\" is set instead of the disabled attribute. Pointer events are removed via CSS."}, {"noteKey": "components.list_item.a11y.link_note", "noteFallback": "When href or to is set, the item renders as a native <a> element — full keyboard navigation and focus management are inherited from the browser."}, {"noteKey": "components.list_item.a11y.selection_note", "noteFallback": "When inside a selectable list (value prop set), selection state is driven by useNestedItem. The active CSS class provides a visual selected indicator."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.list_item.a11y.key_activate", "actionFallback": "Activates a clickable item (fires click event, navigates, or toggles selection)."}, {"key": "Tab", "actionKey": "components.list_item.a11y.key_tab", "actionFallback": "Moves focus. tabindex=0 for standalone clickable items; tabindex=-2 inside a list group."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "56px", "tokenPath": "--origam-list__item---min-height", "descriptionKey": "components.list_item.tokens.min_height", "descriptionFallback": "Default minimum row height."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-list-item---padding-inline-start", "descriptionKey": "components.list_item.tokens.padding_inline_start", "descriptionFallback": "Default inline-start padding (16px). Added to list indent-padding and density."}, {"type": "color", "value": "currentColor", "tokenPath": "--origam-list__item---overlay-background-color", "descriptionKey": "components.list_item.tokens.overlay_background_color", "descriptionFallback": "Overlay tint color for hover/active states."}, {"type": "dimension", "value": "var(--origam-font__size---lg)", "tokenPath": "--origam-list__item---title-font-size", "descriptionKey": "components.list_item.tokens.title_font_size", "descriptionFallback": "Title font size (1rem)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__item---subtitle-font-size", "descriptionKey": "components.list_item.tokens.subtitle_font_size", "descriptionFallback": "Subtitle font size (0.875rem)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"42\" width=\"56\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"100\" y=\"42\" width=\"416\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"108\" y=\"50\" width=\"248\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"232\" y=\"62\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">title</text>\n  <rect x=\"108\" y=\"74\" width=\"180\" height=\"12\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"198\" y=\"84\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">subtitle</text>\n  <rect x=\"528\" y=\"42\" width=\"140\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"598\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\"/>\n  <rect x=\"20\" y=\"110\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.12))\"/>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"60\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"308\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"308\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"232\" cy=\"46\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"232\" y=\"50\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"198\" cy=\"70\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"198\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"598\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"598\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"28\" cy=\"108\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"28\" y=\"112\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-item</text>\n  <text x=\"350\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑦ = overlay — absolute, opacity: 0 at rest, visible on hover/active</text>\n", "legend": [{"cls": ".origam-list-item", "num": 1, "descriptionKey": "components.list_item.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;div&gt;</code> by default, <code>&lt;a&gt;</code> when href/to is set. Grid container: 3 columns (prepend / content / append)."}, {"cls": ".origam-list-item__prepend", "num": 2, "descriptionKey": "components.list_item.anatomy.prepend", "descriptionFallback": "Leading icon/avatar zone. <code>grid-area: prepend</code>. Renders <code>prependIcon</code>, <code>prependAvatar</code>, or the <code>#prepend</code> slot. <code>v-if=\"hasPrepend\"</code>."}, {"cls": ".origam-list-item__content", "num": 3, "descriptionKey": "components.list_item.anatomy.content", "descriptionFallback": "<code>grid-area: content</code>. Contains title, subtitle and the <code>#default</code> slot."}, {"cls": ".origam-list-item__title", "num": 4, "descriptionKey": "components.list_item.anatomy.title", "descriptionFallback": "Primary text. Truncates with ellipsis (white-space: nowrap). <code>v-if=\"hasTitle\"</code>."}, {"cls": ".origam-list-item__subtitle", "num": 5, "descriptionKey": "components.list_item.anatomy.subtitle", "descriptionFallback": "Secondary text. Uses <code>-webkit-box</code> clamp via the <code>lines</code> prop. <code>v-if=\"hasSubtitle\"</code>."}, {"cls": ".origam-list-item__append", "num": 6, "descriptionKey": "components.list_item.anatomy.append", "descriptionFallback": "Trailing icon/avatar zone. <code>grid-area: append</code>. Renders <code>appendIcon</code>, <code>appendAvatar</code>, or the <code>#append</code> slot. <code>v-if=\"hasAppend\"</code>."}, {"cls": ".origam-list-item__overlay", "num": 7, "descriptionKey": "components.list_item.anatomy.overlay", "descriptionFallback": "Absolute interaction scrim. <code>opacity: 0</code> at rest → 0.08 on hover/focus → 0.12 when active. Only rendered when the item is clickable or active."}], "svgDesc": "Schematic of the ListItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamListItem", "rootClass": "origam-list-item", "figcaption": "Anatomy of <code>&lt;origam-list-item&gt;</code> — 7 internal parts. The grid layout places prepend ② / content ③ / append ⑥ in a 3-column grid. Title ④ and subtitle ⑤ live inside content. The overlay ⑦ is an absolute layer that paints hover/active tints.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-list-item---min-height", "defaultValue": "40px", "descriptionKey": "components.list_item.css_vars.min_height", "descriptionFallback": "Minimum row height. Adjusted by the density modifier."}, {"name": "--origam-list-item---padding-block-start", "defaultValue": "8px", "descriptionKey": "components.list_item.css_vars.padding_block_start", "descriptionFallback": "Block-start padding. Added to the density offset."}, {"name": "--origam-list-item---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.list_item.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding. Added to the indent-padding and density offsets."}, {"name": "--origam-list-item---border-radius", "defaultValue": "0px", "descriptionKey": "components.list_item.css_vars.border_radius", "descriptionFallback": "Item border radius. Overridden by the rounded prop."}, {"name": "--origam-list-item---cursor", "defaultValue": "pointer", "descriptionKey": "components.list_item.css_vars.cursor", "descriptionFallback": "Cursor style when the item is in link/clickable mode."}, {"name": "--origam-list-item---opacity", "defaultValue": "0.6", "descriptionKey": "components.list_item.css_vars.opacity", "descriptionFallback": "Opacity applied when the item is disabled."}, {"name": "--origam-list-item__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.list_item.css_vars.overlay_opacity", "descriptionFallback": "Overlay opacity. Animates to 0.08 on hover/focus and 0.12 when active."}, {"name": "--origam-list-item__title---font-size", "defaultValue": "1rem", "descriptionKey": "components.list_item.css_vars.title_font_size", "descriptionFallback": "Title font size. Overridden to 0.8125rem in nav mode."}, {"name": "--origam-list-item__subtitle---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_item.css_vars.subtitle_font_size", "descriptionFallback": "Subtitle font size."}], "exposed": [{"name": "isGroupActivator", "type": "boolean", "descriptionKey": "components.list_item.exposed.is_group_activator", "descriptionFallback": "True when this item acts as the activator of a ListGroup. Prevents selection toggling on click."}, {"name": "isSelected", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_selected", "descriptionFallback": "Reactive selection state from useNestedItem. True when the item value is selected in the parent list."}, {"name": "list", "type": "ListProvide | null", "descriptionKey": "components.list_item.exposed.list", "descriptionFallback": "Parent list context injected by OrigamList. Null when the item is used standalone."}, {"name": "select", "type": "(value: boolean, event?: Event) => void", "descriptionKey": "components.list_item.exposed.select", "descriptionFallback": "Programmatically select or deselect this item within the parent list."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listItemStyles."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_item.playground.title", "defaultValue": "List item", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.list_item.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-inbox", "value": "mdi-inbox"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-home", "value": "mdi-home"}], "labelKey": "components.list_item.playground.prepend_icon", "defaultValue": "mdi-inbox", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "lines", "options": [{"label": "(default)", "value": ""}, {"label": "one-line", "value": "one-line"}, {"label": "two-line", "value": "two-line"}, {"label": "three-line", "value": "three-line"}], "labelKey": "components.list_item.playground.lines", "defaultValue": "", "labelFallback": "Lines"}, {"kind": "switch", "prop": "active", "labelKey": "components.list_item.playground.active", "defaultValue": false, "labelFallback": "Active"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.list_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "simple", "props": {"title": "Inbox", "prependIcon": "mdi-inbox"}}, {"label": "subtitle", "props": {"title": "John Doe", "subtitle": "john.doe@example.com", "prependIcon": "mdi-account"}}, {"label": "active", "props": {"title": "Active", "active": true, "prependIcon": "mdi-star"}}, {"label": "disabled", "props": {"title": "Disabled", "disabled": true, "prependIcon": "mdi-lock"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8728359e-dfe4-40b6-b3bb-70036b3c4dec', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'list-subheader', 'ListSubheader', 'Data Display', NULL, 'mdi-format-list-group', 'components.catalog.list_subheader.description', 'Section heading rendered inside a List. Supports inset indent and sticky positioning.', NULL, NULL, 'origam-list-subheader', NULL, 'packages/ds/src/components/List/OrigamListSubheader.vue', 'origam', NULL, NULL, '/stories/?story=components-list-subheader--design', '/docs/components/List/OrigamListSubheader.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_subheader.a11y.semantic_note", "noteFallback": "For screen-reader accessibility, consider using tag=\"h2\" through \"h6\" so the subheader is part of the heading outline. The default <div> tag is appropriate when the list is not a standalone section."}, {"noteKey": "components.list_subheader.a11y.sticky_note", "noteFallback": "The sticky variant uses position: sticky; top: 0 — the parent list must have overflow: auto or overflow: scroll for this to work correctly."}, {"noteKey": "components.list_subheader.a11y.contrast_note", "noteFallback": "The default secondary text color may have reduced contrast. Ensure at least 4.5:1 contrast ratio when customising the color prop."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-list-subheader---color", "descriptionKey": "components.list_subheader.tokens.color", "descriptionFallback": "Default text color (secondary)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__subheader---font-size", "descriptionKey": "components.list_subheader.tokens.font_size", "descriptionFallback": "Font size (0.875rem)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-list-subheader---min-height", "descriptionKey": "components.list_subheader.tokens.min_height", "descriptionFallback": "Minimum row height."}, {"type": "dimension", "value": "32px", "tokenPath": "--origam-list-subheader---inset-indent-padding", "descriptionKey": "components.list_subheader.tokens.inset_indent_padding", "descriptionFallback": "Indent applied in --inset mode to align with prepend icon items."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-list-subheader---transition-duration", "descriptionKey": "components.list_subheader.tokens.transition_duration", "descriptionFallback": "Transition duration for min-height changes."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"44\" width=\"400\" height=\"22\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"232\" y=\"59\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__text (label)</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"44\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"48\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-subheader</text>\n  <text x=\"350\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">--inset adds 32px indent-padding · --sticky sets position: sticky top: 0</text>\n", "legend": [{"cls": ".origam-list-subheader", "num": 1, "descriptionKey": "components.list_subheader.anatomy.root", "descriptionFallback": "Root element. Flex container (align-items: center). Renders as <code>&lt;div&gt;</code> by default; use <code>tag=\"h2\"</code>–<code>\"h6\"</code> for semantic sectioning."}, {"cls": ".origam-list-subheader__text", "num": 2, "descriptionKey": "components.list_subheader.anatomy.text", "descriptionFallback": "Label text wrapper. <code>overflow: hidden; text-overflow: ellipsis; white-space: nowrap</code>. Rendered only when the title prop or default slot is provided."}], "svgDesc": "Schematic of the ListSubheader component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamListSubheader", "rootClass": "origam-list-subheader", "figcaption": "Anatomy of <code>&lt;origam-list-subheader&gt;</code> — 2 internal parts. The root ① is a flex container; the inner text element ② truncates with ellipsis.", "svgViewBox": "0 0 700 140"}, "cssVars": [{"name": "--origam-list-subheader---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.list_subheader.css_vars.color", "descriptionFallback": "Text color of the subheader label. Defaults to the semantic secondary text color."}, {"name": "--origam-list-subheader---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_subheader.css_vars.font_size", "descriptionFallback": "Font size of the subheader label."}, {"name": "--origam-list-subheader---font-weight", "defaultValue": "400", "descriptionKey": "components.list_subheader.css_vars.font_weight", "descriptionFallback": "Font weight of the subheader label."}, {"name": "--origam-list-subheader---min-height", "defaultValue": "40px", "descriptionKey": "components.list_subheader.css_vars.min_height", "descriptionFallback": "Minimum height of the subheader row. Transitions with density changes."}, {"name": "--origam-list-subheader---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.list_subheader.css_vars.padding_inline_end", "descriptionFallback": "Trailing padding to avoid text running to the edge."}, {"name": "--origam-list-subheader---line-height", "defaultValue": "1.375rem", "descriptionKey": "components.list_subheader.css_vars.line_height", "descriptionFallback": "Line height of the subheader text."}, {"name": "--origam-list-subheader---inset-indent-padding", "defaultValue": "32px", "descriptionKey": "components.list_subheader.css_vars.inset_indent_padding", "descriptionFallback": "Indent padding applied when --inset modifier is active. Aligns the label with prepend icons."}, {"name": "--origam-list-subheader---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.list_subheader.css_vars.transition_duration", "descriptionFallback": "Duration of the min-height transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_subheader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_subheader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listSubheaderStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.list_subheader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_subheader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_subheader.playground.title", "defaultValue": "Section header", "labelFallback": "Title"}, {"kind": "switch", "prop": "inset", "labelKey": "components.list_subheader.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "sticky", "labelKey": "components.list_subheader.playground.sticky", "defaultValue": false, "labelFallback": "Sticky"}]}, "previewVariants": [{"label": "default", "props": {"title": "Section header"}}, {"label": "inset", "props": {"inset": true, "title": "Inset header"}}, {"label": "sticky", "props": {"title": "Sticky header", "sticky": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('483de4aa-182e-40db-b269-13c9c725d979', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'loader', 'Loader', 'Feedback & Status', NULL, 'mdi-loading', 'components.catalog.loader.description', 'Toggle container that swaps between a loading spinner (OrigamProgress circular) and the default slot content. Carries aria-busy and aria-label when loading.', NULL, NULL, 'origam-loader', NULL, 'packages/ds/src/components/Loader/OrigamLoader.vue', 'origam', NULL, NULL, '/stories/?story=components-loader--design', '/docs/components/Loader/OrigamLoader.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.loader.a11y.aria_busy_note", "noteFallback": "While loading, the root carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code> (or the custom loadingText). Screen readers announce the loading state."}, {"noteKey": "components.loader.a11y.live_region_note", "noteFallback": "For critical async operations that change page content, consider wrapping OrigamLoader in a live region (<code>aria-live=\"polite\"</code>) so the transition from loading to loaded is announced."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "100%", "tokenPath": "--origam-loader---height", "descriptionKey": "components.loader.tokens.height", "descriptionFallback": "Default height of the loader root."}, {"type": "other", "value": "auto", "tokenPath": "--origam-loader__progress---margin", "descriptionKey": "components.loader.tokens.progress_margin", "descriptionFallback": "Margin around the progress element in the loader slot."}, {"type": "other", "value": "fixed", "tokenPath": "--origam-loader__fullscreen---position", "descriptionKey": "components.loader.tokens.fullscreen_position", "descriptionFallback": "Position in fullscreen mode."}, {"type": "other", "value": "100vh", "tokenPath": "--origam-loader__fullscreen---height", "descriptionKey": "components.loader.tokens.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"174\" cy=\"96\" r=\"28\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.20))\" stroke-width=\"4\"/>\n  <path d=\"M174 68 A28 28 0 0 1 202 96\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <text x=\"174\" y=\"148\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">loading=true → #loader slot</text>\n  <rect x=\"376\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <text x=\"526\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <text x=\"526\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">loading=false</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"384\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"174\" cy=\"96\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"174\" y=\"100\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<component\n  :is=\"tag\"\n  :aria-busy=\"isLoading || undefined\"\n  :aria-label=\"isLoading ? ''Loading'' : undefined\"\n  class=\"origam-loader\"\n>\n  <!-- shown when loading=true -->\n  <template v-if=\"isLoading\">\n    <slot name=\"loader\">\n      <origam-progress\n        :color=\"color\"\n        :size=\"23\"\n        type=\"circular\"\n        :width=\"2\"\n        class=\"origam-loader__progress\"\n        indeterminate\n      />\n    </slot>\n  </template>\n  <!-- shown when loading=false -->\n  <template v-else>\n    <slot name=\"default\" />\n  </template>\n</component>", "legend": [{"cls": ".origam-loader (loading)", "num": 1, "descriptionKey": "components.loader.anatomy.loading_state", "descriptionFallback": "Root element while <code>loading</code> is truthy. Carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code>. Renders the <code>#loader</code> slot."}, {"cls": ".origam-loader (loaded)", "num": 2, "descriptionKey": "components.loader.anatomy.loaded_state", "descriptionFallback": "Root element while <code>loading</code> is falsy. <code>aria-busy</code> and <code>aria-label</code> are absent. Renders the <code>#default</code> slot."}, {"cls": ".origam-loader__progress", "num": 3, "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress circular spinner injected in the default <code>#loader</code> slot. <code>margin: auto</code> centres it. Can be replaced by a custom slot."}], "classes": [{"cls": "origam-loader", "descriptionKey": "components.loader.anatomy.root", "descriptionFallback": "Root element. height: 100% by default."}, {"cls": "origam-loader--fullscreen", "descriptionKey": "components.loader.anatomy.fullscreen", "descriptionFallback": "Optional consumer-applied modifier. position: fixed; top: 0; left: 0; 100vw × 100vh."}, {"cls": "origam-loader__progress", "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress element rendered in the default loader slot. margin: auto centres it."}], "svgDesc": "Schematic of the Loader component in its two states: loading and loaded.", "svgTitle": "Anatomy of OrigamLoader", "rootClass": "origam-loader", "figcaption": "Anatomy of <code>&lt;origam-loader&gt;</code> — ① loading state (root with aria-busy, spinner rendered via #loader slot), ② loaded state (#default content visible), ③ OrigamProgress spinner (size=23, width=2, type=circular).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-loader---height", "defaultValue": "100%", "descriptionKey": "components.loader.css_vars.height", "descriptionFallback": "Height of the root element. Defaults to 100% to fill its parent."}, {"name": "--origam-loader__fullscreen---position", "defaultValue": "fixed", "descriptionKey": "components.loader.css_vars.fullscreen_position", "descriptionFallback": "Position value when the fullscreen modifier class is applied."}, {"name": "--origam-loader__fullscreen---height", "defaultValue": "100vh", "descriptionKey": "components.loader.css_vars.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}, {"name": "--origam-loader__fullscreen---width", "defaultValue": "100vw", "descriptionKey": "components.loader.css_vars.fullscreen_width", "descriptionFallback": "Width in fullscreen mode."}, {"name": "--origam-loader__progress---margin", "defaultValue": "auto", "descriptionKey": "components.loader.css_vars.progress_margin", "descriptionFallback": "Margin around the progress spinner — auto centres it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.loader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.loader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.loader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.loader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.loader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.loader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "loading", "labelKey": "components.loader.playground.loading", "defaultValue": true, "labelFallback": "Loading"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.loader.playground.color", "defaultValue": "primary", "labelFallback": "Spinner color"}, {"kind": "select", "prop": "tag", "options": [{"label": "span", "value": "span"}, {"label": "div", "value": "div"}, {"label": "section", "value": "section"}], "labelKey": "components.loader.playground.tag", "defaultValue": "span", "labelFallback": "Tag"}]}, "previewVariants": [{"label": "loading", "props": {"color": "primary", "loading": true}, "slotContent": "Content hidden while loading"}, {"label": "loaded", "props": {"loading": false}, "slotContent": "Content visible"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f1eb9f93-b3fb-4366-be71-0b0f1f332646', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'main', 'Main', 'Layout & Structure', NULL, 'mdi-application-outline', 'components.catalog.main.description', 'Content area of an OrigamLayout page. Reads the layout-item CSS offset vars (position-top/right/bottom/left) to auto-pad itself around Drawers, AppBars and BottomNavs. Supports a scrollable inner mode.', NULL, NULL, 'origam-main', NULL, 'packages/ds/src/components/Main/OrigamMain.vue', 'origam', NULL, NULL, '/stories/?story=components-main--design', '/docs/components/Main/OrigamMain.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.main.a11y.landmark_note", "noteFallback": "OrigamMain renders as <code>&lt;main&gt;</code> by default, providing a landmark region for assistive technologies. There should be only one <code>&lt;main&gt;</code> landmark per page."}, {"noteKey": "components.main.a11y.skip_link_note", "noteFallback": "Pair OrigamMain with a \"Skip to main content\" link (<code>&lt;a href=\"#main-id\"&gt;</code>) targeting its rendered id for keyboard-only users."}], "roles": ["main"], "keyboard": [{"key": "Tab", "actionKey": "components.main.a11y.key_tab", "actionFallback": "Navigates to the first interactive element inside the main content area."}]}, "tokens": {"excerpt": [{"type": "other", "value": "1 0 auto", "tokenPath": "--origam-main---flex", "descriptionKey": "components.main.tokens.flex", "descriptionFallback": "Default flex shorthand."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-main---transition-duration", "descriptionKey": "components.main.tokens.transition_duration", "descriptionFallback": "Duration of the push-content transition when layout items move."}, {"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-main---background-color", "descriptionKey": "components.main.tokens.background_color", "descriptionFallback": "Default background color for the main area."}, {"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-main---color", "descriptionKey": "components.main.tokens.color", "descriptionFallback": "Default foreground color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"652\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"40\" y=\"40\" width=\"620\" height=\"120\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-main__wrapper</text>\n  <text x=\"350\" y=\"114\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">→ origam-main__scroller (scrollable mode only)</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"42\" y1=\"32\" x2=\"80\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"18\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-main (tag: main)</text>\n", "code": "<component :is=\"tag\" class=\"origam-main\">\n  <!-- wrapper becomes __scroller when scrollable=true -->\n  <div\n    class=\"origam-main__wrapper\"\n    :class=\"{ ''origam-main__scroller'': scrollable }\"\n  >\n    <slot name=\"default\" />\n  </div>\n</component>", "legend": [{"cls": ".origam-main", "num": 1, "descriptionKey": "components.main.anatomy.root", "descriptionFallback": "Root <code>&lt;main&gt;</code>. Applies <code>padding-inline-start/end/block-start/end</code> from layout offset CSS vars (<code>--origam-layout---position-*</code>). flex: 1 0 auto by default."}, {"cls": ".origam-main__wrapper / .origam-main__scroller", "num": 2, "descriptionKey": "components.main.anatomy.wrapper", "descriptionFallback": "Inner wrapper. In <code>scrollable</code> mode the class becomes <code>__scroller</code> and adds <code>overflow-y: auto; flex: 1 1 auto</code>. Layout offsets are reset to 0 inside the scroller so nested layout items don''t double-count."}], "classes": [{"cls": "origam-main", "descriptionKey": "components.main.anatomy.root", "descriptionFallback": "Root element (defaults to <main>). Reads layout position offset CSS vars for automatic padding."}, {"cls": "origam-main--scrollable", "descriptionKey": "components.main.anatomy.scrollable", "descriptionFallback": "Applied when scrollable=true. Switches to position: absolute, display: flex."}, {"cls": "origam-main__wrapper", "descriptionKey": "components.main.anatomy.wrapper", "descriptionFallback": "Inner wrapper. Hosts the default slot."}, {"cls": "origam-main__scroller", "descriptionKey": "components.main.anatomy.scroller", "descriptionFallback": "Additional class on __wrapper in scrollable mode. overflow-y: auto; flex: 1 1 auto. Resets layout offset vars to 0."}], "svgDesc": "Schematic of the Main component with its wrapper child and scrollable modifier.", "svgTitle": "Anatomy of OrigamMain", "rootClass": "origam-main", "figcaption": "Anatomy of <code>&lt;origam-main&gt;</code> — ① root <code>&lt;main&gt;</code> that reads layout offset CSS vars, ② <code>__wrapper</code> (becomes <code>__scroller</code> in scrollable mode with overflow-y: auto).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-main---flex", "defaultValue": "1 0 auto", "descriptionKey": "components.main.css_vars.flex", "descriptionFallback": "Flex shorthand for the root. Allows the main area to grow and fill the layout."}, {"name": "--origam-main---max-width", "defaultValue": "100%", "descriptionKey": "components.main.css_vars.max_width", "descriptionFallback": "Maximum width of the main area."}, {"name": "--origam-main---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.main.css_vars.transition_duration", "descriptionFallback": "Transition duration when layout items push/pull the main area (e.g. drawer open/close)."}, {"name": "--origam-main---transition-property", "defaultValue": "all", "descriptionKey": "components.main.css_vars.transition_property", "descriptionFallback": "Properties transitioned when the layout offsets change."}, {"name": "--origam-main---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.main.css_vars.transition_timing_function", "descriptionFallback": "Easing of the layout push transition."}, {"name": "--origam-main__scroller---max-width", "defaultValue": "100%", "descriptionKey": "components.main.css_vars.scroller_max_width", "descriptionFallback": "Maximum width of the scroller inner div."}, {"name": "--origam-main__scroller---position", "defaultValue": "relative", "descriptionKey": "components.main.css_vars.scroller_position", "descriptionFallback": "Position of the scroller inner div."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.main.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.main.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.main.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.main.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.main.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.main.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "scrollable", "labelKey": "components.main.playground.scrollable", "defaultValue": false, "labelFallback": "Scrollable"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "surface", "value": "surface"}], "labelKey": "components.main.playground.bg_color", "defaultValue": "", "labelFallback": "Background"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}], "labelKey": "components.main.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3f41cc54-69ea-4854-82f5-95c25dd6e459', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'masonry', 'Masonry', 'Layout & Structure', NULL, 'mdi-view-dashboard-variant-outline', 'components.catalog.masonry.description', 'Pinterest-style masonry grid. Uses native CSS grid-template-rows: masonry when supported; falls back to a ResizeObserver bucket-fill algorithm. Container-query responsive via columnBreakpoints.', NULL, NULL, 'origam-masonry', NULL, 'packages/ds/src/components/Masonry/OrigamMasonry.vue', 'origam', NULL, NULL, '/stories/?story=components-masonry--design', '/docs/components/Masonry/OrigamMasonry.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.masonry.a11y.role_note", "noteFallback": "OrigamMasonry renders with <code>role=\"list\"</code>. In the JS path, each item wrapper carries <code>role=\"listitem\"</code>. In the CSS path, direct children should carry their own semantic markup."}, {"noteKey": "components.masonry.a11y.order_note", "noteFallback": "Items are laid out in DOM order. Visual column order may differ from reading order — ensure the DOM order matches a meaningful reading sequence for keyboard and screen reader users."}, {"noteKey": "components.masonry.a11y.reduced_motion_note", "noteFallback": "Transitions are disabled under <code>prefers-reduced-motion: reduce</code> via a dedicated @media block in the SCSS."}], "roles": ["list"], "keyboard": []}, "tokens": {"excerpt": [{"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-masonry---animation-duration", "descriptionKey": "components.masonry.tokens.animation_duration", "descriptionFallback": "Duration of the animated position-change transition."}, {"type": "cubicBezier", "value": "var(--origam-motion__easing---standard)", "tokenPath": "--origam-masonry---animation-easing", "descriptionKey": "components.masonry.tokens.animation_easing", "descriptionFallback": "Easing of the animated position-change transition."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"24\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">CSS path (grid-template-rows: masonry)</text>\n  <rect x=\"24\" y=\"28\" width=\"300\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"36\" y=\"40\" width=\"84\" height=\"80\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"130\" y=\"40\" width=\"84\" height=\"120\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"224\" y=\"40\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"36\" y=\"132\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"224\" y=\"112\" width=\"84\" height=\"100\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"376\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">JS fallback (ResizeObserver + bucket-fill)</text>\n  <rect x=\"376\" y=\"28\" width=\"300\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"388\" y=\"40\" width=\"84\" height=\"80\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"430\" y=\"84\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__item</text>\n  <rect x=\"482\" y=\"40\" width=\"84\" height=\"120\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"576\" y=\"40\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <rect x=\"388\" y=\"132\" width=\"84\" height=\"60\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <circle cx=\"32\" cy=\"36\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"36\" r=\"10\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\"/>\n  <text x=\"384\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"44\" cy=\"48\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"52\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"396\" cy=\"48\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"396\" y=\"52\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"350\" y=\"248\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">CSS path: display: grid + masonry / JS path: position: absolute per item</text>\n", "code": "<component :is=\"tag\" role=\"list\" class=\"origam-masonry origam-masonry--css\">\n  <!-- CSS path: children rendered directly as grid items -->\n  <slot />\n</component>\n\n<!-- OR (JS fallback path) -->\n<component :is=\"tag\" role=\"list\" class=\"origam-masonry origam-masonry--js\">\n  <div\n    v-for=\"(child, idx) in childrenVNodes\"\n    :key=\"idx\"\n    class=\"origam-masonry__item\"\n    role=\"listitem\"\n    :style=\"getItemStyle(idx)\"\n  >\n    <component :is=\"{ render: () => child }\" />\n  </div>\n</component>", "legend": [{"cls": ".origam-masonry.origam-masonry--css", "num": 1, "descriptionKey": "components.masonry.anatomy.css_path", "descriptionFallback": "CSS path: <code>display: grid; grid-template-rows: masonry; align-tracks: start</code>. <code>grid-template-columns</code> set via <code>--origam-masonry---template-columns</code> CSS var. No item wrappers — children are direct grid items."}, {"cls": ".origam-masonry.origam-masonry--js", "num": 2, "descriptionKey": "components.masonry.anatomy.js_path", "descriptionFallback": "JS fallback path: <code>position: relative; display: block</code>. Container height driven by <code>--origam-masonry---container-height</code>. Items absolutely positioned."}, {"cls": "(direct child — CSS path)", "num": 3, "descriptionKey": "components.masonry.anatomy.css_child", "descriptionFallback": "In the CSS path, children are placed directly as grid items. No wrapper is injected by the component."}, {"cls": ".origam-masonry__item", "num": 4, "descriptionKey": "components.masonry.anatomy.js_item", "descriptionFallback": "In the JS fallback path, each child VNode is wrapped in a <code>div.origam-masonry__item</code> with <code>position: absolute; left/top/width</code> computed by useMasonry."}], "classes": [{"cls": "origam-masonry", "descriptionKey": "components.masonry.anatomy.root", "descriptionFallback": "Root element. role=\"list\". Box-sizing: border-box; gap driven by --origam-masonry---resolved-gap."}, {"cls": "origam-masonry--css", "descriptionKey": "components.masonry.anatomy.css_path", "descriptionFallback": "CSS path modifier. display: grid; grid-template-rows: masonry; align-tracks: start."}, {"cls": "origam-masonry--js", "descriptionKey": "components.masonry.anatomy.js_path", "descriptionFallback": "JS fallback modifier. position: relative; display: block; height from --origam-masonry---container-height."}, {"cls": "origam-masonry--animated", "descriptionKey": "components.masonry.anatomy.animated", "descriptionFallback": "Applied when animated=true. Adds CSS transitions on item position changes."}, {"cls": "origam-masonry__item", "descriptionKey": "components.masonry.anatomy.js_item", "descriptionFallback": "Absolute-positioned wrapper for each child VNode in the JS fallback path. role=\"listitem\"."}], "svgDesc": "Schematic of the Masonry component in CSS and JS fallback paths.", "svgTitle": "Anatomy of OrigamMasonry", "rootClass": "origam-masonry", "figcaption": "Anatomy of <code>&lt;origam-masonry&gt;</code> — ① CSS path (grid-template-rows: masonry, native, no wrappers), ② JS fallback path (position: relative container), ③ direct child (CSS path — no wrapper), ④ <code>.origam-masonry__item</code> (JS path — absolute wrapper added by the component).", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-masonry---resolved-gap", "defaultValue": "var(--origam-grid---gap-md)", "descriptionKey": "components.masonry.css_vars.resolved_gap", "descriptionFallback": "Bridge variable: the serialised gap value (token or raw CSS). Consumed by the gap property AND read back by the JS algo via getComputedStyle."}, {"name": "--origam-masonry---template-columns", "defaultValue": "repeat(3, 1fr)", "descriptionKey": "components.masonry.css_vars.template_columns", "descriptionFallback": "CSS path only. Set to repeat(N, 1fr) where N = active column count."}, {"name": "--origam-masonry---container-height", "defaultValue": "auto", "descriptionKey": "components.masonry.css_vars.container_height", "descriptionFallback": "JS path only. Set to the computed total height of the bucket-fill layout."}, {"name": "--origam-masonry---animation-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.masonry.css_vars.animation_duration", "descriptionFallback": "Duration of position-change transitions (animated=true)."}, {"name": "--origam-masonry---animation-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.masonry.css_vars.animation_easing", "descriptionFallback": "Easing of position-change transitions."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.masonry.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "layout", "type": "Ref<{ items: Array<{ left: number; top: number; width: number }>; containerHeight: number }>", "descriptionKey": "components.masonry.exposed.layout", "descriptionFallback": "Reactive layout data computed by useMasonry. Available in both paths but only consumed by the template in the JS path."}, {"name": "relayout", "type": "() => void", "descriptionKey": "components.masonry.exposed.relayout", "descriptionFallback": "Forces an immediate re-computation of the bucket-fill layout. Useful after programmatically changing item content without changing the DOM structure."}, {"name": "useCssPath", "type": "ComputedRef<boolean>", "descriptionKey": "components.masonry.exposed.use_css_path", "descriptionFallback": "True when the CSS masonry path is active. False when the JS fallback runs."}, {"name": "gapPx", "type": "Ref<number>", "descriptionKey": "components.masonry.exposed.gap_px", "descriptionFallback": "Current gap value in pixels as resolved by getComputedStyle. Used by the JS bucket-fill algorithm."}], "playground": {"controls": [{"kind": "number", "prop": "columns", "labelKey": "components.masonry.playground.columns", "defaultValue": 3, "labelFallback": "Columns"}, {"kind": "select", "prop": "gap", "options": [{"label": "xs", "value": "xs"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.masonry.playground.gap", "defaultValue": "md", "labelFallback": "Gap"}, {"kind": "switch", "prop": "animated", "labelKey": "components.masonry.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "select", "prop": "align", "options": [{"label": "top", "value": "top"}, {"label": "center", "value": "center"}], "labelKey": "components.masonry.playground.align", "defaultValue": "top", "labelFallback": "Align"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d166590d-46b8-4f4a-a94d-d85c363abca5', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'media-controller', 'MediaController', 'Media', NULL, 'mdi-play-circle-outline', 'components.catalog.media_controller.description', 'Universal media controls shell shared by OrigamAudio and OrigamVideo. Purely presentational — receives state and methods from useMediaPlayer() and emits playback intents (play, pause, seek, volume, loop, shuffle, quality, download) without owning the HTMLMediaElement.', NULL, NULL, 'origam-media-controller', NULL, 'packages/ds/src/components/Media/OrigamMediaController.vue', 'origam', NULL, NULL, '/stories/?story=components-audio--design', '/docs/components/Media/OrigamMediaController.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_controller.a11y.nav_label", "noteFallback": "The transport row is a <nav> element with aria-label set via the i18n key \"origam.media.transport\". This correctly marks the zone as a landmark region."}, {"noteKey": "components.media_controller.a11y.aria_pressed", "noteFallback": "Toggle buttons (shuffle, loop, cast) use aria-pressed reflecting their active state. Screen readers announce \"pressed\" or \"not pressed\" on focus."}, {"noteKey": "components.media_controller.a11y.aria_labels", "noteFallback": "All icon-only buttons carry an aria-label (play, pause, previous, next, mute, unmute, shuffle, loop-all/one/off, cast, stop-cast, settings). Labels are i18n-translated strings computed in the script, not hardcoded strings in the template."}, {"noteKey": "components.media_controller.a11y.scrubber", "noteFallback": "The inner OrigamMediaScrubber uses role=\"slider\", aria-orientation=\"horizontal\", aria-valuemin/max/now/text and aria-label. See MediaScrubber accessibility notes for the full keyboard matrix."}], "roles": ["navigation"], "keyboard": [{"key": "Tab", "actionKey": "components.media_controller.a11y.key_tab", "actionFallback": "Moves focus sequentially through all transport buttons (previous, play/pause, next, mute, volume slider, shuffle, loop, cast, cog)."}, {"key": "Enter / Space", "actionKey": "components.media_controller.a11y.key_activate", "actionFallback": "Activates the focused transport button. Native <button> behaviour via OrigamBtn."}, {"key": "ArrowLeft / ArrowRight", "actionKey": "components.media_controller.a11y.key_scrubber_h", "actionFallback": "When the scrubber is focused: seeks backward/forward by step (default 0.1 s or 5 % of duration)."}, {"key": "Home / End", "actionKey": "components.media_controller.a11y.key_scrubber_bounds", "actionFallback": "When the scrubber is focused: seeks to the start or end of the media."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-media-controller---color", "descriptionKey": "components.media_controller.tokens.color", "descriptionFallback": "Default text/icon color for the controller bar."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-media-controller__scrubber---color", "descriptionKey": "components.media_controller.tokens.scrubber_color", "descriptionFallback": "Override color for the inner MediaScrubber timeline bar."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"10\" width=\"660\" height=\"220\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"28\" cy=\"18\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"22\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"40\" y=\"24\" width=\"620\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"47\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#header slot</text>\n  <circle cx=\"48\" cy=\"32\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"36\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"40\" y=\"74\" width=\"620\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"60\" y=\"86\" width=\"440\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.15))\"/>\n  <rect x=\"60\" y=\"86\" width=\"150\" height=\"12\" rx=\"6\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"48\" cy=\"82\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"86\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <rect x=\"40\" y=\"120\" width=\"620\" height=\"48\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <rect x=\"52\" y=\"132\" width=\"260\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"182\" y=\"147\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prev | play | next | volume | time</text>\n  <rect x=\"340\" y=\"132\" width=\"308\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <text x=\"494\" y=\"147\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">shuffle | loop | cast | cog</text>\n  <circle cx=\"48\" cy=\"128\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"132\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"332\" cy=\"128\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"332\" y=\"132\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <rect x=\"40\" y=\"178\" width=\"620\" height=\"38\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"199\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#footer slot</text>\n  <circle cx=\"48\" cy=\"186\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"190\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<div class=\"origam-media-controller origam-media-controller--visible\">\n  <slot name=\"header\" />\n\n  <div class=\"origam-media-controller__progress-row\">\n    <slot name=\"waveform\" :state=\"state\" :methods=\"methods\">\n      <origam-media-scrubber class=\"origam-media-controller__scrubber\" />\n    </slot>\n  </div>\n\n  <nav class=\"origam-media-controller__buttons-row\">\n    <div class=\"origam-media-controller__buttons-left\">\n      <slot name=\"prepend-transport\" />\n      <!-- prev / play-pause / next / volume / time -->\n      <slot name=\"extraControlsLeft\" />\n    </div>\n    <div class=\"origam-media-controller__buttons-right\">\n      <slot name=\"extraControlsRight\" />\n      <!-- shuffle / loop / cast / cog-menu -->\n      <slot name=\"append-transport\" />\n    </div>\n  </nav>\n\n  <slot name=\"footer\" />\n</div>", "legend": [{"cls": ".origam-media-controller", "num": 1, "descriptionKey": "components.media_controller.anatomy.root", "descriptionFallback": "Root div. display: flex; flex-direction: column; gap: 0. When inset=true, applies .origam-media-controller--inset (position: absolute, dark gradient overlay, opacity: 0 by default). .origam-media-controller--visible toggles opacity: 1 and pointer-events: auto."}, {"cls": "#header slot", "num": 2, "descriptionKey": "components.media_controller.anatomy.header", "descriptionFallback": "Optional header region above the scrubber. OrigamAudio injects cover art + metadata strip here."}, {"cls": ".origam-media-controller__progress-row", "num": 3, "descriptionKey": "components.media_controller.anatomy.progress_row", "descriptionFallback": "Scrubber row — padding: 0 12px. Contains OrigamMediaScrubber by default; replaceable via the #waveform slot."}, {"cls": ".origam-media-controller__buttons-left", "num": 4, "descriptionKey": "components.media_controller.anatomy.buttons_left", "descriptionFallback": "Left transport group: previous, play/pause, next, volume control, time display. Flex row; gap: 2px. Buttons use variant=\"text\" density=\"compact\"."}, {"cls": ".origam-media-controller__buttons-right", "num": 5, "descriptionKey": "components.media_controller.anatomy.buttons_right", "descriptionFallback": "Right transport group: shuffle, loop, cast, config cog menu. Same sizing as the left group."}, {"cls": "#footer slot", "num": 6, "descriptionKey": "components.media_controller.anatomy.footer", "descriptionFallback": "Optional footer region below the transport row. OrigamAudio injects the playlist here."}], "classes": [{"cls": "origam-media-controller", "descriptionKey": "components.media_controller.anatomy.root", "descriptionFallback": "Root flex column."}, {"cls": "origam-media-controller--inset", "descriptionKey": "components.media_controller.anatomy.inset", "descriptionFallback": "Applied when inset=true. position: absolute; bottom/left/right: 0; dark gradient; opacity: 0; pointer-events: none."}, {"cls": "origam-media-controller--visible", "descriptionKey": "components.media_controller.anatomy.visible", "descriptionFallback": "Combined with --inset to show the overlay: opacity: 1; pointer-events: auto."}, {"cls": "origam-media-controller__progress-row", "descriptionKey": "components.media_controller.anatomy.progress_row", "descriptionFallback": "Scrubber container with inline padding."}, {"cls": "origam-media-controller__buttons-row", "descriptionKey": "components.media_controller.anatomy.buttons_row", "descriptionFallback": "Transport row. display: flex; justify-content: space-between; min-height: 36px."}, {"cls": "origam-media-controller__buttons-left", "descriptionKey": "components.media_controller.anatomy.buttons_left", "descriptionFallback": "Left button group: flex row; gap: 2px."}, {"cls": "origam-media-controller__buttons-right", "descriptionKey": "components.media_controller.anatomy.buttons_right", "descriptionFallback": "Right button group: flex row; gap: 2px."}, {"cls": "origam-media-controller__scrubber", "descriptionKey": "components.media_controller.anatomy.scrubber", "descriptionFallback": "Class applied to the inner OrigamMediaScrubber. width: 100%; overrides scrubber color tokens."}, {"cls": "origam-media-controller__time", "descriptionKey": "components.media_controller.anatomy.time", "descriptionFallback": "Time display: currentTime / duration. Inline-flex; monospace; font-variant-numeric: tabular-nums."}, {"cls": "origam-media-controller__play-btn", "descriptionKey": "components.media_controller.anatomy.play_btn", "descriptionFallback": "Class applied to the play/pause OrigamBtn for targeting in consumer styles."}], "svgDesc": "Schematic of the media controller with 6 numbered parts: root, header slot, scrubber row, buttons row (left group and right group), footer slot.", "svgTitle": "Anatomy of OrigamMediaController", "rootClass": "origam-media-controller", "figcaption": "Anatomy of <code>&lt;origam-media-controller&gt;</code> — 6 internal parts. Root flex column ①, header slot ②, scrubber row ③ (OrigamMediaScrubber), transport row with left button group ④ (prev/play/next/volume/time) and right button group ⑤ (shuffle/loop/cast/cog), footer slot ⑥.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-media-controller---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.media_controller.css_vars.color", "descriptionFallback": "Text and icon color for the entire controller bar. Inherits from the parent surface by default."}, {"name": "--origam-media-controller---accent-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media_controller.css_vars.accent_color", "descriptionFallback": "Accent color applied to active transport buttons (loop-active, shuffle-active, cast-active). Background is a 14% tint of this color."}, {"name": "--origam-media-controller__scrubber---color", "defaultValue": "currentColor", "descriptionKey": "components.media_controller.css_vars.scrubber_color", "descriptionFallback": "Override for the inner MediaScrubber progress/thumb color. Falls through to the scrubber default when unset."}, {"name": "--origam-media-controller__time---color", "defaultValue": "inherit", "descriptionKey": "components.media_controller.css_vars.time_color", "descriptionFallback": "Color for the current time / duration display."}], "exposed": [{"name": "configMenuOpen", "type": "Ref<boolean>", "descriptionKey": "components.media_controller.exposed.config_menu_open", "descriptionFallback": "Reactive flag controlling the cog config menu open/close state. Can be read or set externally to programmatically open or close the menu."}, {"name": "resolvedLoopMode", "type": "ComputedRef<TAudioLoopMode>", "descriptionKey": "components.media_controller.exposed.resolved_loop_mode", "descriptionFallback": "The currently active loop mode computed from the internal state. Reflects the prop value unless the user cycled it via the loop button."}, {"name": "internalShuffle", "type": "Ref<boolean>", "descriptionKey": "components.media_controller.exposed.internal_shuffle", "descriptionFallback": "Internal shuffle toggle state. Mirrors the shuffle prop and updates when the button is clicked."}], "playground": {"controls": [{"kind": "switch", "prop": "inset", "labelKey": "components.media_controller.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "visible", "labelKey": "components.media_controller.playground.visible", "defaultValue": true, "labelFallback": "Visible"}, {"kind": "switch", "prop": "allowRemotePlayback", "labelKey": "components.media_controller.playground.allow_remote_playback", "defaultValue": false, "labelFallback": "Allow Remote Playback"}, {"kind": "switch", "prop": "downloadable", "labelKey": "components.media_controller.playground.downloadable", "defaultValue": false, "labelFallback": "Downloadable"}, {"kind": "switch", "prop": "showPrevious", "labelKey": "components.media_controller.playground.show_previous", "defaultValue": false, "labelFallback": "Show Previous"}, {"kind": "switch", "prop": "showNext", "labelKey": "components.media_controller.playground.show_next", "defaultValue": false, "labelFallback": "Show Next"}, {"kind": "switch", "prop": "showLoop", "labelKey": "components.media_controller.playground.show_loop", "defaultValue": false, "labelFallback": "Show Loop"}, {"kind": "switch", "prop": "showShuffle", "labelKey": "components.media_controller.playground.show_shuffle", "defaultValue": false, "labelFallback": "Show Shuffle"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('995afe89-2f20-4353-b102-94a7196af1af', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'media-scrubber', 'MediaScrubber', 'Media', NULL, 'mdi-tune', 'components.catalog.media_scrubber.description', 'Headless media-agnostic track-and-thumb slider widget. Owns the full pointer-events drag pipeline, keyboard matrix (ARIA slider pattern), optional buffer bar, hover tooltip and both horizontal and vertical orientations. Used internally by OrigamMediaController for the timeline and the volume slider.', NULL, NULL, 'origam-media-scrubber', NULL, 'packages/ds/src/components/Media/OrigamMediaScrubber.vue', 'origam', NULL, NULL, '/stories/?story=components-audio--design', '/docs/components/Media/OrigamMediaController.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_scrubber.a11y.role_slider", "noteFallback": "role=\"slider\" is set only when not disabled. When disabled, the role attribute is omitted (undefined) and tabindex becomes -1 so AT users are not invited to interact with a frozen widget."}, {"noteKey": "components.media_scrubber.a11y.aria_label_required", "noteFallback": "ariaLabel is a required prop. Always pass a translated string (e.g. \"Seek\" for the timeline, \"Volume\" for the volume slider). The label must describe the purpose of the slider, not its current value."}, {"noteKey": "components.media_scrubber.a11y.aria_value_text", "noteFallback": "Use ariaValueText for a human-readable representation of the value — e.g. \"1:23\" for a timestamp so screen readers announce \"1 minute 23 seconds\" rather than the raw float \"83.4\"."}, {"noteKey": "components.media_scrubber.a11y.reduced_motion", "noteFallback": "Under prefers-reduced-motion: reduce, both track and thumb CSS transitions are disabled (transition: none)."}, {"noteKey": "components.media_scrubber.a11y.pointer_capture", "noteFallback": "The component uses setPointerCapture() on pointerdown so drag events continue even when the pointer leaves the element boundary. This is the standard drag pattern for range inputs on touch devices."}], "roles": ["slider"], "keyboard": [{"key": "ArrowRight / ArrowUp", "actionKey": "components.media_scrubber.a11y.key_increment", "actionFallback": "Increases the value by step (or 5% of range when step=0). ArrowRight for horizontal; ArrowUp for vertical."}, {"key": "ArrowLeft / ArrowDown", "actionKey": "components.media_scrubber.a11y.key_decrement", "actionFallback": "Decreases the value by step (or 5% of range when step=0). ArrowLeft for horizontal; ArrowDown for vertical."}, {"key": "PageUp", "actionKey": "components.media_scrubber.a11y.key_page_up", "actionFallback": "Increases the value by 10% of the range (same regardless of step)."}, {"key": "PageDown", "actionKey": "components.media_scrubber.a11y.key_page_down", "actionFallback": "Decreases the value by 10% of the range."}, {"key": "Home", "actionKey": "components.media_scrubber.a11y.key_home", "actionFallback": "Sets the value to min."}, {"key": "End", "actionKey": "components.media_scrubber.a11y.key_end", "actionFallback": "Sets the value to max."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-media-scrubber---color", "descriptionKey": "components.media_scrubber.tokens.color", "descriptionFallback": "Primary color (progress bar + thumb fill)."}, {"type": "dimension", "value": "12px", "tokenPath": "--origam-media-scrubber---thumb-diameter", "descriptionKey": "components.media_scrubber.tokens.thumb_diameter", "descriptionFallback": "Circular thumb diameter."}, {"type": "color", "value": "var(--origam-color__neutral---900)", "tokenPath": "--origam-media-scrubber__tooltip---background-color", "descriptionKey": "components.media_scrubber.tokens.tooltip_background_color", "descriptionFallback": "Hover tooltip background (near-black for contrast)."}, {"type": "color", "value": "var(--origam-color__neutral---0)", "tokenPath": "--origam-media-scrubber__tooltip---color", "descriptionKey": "components.media_scrubber.tokens.tooltip_color", "descriptionFallback": "Hover tooltip text color (white)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"55\" width=\"640\" height=\"14\" rx=\"7\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.15))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <rect x=\"30\" y=\"55\" width=\"220\" height=\"14\" rx=\"7\" fill=\"rgba(124,58,237,0.25)\"/>\n  <rect x=\"30\" y=\"55\" width=\"148\" height=\"14\" rx=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"178\" cy=\"62\" r=\"7\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---raised, #fff)\" stroke-width=\"2\"/>\n  <rect x=\"130\" y=\"30\" width=\"60\" height=\"20\" rx=\"3\" fill=\"rgba(0,0,0,0.8)\"/>\n  <text x=\"160\" y=\"43\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"ui-monospace,monospace\">0:48</text>\n  <line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"55\" stroke=\"rgba(0,0,0,0.5)\" stroke-width=\"1\"/>\n  <circle cx=\"38\" cy=\"55\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"59\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"240\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"240\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"90\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"90\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"178\" cy=\"55\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"178\" y=\"59\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"160\" cy=\"25\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"160\" y=\"29\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① root — ② track — ③ buffer bar — ④ progress bar — ⑤ thumb — ⑥ hover tooltip</text>\n", "code": "<div\n  class=\"origam-media-scrubber origam-media-scrubber--horizontal\"\n  role=\"slider\"\n  tabindex=\"0\"\n  aria-orientation=\"horizontal\"\n  aria-valuemin=\"0\"\n  aria-valuemax=\"120\"\n  aria-valuenow=\"48\"\n  aria-valuetext=\"0:48\"\n  aria-label=\"Seek\"\n>\n  <div class=\"origam-media-scrubber__track\" aria-hidden=\"true\">\n    <div class=\"origam-media-scrubber__buffer\" aria-hidden=\"true\" />\n    <div class=\"origam-media-scrubber__progress\" aria-hidden=\"true\" />\n    <div class=\"origam-media-scrubber__thumb\" aria-hidden=\"true\" />\n  </div>\n\n  <div class=\"origam-media-scrubber__hover-tooltip\" aria-hidden=\"true\">\n    <slot name=\"tooltip\" :value=\"48\">0:48</slot>\n  </div>\n</div>", "legend": [{"cls": ".origam-media-scrubber", "num": 1, "descriptionKey": "components.media_scrubber.anatomy.root", "descriptionFallback": "Root div. role=\"slider\" (or undefined when disabled), tabindex=\"0\" (or -1 when disabled), aria-orientation, aria-valuemin/max/now/text, aria-label. Handles all pointer and keyboard events. position: relative; cursor: pointer; touch-action: none; user-select: none."}, {"cls": ".origam-media-scrubber__track", "num": 2, "descriptionKey": "components.media_scrubber.anatomy.track", "descriptionFallback": "Track bar. Background color from token --origam-media-scrubber---track-bg. Height grows from --track-thickness to --track-thickness-active on hover / focus / scrubbing. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__buffer", "num": 3, "descriptionKey": "components.media_scrubber.anatomy.buffer", "descriptionFallback": "Buffered portion bar. Renders from min to buffered%. Background --origam-media-scrubber---buffer-bg. Visible only when buffered prop is a finite number. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__progress", "num": 4, "descriptionKey": "components.media_scrubber.anatomy.progress", "descriptionFallback": "Playback progress bar. Width/height = valuePct%. Background --origam-media-scrubber---primary. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__thumb", "num": 5, "descriptionKey": "components.media_scrubber.anatomy.thumb", "descriptionFallback": "Circular drag handle. Position driven by valuePct% (left in horizontal, bottom in vertical). Hidden at rest when showThumbOnHoverOnly=true; revealed on :hover, :focus-visible and .origam-media-scrubber--scrubbing. aria-hidden=\"true\"."}, {"cls": ".origam-media-scrubber__hover-tooltip", "num": 6, "descriptionKey": "components.media_scrubber.anatomy.tooltip", "descriptionFallback": "Hover tooltip. position: absolute; bottom: calc(100% + 8px); left = hoverPct%. Contains the #tooltip slot or the formatted value string. Horizontal orientation only. aria-hidden=\"true\"."}], "classes": [{"cls": "origam-media-scrubber", "descriptionKey": "components.media_scrubber.anatomy.root", "descriptionFallback": "Root slider element with ARIA role and pointer/keyboard event handlers."}, {"cls": "origam-media-scrubber--horizontal", "descriptionKey": "components.media_scrubber.anatomy.horizontal", "descriptionFallback": "Applied when orientation=\"horizontal\". width: 100%; height: 14px."}, {"cls": "origam-media-scrubber--vertical", "descriptionKey": "components.media_scrubber.anatomy.vertical", "descriptionFallback": "Applied when orientation=\"vertical\". height: 100%; width: 14px; flex-direction: column."}, {"cls": "origam-media-scrubber--disabled", "descriptionKey": "components.media_scrubber.anatomy.disabled", "descriptionFallback": "Applied when disabled=true. cursor: not-allowed; opacity: 0.5."}, {"cls": "origam-media-scrubber--scrubbing", "descriptionKey": "components.media_scrubber.anatomy.scrubbing", "descriptionFallback": "Applied while a pointer drag is in progress. Prevents pointerleave from clearing the tooltip."}, {"cls": "origam-media-scrubber--thumb-on-hover", "descriptionKey": "components.media_scrubber.anatomy.thumb_on_hover", "descriptionFallback": "Applied when showThumbOnHoverOnly=true. Scales the thumb to 0 at rest."}, {"cls": "origam-media-scrubber__track", "descriptionKey": "components.media_scrubber.anatomy.track", "descriptionFallback": "Track bar — background + growing height on hover."}, {"cls": "origam-media-scrubber__buffer", "descriptionKey": "components.media_scrubber.anatomy.buffer", "descriptionFallback": "Buffered portion indicator bar."}, {"cls": "origam-media-scrubber__progress", "descriptionKey": "components.media_scrubber.anatomy.progress", "descriptionFallback": "Playback progress fill."}, {"cls": "origam-media-scrubber__thumb", "descriptionKey": "components.media_scrubber.anatomy.thumb", "descriptionFallback": "Circular drag handle (position: absolute)."}, {"cls": "origam-media-scrubber__hover-tooltip", "descriptionKey": "components.media_scrubber.anatomy.tooltip", "descriptionFallback": "Floating hover value tooltip (horizontal only)."}], "svgDesc": "Schematic of the horizontal scrubber with 5 numbered parts: root, track, buffer bar, progress bar, thumb and hover tooltip.", "svgTitle": "Anatomy of OrigamMediaScrubber", "rootClass": "origam-media-scrubber", "figcaption": "Anatomy of <code>&lt;origam-media-scrubber&gt;</code> — 6 internal parts. Root ①, track ② (full-width bg), optional buffer bar ③, progress bar ④ (fills to modelValue %), draggable thumb ⑤, and the hover tooltip ⑥ (horizontal only, conditional on showHoverTooltip).", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-media-scrubber---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.media_scrubber.css_vars.color", "descriptionFallback": "Primary accent color. Drives --origam-media-scrubber---primary (progress bar + thumb fill)."}, {"name": "--origam-media-scrubber---track-background-color", "defaultValue": "rgba(255,255,255,0.3)", "descriptionKey": "components.media_scrubber.css_vars.track_background_color", "descriptionFallback": "Idle track fill. Semi-transparent by design (overlaid on the media surface)."}, {"name": "--origam-media-scrubber---buffer-background-color", "defaultValue": "rgba(255,255,255,0.4)", "descriptionKey": "components.media_scrubber.css_vars.buffer_background_color", "descriptionFallback": "Buffer bar fill. Slightly more opaque than the track."}, {"name": "--origam-media-scrubber---thumb-diameter", "defaultValue": "13px", "descriptionKey": "components.media_scrubber.css_vars.thumb_diameter", "descriptionFallback": "Diameter of the circular thumb handle."}, {"name": "--origam-media-scrubber---track-size", "defaultValue": "3px", "descriptionKey": "components.media_scrubber.css_vars.track_size", "descriptionFallback": "Track thickness at rest."}, {"name": "--origam-media-scrubber---track-size-active", "defaultValue": "5px", "descriptionKey": "components.media_scrubber.css_vars.track_size_active", "descriptionFallback": "Track thickness on hover / focus / scrubbing. Animates over 140ms."}, {"name": "--origam-media-scrubber__tooltip---background-color", "defaultValue": "rgba(0,0,0,0.85)", "descriptionKey": "components.media_scrubber.css_vars.tooltip_background_color", "descriptionFallback": "Hover tooltip background. Near-black for contrast."}, {"name": "--origam-media-scrubber__tooltip---color", "defaultValue": "#ffffff", "descriptionKey": "components.media_scrubber.css_vars.tooltip_color", "descriptionFallback": "Hover tooltip text color."}], "exposed": [{"name": "rootEl", "type": "Ref<HTMLElement | null>", "descriptionKey": "components.media_scrubber.exposed.root_el", "descriptionFallback": "Template ref to the root DOM element. Useful for measuring the track dimensions or programming pointer capture externally."}, {"name": "isScrubbing", "type": "Ref<boolean>", "descriptionKey": "components.media_scrubber.exposed.is_scrubbing", "descriptionFallback": "True while a pointer drag is captured. The parent can use this to suppress autohide logic on the controller overlay during a drag."}, {"name": "hoverValue", "type": "Ref<number | null>", "descriptionKey": "components.media_scrubber.exposed.hover_value", "descriptionFallback": "The hovered track value while the cursor is over the scrubber. null when the cursor has left. Mirrors the hover emit."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.media_scrubber.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.media_scrubber.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.media_scrubber.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "showThumbOnHoverOnly", "labelKey": "components.media_scrubber.playground.show_thumb_on_hover_only", "defaultValue": false, "labelFallback": "Show Thumb On Hover Only"}, {"kind": "switch", "prop": "showHoverTooltip", "labelKey": "components.media_scrubber.playground.show_hover_tooltip", "defaultValue": false, "labelFallback": "Show Hover Tooltip"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('277710ff-435e-4da5-95f7-82ee3bc6ad12', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'media-volume-control', 'MediaVolumeControl', 'Media', NULL, 'mdi-volume-high', 'components.catalog.media_volume_control.description', 'Mute / unmute toggle button with a vertical volume scrubber shown in a tooltip on hover.', NULL, NULL, 'origam-media-volume-control', NULL, 'packages/ds/src/components/Media/OrigamMediaVolumeControl.vue', 'origam', NULL, NULL, '/stories/?story=components-media-volume-control--design', '/docs/components/Media/OrigamMediaVolumeControl.html', 'media', '{"a11y": {"notes": [{"noteKey": "components.media_volume_control.a11y.aria_label_note", "noteFallback": "The toggle button''s aria-label switches between muteLabel and unmuteLabel to reflect the current state."}, {"noteKey": "components.media_volume_control.a11y.scrubber_note", "noteFallback": "The scrubber exposes aria-label (volumeLabel) and aria-valuetext (formatted percentage) for screen readers."}, {"noteKey": "components.media_volume_control.a11y.reduced_motion_note", "noteFallback": "The button scale transform on :active is the only animation — it respects prefers-reduced-motion by being a short (120ms) transition."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.media_volume_control.a11y.key_toggle", "actionFallback": "Toggles mute/unmute on the icon button."}, {"key": "Arrow Up / Arrow Down", "actionKey": "components.media_volume_control.a11y.key_scrubber", "actionFallback": "Adjusts volume via the vertical scrubber (step 0.05)."}, {"key": "Tab", "actionKey": "components.media_volume_control.a11y.key_tab", "actionFallback": "Moves focus between the toggle button and the scrubber inside the tooltip."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"30\" width=\"200\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"128\" cy=\"100\" r=\"30\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"128\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"280\" y=\"20\" width=\"80\" height=\"160\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1.5\"/>\n  <rect x=\"306\" y=\"40\" width=\"28\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, #e9d5ff)\"/>\n  <rect x=\"306\" y=\"100\" width=\"28\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"320\" cy=\"100\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"36\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"152\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"152\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"288\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"288\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"320\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"320\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"38\" x2=\"80\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"18\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tooltip</text>\n", "code": "<!-- tooltip wraps both the activator button and the volume panel -->\n<origam-tooltip location=\"top\" content-class=\"origam-media-volume-control__tooltip\">\n  <template #activator=\"{ props: activatorProps }\">\n    <!-- mute / unmute toggle -->\n    <button\n      type=\"button\"\n      class=\"origam-media-volume-control__btn\"\n      :aria-label=\"muted ? unmuteLabel : muteLabel\"\n      @click=\"onToggleMute\"\n    >\n      <origam-icon :icon=\"volumeIcon\" aria-hidden=\"true\" />\n    </button>\n  </template>\n\n  <!-- tooltip body: vertical scrubber -->\n  <div class=\"origam-media-volume-control__wrapper\">\n    <origam-media-scrubber\n      class=\"origam-media-volume-control__scrubber\"\n      orientation=\"vertical\"\n      :model-value=\"resolvedVolume\"\n      :max=\"1\"\n      :step=\"0.05\"\n      :aria-label=\"volumeLabel\"\n      @update:model-value=\"onVolumeFromScrubber\"\n    />\n  </div>\n</origam-tooltip>", "legend": [{"cls": ".origam-media-volume-control__btn", "num": 1, "descriptionKey": "components.media_volume_control.anatomy.btn", "descriptionFallback": "Icon-only <code>&lt;button&gt;</code> that triggers mute/unmute. Styled with <code>all: unset</code> and rounded with <code>border-radius: 50%</code>."}, {"cls": ".origam-icon (within __btn)", "num": 2, "descriptionKey": "components.media_volume_control.anatomy.icon", "descriptionFallback": "Volume icon that switches between VOLUME_OFF / VOLUME_LOW / VOLUME_MEDIUM / VOLUME_HIGH based on <code>volume</code> and <code>muted</code>."}, {"cls": ".origam-media-volume-control__wrapper", "num": 3, "descriptionKey": "components.media_volume_control.anatomy.wrapper", "descriptionFallback": "Container inside the tooltip — 14 × 80 px — that hosts the vertical scrubber."}, {"cls": ".origam-media-volume-control__scrubber", "num": 4, "descriptionKey": "components.media_volume_control.anatomy.scrubber", "descriptionFallback": "<code>&lt;origam-media-scrubber&gt;</code> in vertical orientation. <code>max=1</code>, <code>step=0.05</code>. Collapses to 0 when muted."}], "classes": [{"cls": "origam-media-volume-control__btn", "descriptionKey": "components.media_volume_control.anatomy.btn", "descriptionFallback": "Icon-only toggle button. Uses all:unset and 50% border-radius."}, {"cls": "origam-media-volume-control__tooltip", "descriptionKey": "components.media_volume_control.anatomy.tooltip", "descriptionFallback": "CSS class injected via content-class on the tooltip to style its inner panel."}, {"cls": "origam-media-volume-control__wrapper", "descriptionKey": "components.media_volume_control.anatomy.wrapper", "descriptionFallback": "Fixed-size (14 × 80 px) flex container for the vertical scrubber."}, {"cls": "origam-media-volume-control__scrubber", "descriptionKey": "components.media_volume_control.anatomy.scrubber", "descriptionFallback": "OrigamMediaScrubber instance in vertical orientation."}], "svgDesc": "Schematic of the MediaVolumeControl component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamMediaVolumeControl", "rootClass": "origam-media-volume-control__btn", "figcaption": "Anatomy of <code>&lt;origam-media-volume-control&gt;</code> — 4 internal parts: the tooltip wrapper ①, the icon-only toggle button ②, the tooltip volume wrapper ③, and the vertical scrubber ④.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-media-volume-control---btn-size", "defaultValue": "36px", "descriptionKey": "components.media_volume_control.css_vars.btn_size", "descriptionFallback": "Width and height of the toggle button."}, {"name": "--origam-media-volume-control---btn-border-radius", "defaultValue": "50%", "descriptionKey": "components.media_volume_control.css_vars.btn_border_radius", "descriptionFallback": "Border radius of the toggle button (full circle by default)."}, {"name": "--origam-media-volume-control---color", "defaultValue": "inherit", "descriptionKey": "components.media_volume_control.css_vars.color", "descriptionFallback": "Foreground color of the icon button."}, {"name": "--origam-media-volume-control---hover-background-color", "defaultValue": "color-mix(in srgb, currentColor 12%, transparent)", "descriptionKey": "components.media_volume_control.css_vars.hover_background_color", "descriptionFallback": "Background color on hover and focus-visible."}, {"name": "--origam-media-volume-control---icon-size", "defaultValue": "20px", "descriptionKey": "components.media_volume_control.css_vars.icon_size", "descriptionFallback": "Font-size of the volume icon inside the button."}, {"name": "--origam-media-volume-control---tooltip-background-color", "defaultValue": "rgba(28, 28, 28, 0.92)", "descriptionKey": "components.media_volume_control.css_vars.tooltip_background_color", "descriptionFallback": "Background color of the tooltip content area containing the scrubber."}], "playground": {"controls": [{"kind": "number", "prop": "volume", "labelKey": "components.media_volume_control.playground.volume", "defaultValue": 0.8, "labelFallback": "Volume (0-1)"}, {"kind": "switch", "prop": "muted", "labelKey": "components.media_volume_control.playground.muted", "defaultValue": false, "labelFallback": "Muted"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('abe6e2dc-5211-4f53-908e-ce3a6bec3036', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'menu', 'Menu', 'Overlay & Surface', NULL, 'mdi-menu', 'components.catalog.menu.description', 'Floating contextual menu anchored to an activator element. Supports nested sub-menus, keyboard navigation, items array shorthand, and full slot customisation.', NULL, NULL, 'origam-menu', NULL, 'packages/ds/src/components/Menu/OrigamMenu.vue', 'origam', NULL, NULL, '/stories/?story=components-menu--design', '/docs/components/Menu/OrigamMenu.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.menu.a11y.activator_note", "noteFallback": "The activator element receives aria-haspopup=\"menu\" and aria-expanded=\"true/false\" bound by the overlay. The menu id is referenced via aria-owns."}, {"noteKey": "components.menu.a11y.role_note", "noteFallback": "The menu panel has role=\"menu\". Each item should carry role=\"menuitem\" (provided automatically by OrigamListItem when inside a menu)."}, {"noteKey": "components.menu.a11y.focus_note", "noteFallback": "Focus is trapped inside the menu when open. On close, focus returns to the activator element."}], "roles": ["menu"], "keyboard": [{"key": "Escape", "actionKey": "components.menu.a11y.key_close", "actionFallback": "Closes the menu and returns focus to the activator."}, {"key": "ArrowDown", "actionKey": "components.menu.a11y.key_next_item", "actionFallback": "Moves focus to the next menu item."}, {"key": "ArrowUp", "actionKey": "components.menu.a11y.key_prev_item", "actionFallback": "Moves focus to the previous menu item."}, {"key": "Enter / Space", "actionKey": "components.menu.a11y.key_select", "actionFallback": "Activates the focused menu item."}, {"key": "Tab", "actionKey": "components.menu.a11y.key_tab", "actionFallback": "Closes the menu and moves focus to the next focusable element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-menu---background", "descriptionKey": "components.menu.tokens.background", "descriptionFallback": "Menu panel background — inherits the raised surface token."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-menu---border-radius", "descriptionKey": "components.menu.tokens.border_radius", "descriptionFallback": "Border radius of the menu panel."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-menu---box-shadow", "descriptionKey": "components.menu.tokens.box_shadow", "descriptionFallback": "Drop shadow applied to the floating panel."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-menu---transition-duration", "descriptionKey": "components.menu.tokens.transition_duration", "descriptionFallback": "Enter/leave animation duration."}, {"type": "number", "value": "var(--origam-zIndex---dropdown)", "tokenPath": "--origam-menu---z-index", "descriptionKey": "components.menu.tokens.z_index", "descriptionFallback": "Stacking order of the floating menu panel."}, {"type": "dimension", "value": "320px", "tokenPath": "--origam-menu__content---max-width", "descriptionKey": "components.menu.tokens.content_max_width", "descriptionFallback": "Maximum width of the scrollable content inner area."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"50\" y=\"20\" width=\"120\" height=\"36\" rx=\"4\" fill=\"var(--origam-col