to none to make the scrim click-through."}, {"name": "--origam-overlay-scrim---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.overlay_scrim.css_vars.transition_duration", "descriptionFallback": "Duration of the opacity transition on enter/leave."}, {"name": "--origam-overlay-scrim---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.overlay_scrim.css_vars.transition_timing_function", "descriptionFallback": "Easing function for the opacity transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.overlay_scrim.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.overlay_scrim.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.overlay_scrim.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.overlay_scrim.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.overlay_scrim.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.overlay_scrim.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "active", "labelKey": "components.overlay_scrim.playground.active", "defaultValue": true, "labelFallback": "Active"}, {"kind": "select", "prop": "scrim", "options": [{"label": "(default)", "value": ""}, {"label": "rgba(0,0,0,0.5)", "value": "rgba(0,0,0,0