INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c5a01240-dd1e-4398-919a-1a847e2a403f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'responsive', 'Responsive', 'Layout & Structure', NULL, 'mdi-aspect-ratio', 'components.catalog.responsive.description', 'Aspect-ratio container that constrains its content to a fixed ratio using a sizer trick. Supports dimension overrides and standard spacing props.', NULL, NULL, 'origam-responsive', NULL, 'packages/ds/src/components/Responsive/OrigamResponsive.vue', 'origam', NULL, NULL, '/stories/?story=components-responsive--design', '/docs/components/Responsive/OrigamResponsive.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.responsive.a11y.container_note", "noteFallback": "OrigamResponsive is a pure layout container with no interactive role. Accessibility is owned by the content placed in the default slot."}, {"noteKey": "components.responsive.a11y.media_note", "noteFallback": "When wrapping an iframe or img, ensure the embedded element has appropriate title or alt attributes for screen readers."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "1.7778", "tokenPath": "--origam-responsive---aspect-ratio-default", "descriptionKey": "components.responsive.tokens.aspect_ratio_default", "descriptionFallback": "Default aspect ratio applied when no prop is set."}, {"type": "other", "value": "100%", "tokenPath": "--origam-responsive---max-width", "descriptionKey": "components.responsive.tokens.max_width", "descriptionFallback": "Default max-width of the container."}, {"type": "other", "value": "hidden", "tokenPath": "--origam-responsive---overflow", "descriptionKey": "components.responsive.tokens.overflow", "descriptionFallback": "Overflow mode — hidden clips content to the ratio box."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"440\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"40\" width=\"400\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__sizer (padding-block-end drives ratio)</text>\n  <rect x=\"40\" y=\"68\" width=\"400\" height=\"72\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"240\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-responsive\">\n  <!-- sizer: padding-block-end = (height / width) * 100% -->\n  <div class=\"origam-responsive__sizer\" />\n\n  <!-- additional slot (overlays, decorations) -->\n  <slot name=\"additional\" />\n\n  <!-- main content, absolutely fills the container -->\n  <div class=\"origam-responsive__content\">\n    <slot name=\"default\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-responsive", "num": 1, "descriptionKey": "components.responsive.anatomy.root", "descriptionFallback": "Root element. Flex container, overflow hidden. Receives dimension, padding, margin, border and rounded classes."}, {"cls": ".origam-responsive__sizer", "num": 2, "descriptionKey": "components.responsive.anatomy.sizer", "descriptionFallback": "Zero-height helper div. Its padding-block-end (set via useAspectRatio) forces the container to the correct ratio height."}, {"cls": ".origam-responsive__content", "num": 3, "descriptionKey": "components.responsive.anatomy.content", "descriptionFallback": "Absolutely positioned content area filling the ratio-locked space. Receives contentClass."}], "classes": [{"cls": "origam-responsive", "descriptionKey": "components.responsive.anatomy.root", "descriptionFallback": "Root block element."}, {"cls": "origam-responsive__sizer", "descriptionKey": "components.responsive.anatomy.sizer", "descriptionFallback": "Aspect-ratio sizer helper div."}, {"cls": "origam-responsive__content", "descriptionKey": "components.responsive.anatomy.content", "descriptionFallback": "Content area, absolutely positioned."}], "svgDesc": "Schematic of the Responsive component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamResponsive", "rootClass": "origam-responsive", "figcaption": "Anatomy of <code>&lt;origam-responsive&gt;</code> — 3 parts: root container ①, sizer div ② (drives padding-block-end aspect trick), and content div ③.", "svgViewBox": "0 0 480 180"}, "cssVars": [{"name": "--origam-responsive---aspect-ratio-default", "defaultValue": "16 / 9", "descriptionKey": "components.responsive.css_vars.aspect_ratio_default", "descriptionFallback": "Default aspect ratio when no aspectRatio prop is set."}, {"name": "--origam-responsive---overflow", "defaultValue": "hidden", "descriptionKey": "components.responsive.css_vars.overflow", "descriptionFallback": "Overflow applied to the root container. Hidden by default to clip content."}, {"name": "--origam-responsive---max-width", "defaultValue": "100%", "descriptionKey": "components.responsive.css_vars.max_width", "descriptionFallback": "Default max-width of the responsive container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.responsive.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.responsive.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.responsive.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.responsive.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.responsive.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.responsive.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "aspectRatio", "options": [{"label": "16/9", "value": "16/9"}, {"label": "4/3", "value": "4/3"}, {"label": "1/1", "value": "1"}, {"label": "3/4 (portrait)", "value": "3/4"}, {"label": "21/9 (ultrawide)", "value": "21/9"}], "labelKey": "components.responsive.playground.aspect_ratio", "defaultValue": "16/9", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.responsive.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "maxWidth", "options": [{"label": "(none)", "value": ""}, {"label": "320px", "value": "320px"}, {"label": "480px", "value": "480px"}, {"label": "640px", "value": "640px"}], "labelKey": "components.responsive.playground.max_width", "defaultValue": "", "labelFallback": "Max width"}]}, "previewVariants": [{"label": "16/9", "props": {"width": 280, "aspectRatio": "16/9"}, "slotContent": "16 : 9"}, {"label": "4/3", "props": {"width": 200, "aspectRatio": "4/3"}, "slotContent": "4 : 3"}, {"label": "1/1", "props": {"width": 160, "aspectRatio": "1"}, "slotContent": "1 : 1"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d42167ff-fd83-469b-8f48-7d0842629f61', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'slider-field-track', 'SliderFieldTrack', 'Form & Input', NULL, 'mdi-ray-start-end', 'components.catalog.slider_field_track.description', 'Internal track sub-component of SliderField. Renders the background rail, the fill bar and optional tick marks. Not intended for standalone use.', NULL, NULL, 'origam-slider-field-track', NULL, 'packages/ds/src/components/SliderField/OrigamSliderFieldTrack.vue', 'origam', NULL, NULL, '/stories/?story=components-slider-field--design', '/docs/components/SliderField/OrigamSliderField.html', 'slider-field', '{"a11y": {"notes": [{"noteKey": "components.slider_field_track.a11y.pointer_events", "noteFallback": "pointer-events: none is set on the root so the track never intercepts thumb interactions. All keyboard and pointer handling lives in the parent SliderField."}, {"noteKey": "components.slider_field_track.a11y.forced_colors", "noteFallback": "Under forced-colors (Windows High Contrast): the root receives a thin solid buttontext border, and background/fill use the highlight system color."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__track---height", "descriptionKey": "components.slider_field_track.tokens.height", "descriptionFallback": "Default track height / thickness."}, {"type": "color", "value": "var(--origam-color__surface---disabled)", "tokenPath": "--origam-slider-field__track---background-color", "descriptionKey": "components.slider_field_track.tokens.background_color", "descriptionFallback": "Rail background color."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-slider-field__track---border-radius", "descriptionKey": "components.slider_field_track.tokens.border_radius", "descriptionFallback": "Border radius of the track (pill shape)."}, {"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__tick---size", "descriptionKey": "components.slider_field_track.tokens.tick_size", "descriptionFallback": "Tick dot size token."}, {"type": "color", "value": "var(--origam-color__text---disabled)", "tokenPath": "--origam-slider-field__tick---background-color", "descriptionKey": "components.slider_field_track.tokens.tick_color", "descriptionFallback": "Tick dot color in the unfilled zone."}, {"type": "color", "value": "var(--origam-color__action--primary---fg)", "tokenPath": "--origam-slider-field__tick---background-color-active", "descriptionKey": "components.slider_field_track.tokens.tick_color_active", "descriptionFallback": "Tick dot color in the filled zone."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"88\" width=\"620\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, #d4c7e8)\"/>\n  <rect x=\"40\" y=\"88\" width=\"310\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"80\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"175\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__action--primary---fg, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"270\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__action--primary---fg, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"350\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"450\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"550\" cy=\"92\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"40\" cy=\"92\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"40\" y=\"96\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"70\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"450\" cy=\"75\" r=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"450\" y=\"79\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"40\" y=\"120\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">track root</text>\n  <text x=\"70\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">background</text>\n  <text x=\"200\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">fill (start→stop)</text>\n  <text x=\"450\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">tick marks</text>\n", "code": "<div class=\"origam-slider-field-track\">\n  <!-- background rail -->\n  <div class=\"origam-slider-field-track__background origam-slider-field-track__background--opacity\" />\n\n  <!-- fill bar (start → stop %) -->\n  <div class=\"origam-slider-field-track__fill\" />\n\n  <!-- tick marks (optional) -->\n  <div class=\"origam-slider-field-track__ticks origam-slider-field-track__ticks--always-show\">\n    <div class=\"origam-slider-field-track__tick origam-slider-field-track__tick--first\">\n      <!-- tick label via #item or #item.{index} slot -->\n      <div class=\"origam-slider-field-track__tick-label\">{{ tick.label }}</div>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-slider-field-track", "num": 1, "descriptionKey": "components.slider_field_track.anatomy.root", "descriptionFallback": "Root element. Position: relative, border-radius: 9999px, pointer-events: none. Size set via --origam-slider-field-track---size."}, {"cls": ".origam-slider-field-track__background", "num": 2, "descriptionKey": "components.slider_field_track.anatomy.background", "descriptionFallback": "Rail background bar. Spans 100% in the track axis. Opacity 0.38 when a fill color is active (--opacity modifier). Animated via slider-field__track---transition."}, {"cls": ".origam-slider-field-track__fill", "num": 3, "descriptionKey": "components.slider_field_track.anatomy.fill", "descriptionFallback": "Fill bar. Positioned from start% to stop% along the track axis using logical CSS properties."}, {"cls": ".origam-slider-field-track__ticks", "num": 4, "descriptionKey": "components.slider_field_track.anatomy.ticks", "descriptionFallback": "Tick container. Rendered only when showTicks is truthy and parsedTicks is non-empty. Children are .origam-slider-field-track__tick elements."}], "classes": [{"cls": "origam-slider-field-track", "descriptionKey": "components.slider_field_track.anatomy.root", "descriptionFallback": "Root track container."}, {"cls": "origam-slider-field-track__background", "descriptionKey": "components.slider_field_track.anatomy.background", "descriptionFallback": "Rail background. Full width/height of the track."}, {"cls": "origam-slider-field-track__background--opacity", "descriptionKey": "components.slider_field_track.anatomy.background_opacity", "descriptionFallback": "Applied when a fill color is active. Sets opacity to 0.38 on the background."}, {"cls": "origam-slider-field-track__fill", "descriptionKey": "components.slider_field_track.anatomy.fill", "descriptionFallback": "Fill bar positioned from start% to stop% along the track."}, {"cls": "origam-slider-field-track__ticks", "descriptionKey": "components.slider_field_track.anatomy.ticks", "descriptionFallback": "Container for tick mark elements."}, {"cls": "origam-slider-field-track__ticks--always-show", "descriptionKey": "components.slider_field_track.anatomy.ticks_always_show", "descriptionFallback": "Applied when showTicks=\"always\". Forces tick opacity to 1."}, {"cls": "origam-slider-field-track__tick", "descriptionKey": "components.slider_field_track.anatomy.tick", "descriptionFallback": "Individual tick dot. Size: tickSize × tickSize, centered on its position."}, {"cls": "origam-slider-field-track__tick--filled", "descriptionKey": "components.slider_field_track.anatomy.tick_filled", "descriptionFallback": "Applied when tick.position is within [start, stop]. Changes background color."}, {"cls": "origam-slider-field-track__tick--first", "descriptionKey": "components.slider_field_track.anatomy.tick_first", "descriptionFallback": "Applied to the first tick (value === min). Label transform is reset to none."}, {"cls": "origam-slider-field-track__tick--last", "descriptionKey": "components.slider_field_track.anatomy.tick_last", "descriptionFallback": "Applied to the last tick (value === max). Label translates −100% to align right."}, {"cls": "origam-slider-field-track__tick-label", "descriptionKey": "components.slider_field_track.anatomy.tick_label", "descriptionFallback": "Tick label text. position: absolute, white-space: nowrap, user-select: none."}], "svgDesc": "Schematic of the slider track with background, fill and tick layers.", "svgTitle": "Anatomy of OrigamSliderFieldTrack", "rootClass": "origam-slider-field-track", "figcaption": "A