INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f3a09ea6-5f6a-4317-98b2-55f1c65fb2c9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'slider-field', 'SliderField', 'Form & Input', NULL, 'mdi-tune-variant', 'components.catalog.slider_field.description', 'Range slider with thumb, track and tick marks. Supports range (dual-thumb), vertical orientation, and media-scrubber variants.', NULL, NULL, 'origam-slider-field', NULL, 'packages/ds/src/components/SliderField/OrigamSliderField.vue', 'origam', NULL, NULL, '/stories/?story=components-sliderfield--design', '/docs/components/SliderField/OrigamSliderField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.slider_field.a11y.range_note", "noteFallback": "The native <input type=\"range\"> owns keyboard and pointer math. aria-valuemin, aria-valuemax, aria-valuenow and aria-orientation are managed by the browser natively."}, {"noteKey": "components.slider_field.a11y.label_note", "noteFallback": "Pair with the label prop or an aria-label attribute to identify the slider purpose for screen readers."}, {"noteKey": "components.slider_field.a11y.range_dual_note", "noteFallback": "In range (dual-thumb) mode, each thumb is a separate <input type=\"range\">. Provide distinct aria-label values for the start and end thumbs."}], "roles": ["slider"], "keyboard": [{"key": "Arrow Left / Down", "actionKey": "components.slider_field.a11y.key_decrease", "actionFallback": "Decreases the value by one step."}, {"key": "Arrow Right / Up", "actionKey": "components.slider_field.a11y.key_increase", "actionFallback": "Increases the value by one step."}, {"key": "Home", "actionKey": "components.slider_field.a11y.key_home", "actionFallback": "Jumps to the minimum value."}, {"key": "End", "actionKey": "components.slider_field.a11y.key_end", "actionFallback": "Jumps to the maximum value."}, {"key": "Page Up / Page Down", "actionKey": "components.slider_field.a11y.key_page", "actionFallback": "Increments or decrements by 10% of the total range."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "4px", "tokenPath": "--origam-slider-field__track---height", "descriptionKey": "components.slider_field.tokens.track_height", "descriptionFallback": "Track rail height."}, {"type": "color", "value": "var(--origam-color__surface---disabled)", "tokenPath": "--origam-slider-field__track---background-color", "descriptionKey": "components.slider_field.tokens.track_bg", "descriptionFallback": "Unfilled rail color."}, {"type": "dimension", "value": "16px", "tokenPath": "--origam-slider-field__thumb---size", "descriptionKey": "components.slider_field.tokens.thumb_size", "descriptionFallback": "Thumb diameter."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-slider-field__thumb---background-color", "descriptionKey": "components.slider_field.tokens.thumb_bg", "descriptionFallback": "Thumb background."}, {"type": "number", "value": "1.25", "tokenPath": "--origam-slider-field__thumb---scale-hover", "descriptionKey": "components.slider_field.tokens.thumb_scale_hover", "descriptionFallback": "Thumb scale on hover."}, {"type": "number", "value": "var(--origam-opacity---32)", "tokenPath": "--origam-slider-field---opacity-disabled", "descriptionKey": "components.slider_field.tokens.opacity_disabled", "descriptionFallback": "Opacity when disabled."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"30\" width=\"644\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"110\" y=\"68\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Volume</text>\n  <rect x=\"100\" y=\"110\" width=\"500\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__surface---disabled, #e5e7eb)\"/>\n  <rect x=\"100\" y=\"110\" width=\"260\" height=\"8\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"360\" cy=\"114\" r=\"12\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <circle cx=\"140\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"220\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"300\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__action--primary---fg, #fff)\"/>\n  <circle cx=\"380\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"460\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"540\" cy=\"126\" r=\"4\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"36\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"66.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"260\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"260\" y=\"112.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"360\" y=\"104.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"300\" cy=\"135\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"300\" y=\"139.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"46\" y1=\"30\" x2=\"80\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"14\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-slider-field</text>\n", "code": "<!-- root: OrigamInput form chrome in \"field\" variant -->\n<div class=\"origam-slider-field\">\n  <!-- label slot (field variant) -->\n  <slot name=\"label\"><origam-label>{{ label }}</origam-label></slot>\n\n  <!-- track: rail + fill + ticks (OrigamSliderFieldTrack sub-component) -->\n  <div class=\"origam-slider-field__container\">\n    <origam-slider-field-track\n      :start=\"startPercent\"\n      :stop=\"stopPercent\"\n      :ticks=\"computedTicks\"\n    />\n    <!-- native <input type=\"range\"> (pointer math owner) -->\n    <input type=\"range\" :min=\"min\" :max=\"max\" :step=\"step\" />\n    <!-- thumb -->\n    <div class=\"origam-slider-field__thumb\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-slider-field", "num": 1, "descriptionKey": "components.slider_field.anatomy.root", "descriptionFallback": "Root container. Wraps inside OrigamInput chrome when variant=\"field\"."}, {"cls": ".origam-slider-field__label", "num": 2, "descriptionKey": "components.slider_field.anatomy.label", "descriptionFallback": "Label slot area. Rendered only in field variant."}, {"cls": ".origam-slider-field__fill", "num": 3, "descriptionKey": "components.slider_field.anatomy.fill", "descriptionFallback": "Active fill bar. Width/height proportional to modelValue between min and max."}, {"cls": ".origam-slider-field__thumb", "num": 4, "descriptionKey": "components.slider_field.anatomy.thumb", "descriptionFallback": "Draggable thumb. Scales on hover/active. Hides at rest when showThumbOnHoverOnly=true."}, {"cls": ".origam-slider-field__tick", "num": 5, "descriptionKey": "components.slider_field.anatomy.tick", "descriptionFallback": "Tick mark dots shown when showTicks is set. One dot per step increment."}], "classes": [{"cls": "origam-slider-field", "descriptionKey": "components.slider_field.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-slider-field__container", "descriptionKey": "components.slider_field.anatomy.container", "descriptionFallback": "Inner container holding track, native input and thumb."}, {"cls": "origam-slider-field__fill", "descriptionKey": "components.slider_field.anatomy.fill", "descriptionFallback": "Active fill from min to current value."}, {"cls": "origam-slider-field__thumb", "descriptionKey": "components.slider_field.anatomy.thumb", "descriptionFallback": "Draggable thumb element."}, {"cls": "origam-slider-field__tick", "descriptionKey": "components.slider_field.anatomy.tick", "descriptionFallback": "Tick mark dot."}], "svgDesc": "Schematic of the SliderField component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamSliderField", "rootClass": "origam-slider-field", "figcaption": "Anatomy of <code>&lt;origam-slider-field&gt;</code> — 5 internal parts: root ①, label ②, track-fill ③, thumb ④ and tick marks ⑤.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-slider-field---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.slider_field.css_vars.transition_duration", "descriptionFallback": "Transition duration for thumb scale and fill width animations."}, {"name": "--origam-slider-field__track---height", "defaultValue": "4px", "descriptionKey": "components.slider_field.css_vars.track_height", "descriptionFallback": "Track rail height (horizontal orientation)."}, {"name": "--origam-slider-field__track---background-color", "defaultValue": "{color.surface.disabled}", "descriptionKey": "components.slider_field.css_vars.track_bg", "descriptionFallback": "Unfilled track rail background color."}, {"name": "--origam-slider-field__track-fill---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.slider_field.css_vars.track_fill_bg", "descriptionFallback": "Active fill color. Overridden by color prop."}, {"name": "--origam-slider-field__thumb---size", "defaultValue": "16px", "descriptionKey": "components.slider_field.css_vars.thumb_size", "descriptionFallback": "Thumb diameter."}, {"name": "--origam-slider-field__thumb---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.slider_field.css_vars.thumb_bg", "descriptionFallback": "Thumb background color."}, {"name": "--origam-slider-field__thumb---scale-hover", "defaultValue": "1.25", "descriptionKey": "components.slider_field.css_vars.thumb_scale_hover", "descriptionFallback": "Thumb scale on hover."}, {"name": "--origam-slider-field---opacity-disabled", "defaultValue": "{opacity.32}", "descriptionKey": "components.slider_field.css_vars.opacity_disabled", "descriptionFallback": "Opacity when disabled."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.slider_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.slider_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.slider_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.slider_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.slider_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.slider_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.slider_field.playground.model_value", "defaultValue": 50, "labelFallback": "Value"}, {"kind": "number", "prop": "min", "labelKey": "components.slider_field.playground.min", "defaultValue": 0, "labelFallback": "Min"}, {"kind": "number", "prop": "max", "labelKey": "components.slider_field.playground.max", "defaultValue": 100, "labelFallback": "Max"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}], "labelKey": "components.slider_field.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.slider_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.slider_field.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}, {"kind": "switch", "prop": "error", "labelKey": "components.slider_field.playground.error", "defaultValue": false, "labelFallback": "Error"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
