INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('155e759d-5aad-40f5-ac82-2ade0f8f87b2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'component', 'snackbar-item', 'SnackbarItem', 'Feedback & Status', NULL, 'mdi-message-badge-outline', 'components.catalog.snackbar_item.description', 'Pure visual layer for a single toast notification. Handles intent theming, icon, title, message, action buttons and the dismiss control.', NULL, NULL, 'origam-snackbar-item', NULL, 'packages/ds/src/components/Snackbar/OrigamSnackbarItem.vue', 'origam', NULL, NULL, '/stories/?story=components-snackbar--design', '/docs/components/Snackbar/OrigamSnackbar.html', 'snackbar', '{"a11y": {"notes": [{"noteKey": "components.snackbar_item.a11y.live_note", "noteFallback": "aria-live is set to \"assertive\" for warning and danger intents, \"polite\" for others. The value can be overridden via the ariaLive prop."}, {"noteKey": "components.snackbar_item.a11y.atomic_note", "noteFallback": "aria-atomic=\"true\" ensures screen readers read the entire item when it is updated."}, {"noteKey": "components.snackbar_item.a11y.dismiss_note", "noteFallback": "The dismiss button carries aria-label=\"Dismiss notification\" (or the dismissLabel prop value). It is keyboard-focusable and activated via Enter/Space."}, {"noteKey": "components.snackbar_item.a11y.contrast_note", "noteFallback": "The v-contrast directive ensures foreground and background token combinations meet WCAG AA contrast ratios for each intent."}], "roles": ["status", "alert"], "keyboard": [{"key": "Tab", "actionKey": "components.snackbar_item.a11y.key_tab", "actionFallback": "Moves foc