de?: string[]) => Partial<T>", "descriptionKey": "components.tab.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "toggle", "type": "() => void", "descriptionKey": "components.tab.exposed.toggle", "descriptionFallback": "Toggles the selected state of this tab in the group."}, {"name": "select", "type": "(value: boolean) => void", "descriptionKey": "components.tab.exposed.select", "descriptionFallback": "Programmatically selects (true) or deselects (false) this tab."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed tab styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tab.playground.text", "defaultValue": "Tab label", "labelFallback": "Label text"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-magnify", "value": "mdi-magnify"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.tab.playground.icon", "defaultValue": "", "labelFallback": "Leading icon"}, {"kind": "select", "prop": "appendIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-close", "value": "mdi-close"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"label": "mdi-bell", "value": "mdi-bell"}], "labelKey": "components.tab.playground.append_icon", "defaultValue": "", "labelFallback": "Trailing icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.tab.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": ""}, "previewVariants": [{"label": "default", "props": {"text": "Tab", "value": "a"}}, {"label": "with icon", "props": {"icon": "mdi-magnify", "text": "Search", "value": "b"}}, {"label": "disabled", "props": {"text": "Disabled", "value": "c", "disabled": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
