INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8b78efd2-4b9f-428d-a37b-2a01075f593b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'composable', 'use-active', 'useActive', NULL, 'Commons', 'mdi-cursor-default-click', '', 'Tracks the active (pressed / selected) state of a host element with full v-model integration. Accepts boolean, forced-on (true) and IActiveState config objects with style overrides. The `prop` argument lets callers bind non-`active` keys (e.g. `modelValue`).', NULL, 'function useActive(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6e2f62ed-71c4-428e-a0b6-845db3aed0a6', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'composable', 'use-adjacent', 'useAdjacent', NULL, 'Commons', 'mdi-arrow-expand-horizontal', '', 'Resolve the presence of prepend and append slots/icons for a component. Exposes computed flags (hasPrepend, hasAppend) that combine both the slot content and the icon/avatar props, plus click-event emitters for the clickable prepend/append areas. A companion composable useAdjacentInner handles the inner prepend/append surface (inside an input field).', NULL, 'function useAdjacent(
