INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2217158c-11c4-4041-8db1-e702275d5101', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'composable', 'use-defaults', 'useDefaults', NULL, 'Commons', 'mdi-tune-variant', '', 'Component-side hook for the OrigamDefaultsProvider system. Returns a Proxy over the component''s own props that resolves each value through a four-level chain: explicitly passed prop → component-specific defaults from the closest provider → global defaults from the closest provider → withDefaults() value.', NULL, 'function useDefaults<T extends Record<string, any>>(
