INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('012d1524-9201-47b4-8586-b7d37b7a1122', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'composable', 'use-throttle', 'useThrottleFn', NULL, 'Commons', 'mdi-timer-outline', '', 'Wraps a function so it executes at most once per wait milliseconds. The first call fires immediately; subsequent calls within the wait window are silently discarded. After the window expires the next call fires again immediately. Designed for scroll, resize, and pointer-move handlers where firing on every frame would be prohibitively expensive.', NULL, 'function useThrottleFn<T extends any[], R = void>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d6dd2206-5f64-46ad-8233-a2ef5284e31d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'composable', 'use-toggle-scope', 'useToggleScope', NULL, 'Commons', 'mdi-toggle-switch-outline', '', 'Conditionally activates a Vue effectScope driven by a reactive boolean source. When the source turns true the scope starts (running the provided callback inside it); when it turns false the scope is stopped and discarded. The scope is also stopped on parent scope dispose.', NULL, 'function useToggleScope(
