INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8174f6e-70fa-4838-b2f3-20d286c937cc', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ec98abc3-f6cf-4c73-b18f-b4ab7f581ff5', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e8682eab-0c82-4b4f-9793-48f55c53084a', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ec98abc3-f6cf-4c73-b18f-b4ab7f581ff5', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('488e7051-05de-4e86-b00b-45aae1e27da2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ec98abc3-f6cf-4c73-b18f-b4ab7f581ff5', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cee30407-65f8-4b6e-8c1c-d9bf976cd57d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '8b78efd2-4b9f-428d-a37b-2a01075f593b', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('228d1e1c-a12c-410c-8cf1-2a861c52cc50', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '8b78efd2-4b9f-428d-a37b-2a01075f593b', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('673bf0ef-6602-4629-adf6-f5f77be89f90', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '8b78efd2-4b9f-428d-a37b-2a01075f593b', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('44600577-1957-4ae3-ba2a-f71c677170fe', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6e2f62ed-71c4-428e-a0b6-845db3aed0a6', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cf64a7c5-f34e-4516-845f-efabcdf3f362', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6e2f62ed-71c4-428e-a0b6-845db3aed0a6', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9feb1aee-803b-46e8-a313-e8c3f6c190f1', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6e2f62ed-71c4-428e-a0b6-845db3aed0a6', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b84d2670-9072-4ef2-aad3-f02e2b000d6e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '9775e33b-3de7-4fd6-9195-39e956510c49', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35b85e8e-802a-4338-8f2b-cc0340504703', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '40d4c484-0fde-4af8-aae4-faa85159d0cb', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b7630a7-e378-41a6-94b1-2d12721a9afa', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ebe0a1bc-acc9-40ef-889e-f45b8a5f7ccb', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dec9777f-130c-4f3f-b40f-293b77a34d26', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'bcd79edc-8110-41ff-b41c-36305fe64168', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
