INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63b44597-383c-4f48-bba4-efb0d2524943', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd7a3f51d-b948-4f55-baac-1c3c3602e0e9', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8efecc8c-9d40-4a72-8b1e-37060f76b5e6', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd7a3f51d-b948-4f55-baac-1c3c3602e0e9', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da25fc97-13b8-41ff-a114-e7347fc38e93', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd7a3f51d-b948-4f55-baac-1c3c3602e0e9', 'setCurrentDate', '(date: Date) => void', false, NULL, '', 'Optional callback invoked by navigate(). Bind to a v-model:currentDate setter. If omitted, navigation calls have no effect on the parent state.', 2, false, NULL, NULL);
