INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('84dc7d00-717b-4c50-b975-173a3c44216d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3012c2b0-9ad1-4797-9ca6-08ef962d976b', 'link', 'IUseLink', true, NULL, '', 'The link object returned by useRouter/useLink. Exposes isLink (whether an href/to prop is present) and isActive (whether the current route matches the link target). Watched by the composable to trigger selection.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c89c9d5c-1f10-4e30-9aa6-6bc68b4d4c70', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3012c2b0-9ad1-4797-9ca6-08ef962d976b', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a9f1f9d-c919-4847-84e6-1561e064da67', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7da5e749-66c9-48b9-ac83-d03a0febac17', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '43b32052-77a7-4570-81b5-d4653f42e6e7', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('14d45759-4e8a-471a-8acb-bce83eaf368d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '43b32052-77a7-4570-81b5-d4653f42e6e7', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8e692c8-60c6-4513-bdcc-b068f6c750f6', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c22588c2-f40c-4b04-9ed0-1828001be34c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '2cc70ffe-bc14-4726-ad72-b7430493b2d2', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6561975a-efae-4a87-a21b-67f7b51366ea', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cd3272c1-9cf3-4e12-bab2-7463ea2c2f2e', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
