INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f0bdb6d-08fa-4487-a6fa-17b10b7aca63', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bce2996e-67cb-43bb-b92a-5427899be257', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81a8d625-848e-4286-8c80-cea0ae759255', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7bee893-1c9a-42d8-a641-d2bb940eb178', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1e12dff7-6f12-48db-afb4-dc38fcbcf99d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1c2cee0-4719-4b67-bb74-83612113fc27', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'c45598da-ae58-4afc-af57-6e322118181b', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('868e5264-50a5-405c-9f5d-0dda735552ac', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('190635ae-d125-4ba9-8905-1331f9473480', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fa69289e-7885-4771-85b7-9a8ceda861f3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e700d361-b02d-4e89-864f-c2ba57ddd7fc', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('263acfb6-8d3c-4f91-b93a-6e57dfa8e84c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aaeb0477-717b-4e25-b5e9-fda3e7e91cec', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cff2ed17-06d5-49d8-9ff8-b90356b671aa', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a2bc2c4e-dbcf-47a5-85ae-3a6aa8b7f5fc', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cff2ed17-06d5-49d8-9ff8-b90356b671aa', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e5a06b2-b604-4ce8-9a1c-131ae39f6b0a', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63eae55e-5b07-435c-9dda-7ac99bee12ec', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96d3def7-1fc1-4347-b900-13f02d095f81', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'e9460ffc-5a79-49c3-9f11-c422a1b4d830', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
