INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('020f22b1-97e0-4d3b-bf50-da18e20d7ca1', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '62ceae34-192e-4caf-871d-81d34c575191', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
