INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('897c365a-3168-49ed-9531-665753c1f683', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '89757c0c-5293-4277-8282-43080a049189', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e639c7c7-d8ac-48e6-9240-2c2767d8106d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '89757c0c-5293-4277-8282-43080a049189', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bf5d0945-8bdf-42c2-90a0-2c916a5f1ce3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c6f7033b-5d24-4bd8-8f63-f845cfb1d904', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f458cdae-24ee-4f17-acf6-41519bffe2b2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', 'defaultValue', 'MaybeRefOrGetter<Props[Prop] | undefined>', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('727be50f-b568-4d7d-b7b3-ea87519896e3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b61e3eb0-0863-4502-b990-155e4f32225c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', 'transformOut', '(value: Inner) => Props[Prop]', false, '(v: Inner) => v as Props[Prop]', '', 'Optional inverse transform applied before emitting `update:prop`. Pairs with transformIn to keep the internal representation separate from the public API value.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c22c1f9f-032b-4134-9ff5-dcbc4e90ebe5', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '04b8a236-b4f7-460f-859a-c5a3428d62ab', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4c763d9-73b2-4dcd-9085-a71a659924e9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ef843d53-3cb3-4133-bbf0-ed92da842464', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c5c70cc-85c4-48e3-85f6-117091a9a1b2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'ef843d53-3cb3-4133-bbf0-ed92da842464', 'options', 'IUseWaveformOptions', false, '{}', '', 'Optional: `bins` (number of peaks to produce, default 200) and `crossOrigin` ("use-credentials" | undefined) for the fetch credentials policy.', 1, false, NULL, NULL);
