INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('83491aaa-baa9-4f7a-81c0-7b36cb48d064', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'fca5ad3c-4c49-4575-bdd3-f7eb59b6bbbf', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
