INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5913b66-f492-4fca-a286-5f095cea18a1', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'fca5ad3c-4c49-4575-bdd3-f7eb59b6bbbf', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
