INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57a9014b-dc65-40b4-ae9b-7d07bf21469d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'lang', 'TCodeLangOpen', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e76d5b1-92de-42ab-ba6a-448ef634f3bd', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3dad83c6-c9b0-4f7a-9aa7-19e5c9c9b1d7', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a09365f7-e418-4103-b6c9-7a593bf7028c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0e8596c3-d675-4472-bf13-7b37bc2877a3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('89a6aaa6-a7fb-4e03-855f-7d4409064604', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ada0b9b2-8aca-4734-9ca8-439fefb9a0b3', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b0affbb-c8e5-474f-ab60-b29b393e679f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b603e1ef-cf56-4bd2-8aba-d8ea45940ade', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02fa9d52-abd0-44e4-9951-7f6d8b987c53', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a05b8bcf-0e50-4a39-9354-de9c1eba92d9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '65eb34a6-64b4-487b-9b6b-a0983090bf12', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
