INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5da7d872-5399-438b-a340-df55bddc195f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a3e8d5a-51ec-4757-a6ff-f969c580bc9b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92a95793-f32e-4ca8-9c1a-7a45011a0c94', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8e381589-ce8b-43e1-8f46-dfd2a5703dc7', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('33ba753d-5c16-4eb2-b55b-72dae10cee9e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d37bc193-0b4a-4f48-829e-78a8a44be4e0', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38838456-8f6b-4ca3-9f2c-2004ddc83dbd', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72887ceb-8086-43d5-8fb8-3d91931c80e2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4bbcd374-c8b5-4203-8950-c8826c199d6c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16cc36c5-87ee-49db-8145-5f358dafd60c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d34247c-79cf-4f2a-962c-8d9f62177f07', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'abe6e2dc-5211-4f53-908e-ce3a6bec3036', 'roundedEndStart', 'boolean | number | string', NULL, NULL, NULL, false, NULL, NULL, NULL, 79, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dcaae494-9aa7-45f3-a652-0c90718d9d72', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f1fdf1e-aad6-445d-9cc7-5a171564ba88', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21b55f21-ca0e-479a-a738-0b9fa9950c4f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'showShuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a8acd66c-b429-4047-8833-bfdeec5409de', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'loopMode', 'TAudioLoopMode', '', 'primitive', NULL, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('01e6bf22-5fc9-4204-ace4-bcf8f47a7414', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', 'd166590d-46b8-4f4a-a94d-d85c363abca5', 'shuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
