INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('95406d61-4931-4b04-805c-ec41b68b99bc', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4c70bd3c-527a-4e52-9c61-77323c04a9c2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'min', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.min.description', 'Lower bound of the value range.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1f4197f-29b9-4396-b16d-92cd17f2d145', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'max', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.max.description', 'Upper bound of the value range. Required to compute the thumb position. Passing 0 or any value <= min freezes the scrubber at the start.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f7d29d0f-ca77-4c6a-a4f1-7f5239ed66fb', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bd37e1a-7c85-4104-b2ef-7a36a6bf774c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'buffered', 'number', '', 'primitive', NULL, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45b29ad4-3e01-4c77-8d2d-d61a714d6796', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06b23830-33d9-45ae-9e5d-57c67ff0cb48', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0cac278f-d553-4a2e-97c3-b99bd3b20d21', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('41788a32-17c8-4989-994c-551cb4c77a57', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'showHoverTooltip', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_hover_tooltip.description', 'Shows a tooltip above the cursor (horizontal only) reflecting the hovered value. Content can be overridden via the #tooltip slot.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('64d5dd92-5d0d-4dee-9a3c-ff06dacd1095', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'formatHoverTooltip', '(value: number) => string', '', 'primitive', NULL, false, 'value => String(value)', 'components.media_scrubber.props.format_hover_tooltip.description', 'Formatter for the default hover tooltip label. Receives the hovered value, returns the string to render.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('504a520c-5643-44c0-8e74-efb11d899e3d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:58.933458+00', '995afe89-2f20-4353-b102-94a7196af1af', 'ariaLabel', 'string', '', 'primitive', NULL, false, '—', 'components.media_scrubber.props.aria_label.description', 'Required accessibility label read by screen readers when the scrubber gains focus. Always pass a translated string here.', 10, false, NULL, NULL);
