INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd66a5a5-24a4-42bc-a898-9c253841dc3f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd7a3f51d-b948-4f55-baac-1c3c3602e0e9', 'positionEvent', '(event: IEvent, dayStart: Date, pxPerMin: number) => { top: number; height: number } | null', '', 'Compute top and height pixel values for an event on the day/week timeline. pxPerMin is the CSS-driven slot height divided by slotDuration so the layout stays responsive without JS ResizeObservers.', 8, false, NULL, NULL);
