INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aed57864-6420-45ab-8b12-87898d0ed80c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '9716fcde-8821-44a3-80e4-903e91a2ea1b', 'legend', 'ComputedRef<Array<IChartLegendItem>>', '', 'Pre-resolved legend entries. Single-series pie/donut exposes one entry per slice (category); all other types expose one entry per series.', 5, false, NULL, NULL);
