INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d71d1f03-21ef-48cf-9bf6-20fb51f75802', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75c70235-250a-42a1-a26c-5b1c2196334e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('301f88ca-2b50-464a-9925-ea8005313a55', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96c9a4a0-b27e-4b25-a2d1-fed97b0ada5e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e1358bc7-e3c0-49ea-b2f4-716de97989e2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db33c594-c365-4361-b11e-ddfc2a5cc628', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'fda1220d-62c6-4e13-bc24-6191a06e234d', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('857f0f19-87a3-414c-9014-6829cc0dbafe', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '43b32052-77a7-4570-81b5-d4653f42e6e7', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ed7b4526-1080-4080-bb33-f845d795ced7', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '43b32052-77a7-4570-81b5-d4653f42e6e7', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6becb72f-cae8-4fa2-b464-51217db2128e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('af089912-ab1e-4917-8bf9-2947f6233679', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('969245b6-5c9f-4828-83b7-4f4a2b6b8f91', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('af449b46-62eb-43ef-aad6-be520beb75e4', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1c8b140-0568-483a-ba1c-88fd222339e1', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'a31c04ed-66c5-473f-b88d-c36ea47fe53d', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5d306b2-1afa-406b-95ec-d7d944e44b56', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '2cc70ffe-bc14-4726-ad72-b7430493b2d2', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('58107f3f-b9fa-4362-b785-2cf14eba292d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '2cc70ffe-bc14-4726-ad72-b7430493b2d2', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('858176bf-9f7c-41bb-a46e-cd4025d00649', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '2cc70ffe-bc14-4726-ad72-b7430493b2d2', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e616cc6-074e-4226-bde1-8c6c92be3b8b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '2cc70ffe-bc14-4726-ad72-b7430493b2d2', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('77f3301c-d6cc-4294-8dbb-61641ad9f7f4', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cd3272c1-9cf3-4e12-bab2-7463ea2c2f2e', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('968206df-e8b2-4391-9c77-767adbc3f194', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cd3272c1-9cf3-4e12-bab2-7463ea2c2f2e', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('be26ccd7-d7cb-49cf-8c32-c18e80578ccb', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cd3272c1-9cf3-4e12-bab2-7463ea2c2f2e', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('397c5944-7018-492e-b35f-920b42583d8b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'cd3272c1-9cf3-4e12-bab2-7463ea2c2f2e', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9bb78009-b4d0-4832-8c19-8e21b2d0a9d9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '75316244-31a6-4a7f-a818-c7da4205ac6f', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d279cf58-1684-416b-bd1a-ac51a4d51d5a', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '75316244-31a6-4a7f-a818-c7da4205ac6f', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a10192c4-0ba4-4a06-a77e-6659c26aad9e', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '75316244-31a6-4a7f-a818-c7da4205ac6f', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3aeb2b68-4714-4d5a-a8ca-1474de0eb992', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '456ee2ff-53d7-4b01-a2d0-9178d73d0090', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d42297a5-5ba9-416c-8c5e-bf85c4c4e9f2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '456ee2ff-53d7-4b01-a2d0-9178d73d0090', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4940dcd6-bf72-4b08-822c-b09bac015141', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '95b72e50-fa92-463a-a8fb-203c4c8be534', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('df3e6385-09a5-4abd-b83c-cd655f12b0d9', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('11838705-229f-4a90-8669-48519c933132', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('841a8cae-23ef-4d19-b9c2-44323620069d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '260cb64d-d6d1-47de-b8c6-18d677518b41', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb90cd6f-ed97-49e0-be3d-22c1bed98905', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4c19579-09c9-4675-93ba-0c480d21531d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8b16519-10cd-4bae-a4aa-2f70406e6fb4', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47dcbdb7-b48d-4415-b705-d03be99eb8c2', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7a636d41-6100-4809-a3a3-df77af5c4101', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('749d56ff-8ab5-4cc8-ac74-3f60208a6a9b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd396e61-a5b3-4638-8258-6546245ee77c', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3e671db5-d107-47a7-8a94-bd4f46dbe640', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54ca9c50-e904-4f70-a093-800ca8d99257', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('beb8ad43-5033-4efb-b4cd-be27c1534e32', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6bd03e1f-b392-4eb5-a9f1-c1cd0b6fd1cf', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('067eda8c-afd1-4fbc-84b2-37441ca87d40', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4eafe9a7-16a2-4c28-bc52-70c9a36a9867', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'd052e9f4-c2f4-4475-9780-03869c8efe40', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('26a065fa-4666-4df8-bf11-fd9553cf9f2d', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'e9460ffc-5a79-49c3-9f11-c422a1b4d830', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2f6e6a2-a75c-4024-9659-713cbd1ba396', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', 'e9460ffc-5a79-49c3-9f11-c422a1b4d830', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f39d78a7-d05e-4b9b-9523-df1a78dfa9cb', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '62ceae34-192e-4caf-871d-81d34c575191', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96a4d23c-57b5-4474-a23e-18f2c6d0d9ab', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '62ceae34-192e-4caf-871d-81d34c575191', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75144e1c-4d8b-45f8-8415-c8da17780935', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '62ceae34-192e-4caf-871d-81d34c575191', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4de81011-60e8-4b21-97a4-478e0af7c483', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '62ceae34-192e-4caf-871d-81d34c575191', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('90c02ea4-1c03-48c0-aa6e-a1a3920959ab', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '04960239-2ee1-4c8f-a4ec-860dedee4732', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c6967b95-f3f1-4c63-934a-206abf4bee48', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('330ab5f3-82a4-40c7-be46-785033e54268', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('824042eb-edea-4534-8949-6768fb8bf038', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ec13280-7c6d-4dbf-8572-928b37498f03', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c5565f3-5b01-475a-b1d3-1764957637ca', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2e895c26-6bb7-4390-88a0-264d7e9c9e67', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6d0327ba-ec09-4585-a2e1-7702dba0e757', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f7d33e32-bc98-4260-90e9-9703f3d37079', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '3efe53b9-00c1-4fb2-9481-c5b60d2254dd', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
