INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ddd83518-e4c5-4bea-9b8e-5835d4f9c58f', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '89757c0c-5293-4277-8282-43080a049189', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
