INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('31e9e63a-4f92-46fb-9997-9365e98018f1', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '89757c0c-5293-4277-8282-43080a049189', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bef5af84-c74a-4e0c-be99-94bacd8f4016', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '529e89c7-2b9f-45b7-b261-cbf481f4cb11', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
