INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5ebdfd1-056f-4db2-bfd4-85955bff3567', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '04b8a236-b4f7-460f-859a-c5a3428d62ab', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
