INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c6e57d83-1593-45fc-9535-766eb200861b', '2026-10-29 00:51:30.999304+00', '2026-10-29 00:51:30.999304+00', '6abcb5e5-009a-4565-b2ef-885ad87fc144', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
